------------------------------------
--- Localization Functions
--- LANG()         → multilingual with {lang} tags (broadcasts, buttons, tooltips)
--- LANG_NOTAGS()  → English-only plain text (XML UI <Text> elements)
--- LANG_TABLE()   → returns {en=..., ko=...} table (intermediate use in complex concatenations)
--- LANG_CALL()    → wrapper for sub-scripts via Global.call("LANG_CALL", {entry, ...})
--- LANG_NOTAGS_CALL() → wrapper for sub-scripts via Global.call("LANG_NOTAGS_CALL", {entry, ...})
------------------------------------

--- LANG(entry, ...) — Multilingual string formatting with TTS language tags.
--- entry is a STRINGS table (e.g. LANG(STRINGS.HELLO)).
--- Formats each language independently, then combines with TTS language tags:
--- {en}English{ko}한국어{zh-CN}中文 — TTS auto-selects per client language.
--- Use with broadcastToAll / broadcastToColor / setNotes / button labels / tooltips.
function LANG(entry, ...)
  if type(entry) == "table" then
    local argCount = select("#", ...)
    local langCount = 0
    for _ in pairs(entry) do langCount = langCount + 1 end
    if langCount <= 1 then
      local text = entry.en or ""
      if argCount > 0 then
        local resolved = {}
        for i = 1, argCount do
          local arg = select(i, ...)
          resolved[i] = type(arg) == "table" and (arg.en or "") or arg
        end
        text = string.format(text, table.unpack(resolved, 1, argCount))
      end
      return text
    end
    local parts = {}
    if entry.en then
      local text = entry.en
      if argCount > 0 then
        local resolved = {}
        for i = 1, argCount do
          local arg = select(i, ...)
          resolved[i] = type(arg) == "table" and (arg.en or "") or arg
        end
        text = string.format(text, table.unpack(resolved, 1, argCount))
      end
      table.insert(parts, "{en}" .. text)
    end
    for lang, template in pairs(entry) do
      if lang ~= "en" then
        local text = template
        if argCount > 0 then
          local resolved = {}
          for i = 1, argCount do
            local arg = select(i, ...)
            resolved[i] = type(arg) == "table" and (arg[lang] or arg.en or "") or arg
          end
          text = string.format(text, table.unpack(resolved, 1, argCount))
        end
        table.insert(parts, "{" .. lang .. "}" .. text)
      end
    end
    return table.concat(parts)
  end
  -- Plain string (no translation)
  if select("#", ...) > 0 then
    local argCount = select("#", ...)
    local resolved = {}
    for i = 1, argCount do
      local arg = select(i, ...)
      resolved[i] = type(arg) == "table" and (arg.en or "") or arg
    end
    return string.format(entry, table.unpack(resolved, 1, argCount))
  end
  return entry
end

--- LANG_NOTAGS(entry, ...) — Plain English output, no {lang} tags.
--- entry is a STRINGS table directly (e.g. STRINGS.BTN_MODE), NOT a key string.
--- Table args are resolved to their .en value.
--- Use for XML UI <Text> and any context that does NOT support {lang} tags.
function LANG_NOTAGS(entry, ...)
  if type(entry) == "string" then
    -- plain string, use as-is
  elseif type(entry) == "table" then
    -- prefer .en, fall back to first available entry
    entry = entry.en or next(entry) and entry[next(entry)] or ""
  else
    entry = ""
  end
  if select("#", ...) > 0 then
    local argCount = select("#", ...)
    local resolved = {}
    for i = 1, argCount do
      local arg = select(i, ...)
      if type(arg) == "table" then
        resolved[i] = arg.en or next(arg) and arg[next(arg)] or ""
      else
        resolved[i] = arg
      end
    end
    return string.format(entry, table.unpack(resolved, 1, argCount))
  end
  return entry
end

--- LANG_TABLE(entry, ...) — Formats a STRINGS entry with arguments per language.
--- Returns a new STRINGS-like table { en = "formatted", ko = "formatted", ... }.
--- Use when building multilingual labels from format patterns outside of LANG().
function LANG_TABLE(entry, ...)
  local result = {}
  local args = { ... }
  for lang, fmt in pairs(entry) do
    result[lang] = string.format(fmt, table.unpack(args))
  end
  return result
end

--- LANG_CALL(params) — Wrapper for Global.call from sub-scripts.
--- params is an array: {entry, arg1, arg2, ...}
--- Unpacks and forwards to LANG().
function LANG_CALL(params)
  return LANG(table.unpack(params))
end

--- LANG_NOTAGS_CALL(params) — Wrapper for Global.call from sub-scripts.
--- params is an array: {entry, arg1, arg2, ...}
--- Unpacks and forwards to LANG_NOTAGS().
function LANG_NOTAGS_CALL(params)
  return LANG_NOTAGS(table.unpack(params))
end

