------------------------------------
--- Utility: Test Player Hand Dealing
------------------------------------
-- Deals cards to test players' top hand positions (deck.deal only reaches real seated players).
function dealTestPlayerCards(drawCount)
  if not testPlayerSet then return end
  refreshDeckReference()
  if not deck then return end
  for _, color in ipairs(SEAT_ORDER) do
    if testPlayerSet[color] and not (Player[color] and Player[color].seated) then
      if playerParameters[color] and playerParameters[color].topHandObj then
        for i = 1, drawCount do
          refreshDeckReference()
          if not deck then return end
          deck.takeObject({
            position = playerParameters[color].topHandObj.getPosition(),
            rotation = { 0, 0, 0 },
            smooth = false
          })
        end
      end
    end
  end
end

------------------------------------
--- Utility: TwoHand Bot Dealing
------------------------------------
function dealBotHandCards(drawCount)
  if not FLAGS.TwoHand then return end
  refreshDeckReference()
  if not deck then return end
  for _, playerColor in ipairs(getSeatedPlayers()) do
    if playerParameters[playerColor].botHandObj then
      for i = 1, drawCount do
        deck.takeObject({
          position = playerParameters[playerColor].botHandObj.getPosition(),
          rotation = { 0, 0, 0 },
          smooth = false
        })
      end
    end
  end
end

