function applyHandRankLabels(playerColor, playerParams, topLabel, botLabel)
  if playerParams.topHandRankObj then
    playerParams.topHandRankObj.editButton({ index = 0, label = topLabel or "" })
  end
  if playerParams.botHandRankObj then
    if FLAGS['TwoHand'] then
      playerParams.botHandRankObj.editButton({ index = 0, label = botLabel or "" })
    else
      playerParams.botHandRankObj.editButton({ index = 0, label = "" })
    end
  end
end

