------------------------------------
--- Utility: Deck & Related Tile Positioning
------------------------------------
-- Moves the deck tile, script zone, discard tile, and hand rank reference to a new base position.
-- Used in communityCreateTiles, communityCleanUp, and cleanUp.
function positionDeckAndRelatedTiles(basePos)
  if deckTile then
    deckTile.setPosition({ x = basePos.x, y = basePos.y, z = basePos.z })
  end
  if scriptZoneDeck then
    local zonePos = scriptZoneDeck.getPosition()
    scriptZoneDeck.setPosition({ x = basePos.x, y = zonePos.y, z = basePos.z })
  end
  if cardDiscardTileObj then
    cardDiscardTileObj.setPosition({
      x = basePos.x + cardDiscardTilePositionOffset.x,
      y = basePos.y + cardDiscardTilePositionOffset.y,
      z = basePos.z + cardDiscardTilePositionOffset.z
    })
    if deckTile then
      cardDiscardTileObj.setRotation(deckTile.getRotation())
    end
  end
  if handRankReferenceObj then
    handRankReferenceObj.setPosition({
      x = basePos.x + handRankReferencePositionOffset.x,
      y = basePos.y + handRankReferencePositionOffset.y,
      z = basePos.z + handRankReferencePositionOffset.z
    })
  end
end

------------------------------------
--- Utility: Chip Change Indicator
------------------------------------
-- Builds a BB Code change indicator string comparing current vs previous chip star values.
-- Returns formatted string with colored arrow/dash/dot, or empty string if no previous round.
function buildChipChangeIndicator(diff, hasPrevValue, hasPrevRound, extraSpace)
  if hasPrevRound and hasPrevValue then
    if diff > 0 then
      return "  [" .. INDICATOR_COLORS.up .. "]▲" .. diff
    elseif diff < 0 then
      return "  [" .. INDICATOR_COLORS.down .. "]▼" .. math.abs(diff)
    else
      return (extraSpace and "   " or "  ") .. "[" .. INDICATOR_COLORS.same .. "]─"
    end
  elseif hasPrevRound then
    return "  [" .. INDICATOR_COLORS.new .. "]●"
  end
  return ""
end

