-- Returns a list of non-nil script zone objects for a player (top and bot).
function getPlayerScriptZones(params)
  local zones = {}
  if params.topScriptZoneObj then table.insert(zones, params.topScriptZoneObj) end
  if params.botScriptZoneObj then table.insert(zones, params.botScriptZoneObj) end
  return zones
end

