-- Hand Rank Registry (single source of truth)
-- Order = best → worst. Priority is derived from position.
-- rainbow = true means the rank only exists when Grinding Gears (challenge 41) is active.
-------------------------------
HAND_RANKS = {
  { code = "RF", label = STRINGS.RANK_ROYAL_FLUSH,      rainbow = false },
  { code = "5s", label = STRINGS.RANK_FIVE_OF_A_KIND,   rainbow = false },
  { code = "SF", label = STRINGS.RANK_STRAIGHT_FLUSH,   rainbow = false },
  { code = "SR", label = STRINGS.RANK_STRAIGHT_RAINBOW, rainbow = true },
  { code = "4s", label = STRINGS.RANK_FOUR_OF_A_KIND,   rainbow = false },
  { code = "FH", label = STRINGS.RANK_FULL_HOUSE,       rainbow = false },
  { code = "FL", label = STRINGS.RANK_FLUSH,            rainbow = false },
  { code = "ST", label = STRINGS.RANK_STRAIGHT,         rainbow = false },
  { code = "3s", label = STRINGS.RANK_THREE_OF_A_KIND,  rainbow = false },
  { code = "RB", label = STRINGS.RANK_RAINBOW,          rainbow = true },
  { code = "2p", label = STRINGS.RANK_TWO_PAIR,         rainbow = false },
  { code = "1p", label = STRINGS.RANK_ONE_PAIR,         rainbow = false },
