-- Scans the challenge zone and populates activeChallenges.
-- Returns the activeChallenges table. Each active challenge key stores
-- the number of matching tokens found (1, 2, ...). Truthy for boolean checks,
-- usable as a multiplier for stacking challenges.
function scanActiveChallenges()
  activeChallenges = {}
  if not scriptZoneChallengesObj then return activeChallenges end

  local objects = scriptZoneChallengesObj.getObjects()
  for _, obj in ipairs(objects) do
    local id = obj.getGMNotes()
    if id and id ~= "" then
      local key = challengeIdToKey[id]
      if key then
        activeChallenges[key] = (activeChallenges[key] or 0) + 1
      end
    end
  end
  return activeChallenges
end

-- Returns a challenge's apply-timing (see the CHALLENGES registry header):
--   "gameStart" (default) — applied once at round 1.
--   "roundStart"          — re-applied at the start of every round (via roundSetup).
--   "instant"             — applied the moment the token enters/leaves the zone.
function getChallengeTiming(key)
  local entry = CHALLENGES[key]
  return (entry and entry.applyTiming) or "gameStart"
end

-- Derives the four live hand-evaluation flags from the current activeChallenges scan.
-- Idempotent: always resets to defaults first, then applies, so it is safe to call at
-- round start (roundSetup) or instantly when an instant-timed token enters/leaves the zone.
-- Only the four pure-evaluation-flag challenges live here — they change how existing cards
-- are read, not which cards exist. Deck-composition challenges (Extra Hours, Grinding Gears,
-- Cluttered Toolbox, ...) stay in round1 because their cards are only built at deal time.
function applyChallengeEvalFlags()
  sortNormal    = true
  flushActive   = true
  forceHighCard = false
  forceLowCard  = false
  if activeChallenges.QUANTUM_CHAOS then sortNormal = false end
  if activeChallenges.NO_COLOR then flushActive = false end
  if activeChallenges.ALL_OUT_ATTACK then forceHighCard = true end
  if activeChallenges.SLEEPING_GUARD then forceLowCard = true end
end

-- An instant-timed challenge token entered or left the challenge zone: re-scan the active
-- challenges, re-derive the eval flags and force-locked ranks, then refresh the displays now.
-- The card fingerprint does not include these flags, so it must be invalidated to make the
-- 2s hand-rank loop recompute instead of re-applying stale cached labels. The live recalc only
-- runs while a game is in progress (round 1-5); during setup the flag + deck-modifier preview
-- is enough, and round1 will re-derive everything when the game starts.
function applyInstantChallengeChange()
  scanActiveChallenges()
  applyChallengeEvalFlags()
  rebuildLockedHandRanks()
  updateDeckTileModifiers()
  if round >= 1 and round <= 5 then
    handRankFingerprint = ""
    communityFingerprint = ""
    playerHandFingerprints = {}
    updatehandRankObjects()
  end
end

-- Finds and returns a challenge token object in the challenge zone by its GMNotes ID.
-- Returns nil if not found.
function findChallengeToken(id)
  if not scriptZoneChallengesObj then return nil end
  for _, obj in ipairs(scriptZoneChallengesObj.getObjects()) do
    if obj.getGMNotes() == id then return obj end
  end
  return nil
end

-- Returns whether the player has clearance to use admin buttons (promoted/host/allowed).
function antiTrollClearance(playerColor)
  -- Returns true if the player has clearance to use anti-troll features

  -- always allow if anti-troll is disabled
  if not FLAGS.AntiTroll then return true end

  -- allow if promoted or host
  if Player[playerColor].promoted or Player[playerColor].host then
    return true
  end

  for _, random in ipairs(randomRNGs) do
    if Player[playerColor].steam_id == random then
      return true
    end
  end

  return false
end

-- Sets buttonLocked flag and increments lock version to prevent double-clicks.
function lockButtons()
  buttonLockVersion = buttonLockVersion + 1
  buttonLocked = true
end

-- Clears the buttonLocked flag, allowing buttons to be clicked again.
function unlockButtons()
  buttonLocked = false
end

-- Safety fallback: only unlocks if no new lock was acquired since this was scheduled.
-- Prevents stale timers from unlocking a fresh lock (e.g. when mashing buttons).
function scheduleSafeUnlock(seconds)
  local version = buttonLockVersion
  Wait.time(function()
    if buttonLockVersion == version then
      unlockButtons()
    end
  end, seconds)
end

-- Returns a list of all currently seated player color strings (includes test players).
function getSeatedPlayers()
  local seated = {}
  local seen = {}
  -- Real seated players first
  for _, color in ipairs(Player.getAvailableColors()) do
    if Player[color].seated then
      table.insert(seated, color)
      seen[color] = true
    end
  end
  -- Append test players that aren't actually seated
  if testPlayerSet then
    for _, color in ipairs(SEAT_ORDER) do
      if testPlayerSet[color] and not seen[color] then
        table.insert(seated, color)
      end
    end
  end
  return seated
end

-- Scans all player dealerChipScriptZoneObj for the dealer chip. Returns the color of the
-- player whose zone contains it, or nil if not found. In non-Normal modes, broadcasts a
-- warning and returns nil (dealer mode only works in Normal/Texas Hold'em).
function detectDealerChip()
  if not dealerChipGUID then return nil end
  local foundColor = nil
  for color, params in pairs(playerParameters) do
    if params.dealerChipScriptZoneObj and isPlayerSeated(color) then
      for _, obj in ipairs(params.dealerChipScriptZoneObj.getObjects()) do
        if obj.getGUID() == dealerChipGUID then
          foundColor = color
          break
        end
      end
    end
    if foundColor then break end
  end
  if not foundColor then return nil end
  if activeGameMode ~= 0 then
    broadcastToAll(LANG(STRINGS.MSG_DEALER_NORMAL), { 1, 0.5, 0.2 })
    return nil
  end
  return foundColor
end

-- Returns the next seated player color in SEAT_ORDER after fromColor (circular).
function getNextSeatedPlayer(fromColor)
  local seated = getSeatedPlayers()
  if #seated == 0 then return nil end
  -- Build a set for O(1) lookup
  local seatedSet = {}
  for _, c in ipairs(seated) do seatedSet[c] = true end
  -- Find fromColor in SEAT_ORDER, then walk forward circularly
  local startIdx = nil
  for i, c in ipairs(SEAT_ORDER) do
    if c == fromColor then
      startIdx = i; break
    end
  end
  if not startIdx then return seated[1] end
  for offset = 1, #SEAT_ORDER do
    local idx = ((startIdx - 1 + offset) % #SEAT_ORDER) + 1
    local candidate = SEAT_ORDER[idx]
    if seatedSet[candidate] then return candidate end
  end
  return fromColor -- fallback: only one player
end

-- Moves the dealer chip from the current dealer to the next seated player's dealerChipTile.
-- Updates dealerColor to the new color.
function moveDealerChip(fromColor)
  local chipObj = getObjectFromGUID(dealerChipGUID)
  if not chipObj then return end
  local nextColor = getNextSeatedPlayer(fromColor)
  if not nextColor then return end
  local nextParams = playerParameters[nextColor]
  if not nextParams or not nextParams.dealerChipTileObj then return end
  local pos = nextParams.dealerChipTileObj.getPosition()
  chipObj.setPosition({ pos.x, pos.y + 1, pos.z })
  dealerColor = nextColor
end

-- Resets the dealer chip to its tile position if it's not in any player zone.
function resetDealerChipPosition()
  local chipObj = getObjectFromGUID(dealerChipGUID)
  if not chipObj then return end
  -- Check if dealer chip is in any player zone
  if detectDealerChip() then return end
  -- Move back to dealer chip tile
  if dealerChipTileObj then
    local pos = dealerChipTileObj.getPosition()
    chipObj.setPositionSmooth({ pos.x, pos.y + 1, pos.z })
    chipObj.setRotation({ 0, 0, 0 })
  end
end

