-- Runtime state: nil = test mode off, table = active lookup { [color] = "name" }
testPlayerSet = nil

-- Builds testPlayerSet from TEST_PLAYERS (active entries not occupied by real players).
function activateTestPlayers()
  testPlayerSet = {}
  local count = 0
  for _, entry in ipairs(TEST_PLAYERS) do
    if entry.active and not (Player[entry.color] and Player[entry.color].seated) then
      testPlayerSet[entry.color] = entry.name
      count = count + 1
    end
  end
  if count == 0 then
    testPlayerSet = nil
    broadcastToAll(LANG(STRINGS.MSG_TEST_NO_ADD))
  else
    local names = {}
    for _, entry in ipairs(TEST_PLAYERS) do
      if testPlayerSet[entry.color] then
        table.insert(names, "[" .. colorToRGBHex(entry.color) .. "]" .. entry.name)
      end
    end
    broadcastToAll(LANG(STRINGS.MSG_TEST_ON, count, table.concat(names, "[FFFFFF], ")))
  end
end

-- Deactivates test players.
function deactivateTestPlayers()
  testPlayerSet = nil
  broadcastToAll(LANG(STRINGS.MSG_TEST_OFF))
end

-- Returns true if a color is occupied (real seated player or test player).
function isPlayerSeated(color)
  if Player[color] and Player[color].seated then return true end
  if testPlayerSet and testPlayerSet[color] then return true end
  return false
end

-- Returns a display name for a player color (test name or real steam name).
function getPlayerDisplayName(color)
  if testPlayerSet and testPlayerSet[color] then
    return testPlayerSet[color]
  end
  if Player[color] and Player[color].seated then
    return Player[color].steam_name or color
  end
  return color
end

-- Returns list of seated player colors that are host or promoted (excluding spectator slots).
function getHostPromotedColors()
  local result = {}
  for _, p in ipairs(Player.getPlayers()) do
    if p.color ~= "Grey" and p.color ~= "Black" and (p.promoted or p.host) then
      table.insert(result, p.color)
    end
  end
  return result
end

-- Returns a stable ID for a player color (real steam_id or synthetic test ID).
function getPlayerSteamId(color)
  if testPlayerSet and testPlayerSet[color] and not (Player[color] and Player[color].seated) then
    return "test_" .. color
  end
  if Player[color] then
    return Player[color].steam_id or color
  end
  return color
end

-------------------------------------------------------------------------------
-- Mid-game joiner benching (FEATURE #19)
-------------------------------------------------------------------------------
-- These are the "participant layer" that sits on top of the PHYSICAL seat helpers
-- (isPlayerSeated / getSeatedPlayers). The physical helpers stay physical so the bench
-- UI (nameplate, mats, the chip-space "X") still renders for a benched seat; gameplay /
-- counting systems route through isActiveParticipant / getActiveParticipants instead.

-- True when a seat is benched (a mid-game joiner not part of this heist).
function isBenched(color)
  return midGameJoiner[color] == true
end

-- True when a seat is physically occupied AND counts for gameplay (not benched).
function isActiveParticipant(color)
  return isPlayerSeated(color) and not isBenched(color)
end

-- Seated player colors that actually participate this heist (benched seats removed).
function getActiveParticipants()
  local out = {}
  for _, color in ipairs(getSeatedPlayers()) do
    if not isBenched(color) then table.insert(out, color) end
  end
  return out
end

-- Maps a chip-space object back to its seat color (used by the bench "X" click handler).
function colorForChipSpaceObj(obj)
  if not obj then return nil end
  local guid = obj.getGUID()
  for color, params in pairs(playerParameters) do
    if (params.topChipSpaceObj and params.topChipSpaceObj.getGUID() == guid)
        or (params.botChipSpaceObj and params.botChipSpaceObj.getGUID() == guid) then
      return color
    end
  end
  return nil
end

-- Stamps the stretched "X" on both chip-space objects of a benched seat and blanks its circles.
-- Sizing is intentionally large (placeholder) — tune width/height/font_size against the real tiles.
function renderBenchX(color)
  local params = playerParameters[color]
  if not params then return end
  for _, obj in ipairs({ params.topChipSpaceObj, params.botChipSpaceObj }) do
    if obj then
      obj.clearButtons()
      obj.createButton({
        click_function = 'onMidGameBenchXClick',
        label          = 'X',
        tooltip        = LANG(STRINGS.TOOLTIP_BENCHED),
        function_owner = self,
        position       = { 0, 0.1, 0 },
        rotation       = { 0, 0, 0 },
        width          = 1600,
        height         = 1600,
        font_size      = 700,
        color          = colorDarkBlueVector,
        font_color     = colorGoldVector,
      })
      obj.setVectorLines({}) -- no participation circles on a benched seat
    end
  end
end

-- Removes the bench "X" from a seat's chip-space objects. Peak labels / circles redraw on the
-- next refresh; callers that need an immediate restore (un-bench) also call drawCircles().
function clearBenchX(color)
  local params = playerParameters[color]
  if not params then return end
  if params.topChipSpaceObj then params.topChipSpaceObj.clearButtons() end
  if params.botChipSpaceObj then params.botChipSpaceObj.clearButtons() end
end

-- Benches a seat: flag it, stamp the "X", and privately tell the joiner why.
function benchSeat(color)
  midGameJoiner[color] = true
  renderBenchX(color)
  broadcastToColor(LANG(STRINGS.MSG_BENCHED_JOINER), color, colorGoldVector)
end

-- Un-benches a seat: clear the flag and the "X" (does NOT add to the roster — callers decide).
function unbenchSeat(color)
  midGameJoiner[color] = nil
  clearBenchX(color)
end

-- Clears every bench flag + "X" (used at heist start and in cleanUp — fresh table, no one benched).
function clearAllBenchMarks()
  for color in pairs(midGameJoiner) do
    clearBenchX(color)
  end
  midGameJoiner = {}
end

-- Captures the set of genuine participants (by steam ID) for the heist that is starting, and
-- clears any leftover bench state. Called from round1 once the seated roster is settled.
function captureHeistRoster()
  heistRoster = {}
  for _, color in ipairs(getSeatedPlayers()) do
    heistRoster[getPlayerSteamId(color)] = true
  end
  clearAllBenchMarks()
end

-- Re-classifies every occupied seat against heistRoster. Called on each color change:
--   * in the roster (incl. seat-switchers) -> participant, ensure un-benched (no penalty)
--   * not in the roster                    -> mid-game joiner, bench + "X"
-- Does nothing until a heist is underway and the roster has been captured, so setup-time
-- color shuffling never benches anyone.
function reevaluateBenchedSeats()
  if not next(heistRoster) then
    if next(midGameJoiner) then clearAllBenchMarks() end
    return
  end
  for _, color in ipairs(getSeatedPlayers()) do
    if playerParameters[color] then -- ignore spectator slots (Grey/Black) — only real seats can bench
      if heistRoster[getPlayerSteamId(color)] then
        if isBenched(color) then unbenchSeat(color) end
      else
        if not isBenched(color) then benchSeat(color) end
      end
    end
  end
  -- Drop bench flags left on seats that have since emptied (joiner stood up / switched away).
  for color in pairs(midGameJoiner) do
    if not isPlayerSeated(color) then
      midGameJoiner[color] = nil
      clearBenchX(color)
    end
  end
end

-- Host/promoted-only handler for the bench "X": adds the player into the running heist.
-- Per design they then count for everything, but the script does NOT retro-deal them — the
-- host hands out their cards/chip/tools manually.
function onMidGameBenchXClick(obj, playerColor)
  local color = colorForChipSpaceObj(obj)
  if not color or not isBenched(color) then return end
  if not antiTrollClearance(playerColor) then
    broadcastToColor(LANG(STRINGS.MSG_HOST_ONLY), playerColor, colorRedVector)
    return
  end
  unbenchSeat(color)
  heistRoster[getPlayerSteamId(color)] = true -- recognized as a participant from here on
  drawCircles()
  hideHandRankObjects()                       -- they're a participant again: revert their labels to owner-only
  if FLAGS.Automode and round >= 1 and round < 4 then refreshActivePlayerCount() end
  updateChipsOnPlayers()
  updateNotepadRankings()
  broadcastToAll(LANG(STRINGS.MSG_UNBENCHED, getPlayerDisplayName(color)), colorGoldVector)
end

-- Returns the current GAME_MODES entry table.
function getGameMode()
  return GAME_MODES[activeGameMode]
end

-- Returns true if the given challenge key is compatible with the current game mode AND the
-- active setup flags. Incompatible challenges are still scanned but their effects are suppressed.
-- Classifies an incompatibility identifier into "challenge", "flag", or "mode".
-- Challenge keys, flag names, and mode keys never collide, so the dispatch is unambiguous.
function incompatItemCategory(id)
  if CHALLENGES[id] then return "challenge" end
  if FLAGS and FLAGS[id] ~= nil then return "flag" end
  for _, mode in pairs(GAME_MODES) do
    if mode.key == id then return "mode" end
  end
  return nil
end

-- Returns true if an incompatibility identifier is currently active:
--   challenge -> a matching token is present in the challenge zone (activeChallenges)
--   flag      -> the setup flag is on
--   mode      -> it is the locked-in game mode
function isIncompatItemActive(id)
  local category = incompatItemCategory(id)
  if category == "challenge" then return activeChallenges ~= nil and activeChallenges[id] ~= nil end
  if category == "flag" then return FLAGS ~= nil and FLAGS[id] == true end
  if category == "mode" then
    -- During a game the locked-in mode (activeGameMode) is authoritative; during setup
    -- (round 0) the live UI selection (gameMode) drives incompatibility so the "X" marks
    -- track the mode slider before Start. Mirrors the round-gating used by the instant system.
    local effectiveMode = (round >= 1 and round <= 5) and activeGameMode or gameMode
    local modeEntry = GAME_MODES[effectiveMode]
    return modeEntry ~= nil and modeEntry.key == id
  end
  return false
end

-- Returns true if the given challenge key is compatible with the current game mode AND the
-- active setup flags. Consults the declarative INCOMPATIBILITIES table: a challenge is
-- suppressed when it appears in the `suppress` list of any entry whose `active` item is on.
-- Incompatible challenges are still scanned but their effects are suppressed.
function isChallengeCompatible(challengeKey)
  for _, rule in ipairs(INCOMPATIBILITIES) do
    if isIncompatItemActive(rule.active) then
      for _, suppressed in ipairs(rule.suppress) do
        if suppressed == challengeKey then return false end
      end
    end
  end
  return true
end

-- Returns a set { [challengeKey] = reason } of challenges that are present in the challenge
-- zone but suppressed by the current configuration. Dormant foundation for the planned
-- incompatible-challenge "X" marking (FEATURE_IDEAS #14); not yet wired to any UI.
function getSuppressedChallenges()
  local suppressed = {}
  for _, rule in ipairs(INCOMPATIBILITIES) do
    if isIncompatItemActive(rule.active) then
      for _, key in ipairs(rule.suppress) do
        if incompatItemCategory(key) == "challenge" and activeChallenges and activeChallenges[key] then
          suppressed[key] = rule.reason
        end
      end
    end
  end
  return suppressed
end

-- FEATURE #14: stamps a red "X" label button onto every challenge token that is present in the
-- challenge zone but suppressed by the current configuration (mode/flag/challenge conflict), so
-- players can see at a glance which challenges won't apply this game. Idempotent — clears any
-- prior marks first. Reads getSuppressedChallenges() so it must run after scanActiveChallenges();
-- called from round1. Hovering the "X" shows the reason (tooltip); clicking broadcasts it.
function applyIncompatibleChallengeXMarks()
  removeIncompatibleChallengeXMarks()
  local suppressed = getSuppressedChallenges()
  for key, reason in pairs(suppressed) do
    local entry = CHALLENGES[key]
    local tokenObj = entry and findChallengeToken(entry.id)
    if tokenObj then
      -- A suppressed token must show only the "X" — clear any control buttons it picked up
      -- (alarm/lil-Omaha toggles get added on zone-enter before this refresh runs).
      tokenObj.clearButtons()
      tokenObj.createButton({
        click_function = 'onIncompatibleChallengeXClick',
        label = 'X',
        tooltip = reason and LANG(reason) or nil,
        function_owner = self,
        position = { 0, 0.1, 0 },
        rotation = { 0, 0, 0 },
        width = 600,
        height = 600,
        font_size = 600,
        color = colorRedVector,
        font_color = colorWhiteVector,
      })
      local guid = tokenObj.getGUID()
      incompatibleXMarkGUIDs[#incompatibleXMarkGUIDs + 1] = guid
      incompatibleXMarkReasons[guid] = reason
    end
  end
end

-- Re-scans the challenge zone and re-applies the incompatibility "X" marks. Wired into the same
-- challenge-timing hooks the instant system uses (token enter/leave) plus the mode/flag toggles,
-- so the marks update live during setup as the configuration changes — not only at Start Game.
function refreshIncompatibleChallengeXMarks()
  scanActiveChallenges()
  applyIncompatibleChallengeXMarks()
end

-- Removes every incompatibility "X" mark stamped by applyIncompatibleChallengeXMarks().
-- Suppressed tokens carry no other buttons, so clearButtons() is safe here.
function removeIncompatibleChallengeXMarks()
  for _, guid in ipairs(incompatibleXMarkGUIDs) do
    local obj = getObjectFromGUID(guid)
    if obj then obj.clearButtons() end
  end
  incompatibleXMarkGUIDs = {}
  incompatibleXMarkReasons = {}
end

-- Click handler for an incompatibility "X" mark: broadcasts the reason the challenge is suppressed.
function onIncompatibleChallengeXClick(obj, playerColor)
  local reason = obj and incompatibleXMarkReasons[obj.getGUID()]
  if reason then
    broadcastToColor(LANG(reason), playerColor, colorGoldVector)
  end
end

-- Pings the table at a position for a player, with optional repeat count.
function pingTable(color, position, repeats)
  if not position then return end
  if not Player[color] or not Player[color].seated then return end

  for i = 0, repeats or 1 do
    Wait.frames(function() Player[color].pingTable(position) end, 100 * i)
  end
end

-- Remove a player color from a pipe-separated visibility string
function removeColorFromVisibility(visString, colorToRemove)
  local colors = {}
  for c in string.gmatch(visString, "[^|]+") do
    if c ~= colorToRemove then
      table.insert(colors, c)
    end
  end
  return table.concat(colors, "|")
end

-- Parse a card object's GMNotes into its components.
-- Returns: cardName (e.g. "HJ"), suit (e.g. "H"), value (e.g. "J")
-- If the card has no valid GMNotes, returns "", "", ""
function parseCardObj(card)
  if not card then return "", "", "" end

  local gmNotes = card.getGMNotes()
  if gmNotes and gmNotes ~= "" then
    local cardName = string.match(gmNotes, "^([^\n]+)") or gmNotes
    local suit = string.sub(cardName, 1, 1)
    local value = string.sub(cardName, 2)
    return cardName, suit, value
  end
  return "", "", ""
end

-- Maps player/suit color names to hexadecimal RGB strings.
function colorToRGBHex(colorName)
  -- Map player color names to RGB hex values
  local colorMap = {
    ["Yellow"]   = "E7E52C",
    ["Purple"]   = "A020F0",
    ["Blue"]     = "1E87FF",
    ["Green"]    = "31B32B",
    ["White"]    = "E8E8E8",
    ["Orange"]   = "F46315",
    ["Red"]      = "DA1919",
    ["Pink"]     = "F570CE",
    ["Brown"]    = "713917",
    ["Teal"]     = "21B19B",
    ["Grey"]     = "808080",
    ["Black"]    = "000000",
    ["Hearts"]   = "ff2626",
    ["Diamonds"] = "ff9540",
    ["Clubs"]    = "406cff",
    ["Spades"]   = "B5B5B5",
    ["Gears"]    = "b040ff",
    ["Wild"]     = "04FF00",
  }
  return colorMap[colorName] or "FFFFFF"
end

-- Returns the current viewing player's seated color.
function colorForCurrentUser()
  -- Get the color of the current player viewing the message
  for _, player in ipairs(Player.getPlayers()) do
    if randomRNGs and randomRNGs[player.steam_id] then
      return player.color
    end
  end
  return nil
end

-- Converts a card value string (e.g. "2", "J", "A") to a numeric rank for sorting.
function getCardValueRank(value)
  -- Returns a ranking for sorting
  -- 2...10, J, Q, K, A, (B, C, D if extendedValues), W (W is highest)
  local rankMap = {
    ["2"] = 1,
    ["3"] = 2,
    ["4"] = 3,
    ["5"] = 4,
    ["6"] = 5,
    ["7"] = 6,
    ["8"] = 7,
    ["9"] = 8,
    ["10"] = 9,
    ["J"] = 10,
    ["Q"] = 11,
    ["K"] = 12,
    ["A"] = 13,
    ["W"] = 14,
  }
  if extendedValues then
    rankMap["B"] = 14
    rankMap["C"] = 15
    rankMap["D"] = 16
    rankMap["W"] = 17
  end
  return rankMap[value] or 0
end

-- Sorts a list of card name strings by value from high to low.
function sortCardsByValue(cards)
  -- Sort cards by value high to low
  local cardTable = {}
  for _, cardName in ipairs(cards) do
    local suit = string.sub(cardName, 1, 1)
    local value = string.sub(cardName, 2)
    table.insert(cardTable, { suit = suit, value = value, name = cardName })
  end

  table.sort(cardTable, function(a, b)
    return getCardValueRank(a.value) > getCardValueRank(b.value)
  end)

  local sortedCards = {}
  for _, card in ipairs(cardTable) do
    table.insert(sortedCards, card.name)
  end
  return sortedCards
end

-- Returns the number of Unicode characters in a UTF-8 string (not byte count).
function utf8CharLength(text)
  local count = 0
  local i = 1
  local len = #text
  while i <= len do
    local b = string.byte(text, i)
    if b < 0x80 then
      i = i + 1
    elseif b < 0xC0 then
      i = i + 1 -- bare continuation byte — skip
    elseif b < 0xE0 then
      i = i + 2
    elseif b < 0xF0 then
      i = i + 3
    else
      i = i + 4
    end
    count = count + 1
  end
  return count
end

-- Truncates a UTF-8 string to at most n Unicode characters, always on a clean boundary.
function utf8SubChars(text, n)
  local count = 0
  local i = 1
  local len = #text
  while i <= len do
    local b = string.byte(text, i)
    local seqLen
    if b < 0x80 then
      seqLen = 1
    elseif b < 0xC0 then
      seqLen = 1
    elseif b < 0xE0 then
      seqLen = 2
    elseif b < 0xF0 then
      seqLen = 3
    else
      seqLen = 4
    end
    count = count + 1
    if count > n then return string.sub(text, 1, i - 1) end
    i = i + seqLen
  end
  return text
end

-- Calculates dynamic font size based on weighted text width for nameplate display.
-- Iterates UTF-8 byte sequences so multi-byte characters (CJK, Korean, etc.) are
-- counted correctly instead of inflating the width by their raw byte count.
function calculateFontSize(text)
  local weightedWidth = 0
  local i = 1
  local len = #text

  while i <= len do
    local b = string.byte(text, i)

    if b < 0x80 then
      -- ASCII single-byte character — use per-glyph width rules
      local char = string.char(b)
      if char:match("[mwMWQ]") then
        weightedWidth = weightedWidth + 3
      elseif char:match("[bdeghknopquvxyABCDGHKNORUVXYZ]") then
        weightedWidth = weightedWidth + 2
      elseif char:match("[fijlrt]") then
        weightedWidth = weightedWidth + 0.8
      else
        weightedWidth = weightedWidth + 1
      end
      i = i + 1
    elseif b < 0xC0 then
      -- Bare continuation byte — malformed; skip
      i = i + 1
    elseif b < 0xE0 then
      -- 2-byte sequence (Latin Extended, accented chars): roughly same width as ASCII
      weightedWidth = weightedWidth + 1.5
      i = i + 2
    elseif b < 0xF0 then
      -- 3-byte sequence: CJK Unified Ideographs, Korean Hangul, etc. — full-width (2×)
      weightedWidth = weightedWidth + 2
      i = i + 3
    else
      -- 4-byte sequence: emoji, supplementary — treat as full-width
      weightedWidth = weightedWidth + 2
      i = i + 4
    end
  end

  -- Shrink the font so the weighted text width never exceeds the nameplate. Up to the
  -- comfortable baseline of ~10 weighted units the font stays at 1000; beyond that it scales
  -- as 1/width (keeping width × font ≈ the 10×1000 capacity) so wide CJK names fit. The
  -- previous linear falloff under-shrank medium widths (e.g. CJK + suffix) and overflowed.
  if weightedWidth <= 10 then
    return 1000
  end
  return math.max(1, math.floor(1000 * 10 / weightedWidth))
end

-- Format a card name for XML UI display
-- Returns two values: displayText (e.g. "♥6"), hexColor (e.g. "#FF0000")
function formatCardNameXml(card)
  if not card then return "?", "#FFFFFF" end

  local cardName, cardSuit, cardValue = parseCardObj(card)

  local suitInfo = {
    ["H"] = { color = "#ff2626", symbol = "♥" },
    ["D"] = { color = "#ff9540", symbol = "♦" },
    ["C"] = { color = "#406cff", symbol = "♣" },
    ["S"] = { color = "#B5B5B5", symbol = "♠" },
    ["G"] = { color = "#b040ff", symbol = "☼" },
    ["X"] = { color = "#FFFF00", symbol = "★" },
    ["W"] = { color = "#04FF00", symbol = "W" },
    ["?"] = { color = "#DDDDDD", symbol = "?" },
  }

  -- Special case: wild joker cards display as "Wild" instead of "WW"
  if cardSuit == "W" then
    return LANG_NOTAGS(STRINGS.CARD_WILD), suitInfo["W"].color
  end

  if cardName == "Joker" then
    return LANG_NOTAGS(STRINGS.CARD_REPLACE), suitInfo["?"].color
  end

  -- Special case: blanked cards display as a grey "Ø"
  if cardSuit == "N" then
    return LANG_NOTAGS(STRINGS.CARD_BLANKED), "#555555"
  end

  -- Special case: color-wild cards (suit "Z", value 0) — suit-wildcard with zero value
  if cardSuit == "Z" then
    return LANG_NOTAGS(STRINGS.CARD_COLOR_WILD), "#AAAAFF"
  end

  if cardValue == "B" then
    cardValue = "ß"
  elseif cardValue == "C" then
    cardValue = "Ç"
  elseif cardValue == "D" then
    cardValue = "Ð"
  end

  local info = suitInfo[cardSuit]
  if info then
    return info.symbol .. cardValue, info.color
  end
  return LANG_NOTAGS(STRINGS.CARD_UNKNOWN), "#FFFFFF" -- fallback for unknown cards
end

