------------------------------------
--- Admin Board (modular setup controls on one movable board)
------------------------------------
--
-- The board is composed of self-contained "modules" (widget types). Each module type lives in
-- ADMIN_MODULES and provides:
--   build(obj, def, ctx)   -- create its buttons, advance the layout cursor (ctx.z), and record
--                              its button indices in adminBoardState.runtime[def]
--   registerHandlers(def)  -- (optional) define its named global click handlers
--   update(def)            -- (optional) refresh its visual state after a state change
-- The board content (ADMIN_BOARD) is just an ordered list of module instances. Adding a new
-- widget kind = add one entry to ADMIN_MODULES; adding a control = add one row to ADMIN_BOARD.

-- Layout constants (object-local coordinates). First-pass values — tune against the real board.
ADMIN_BOARD_LAYOUT = {
  buttonY             = 0.6,  -- height above the board surface
  rowZ0               = -4.0, -- z of the first (top) row

  -- Vertical spacing — the three knobs that shape the stack:
  moduleGapZ          = 1.2, -- (1) z gap added between consecutive modules
  headerStepZ         = 0.8, -- (2) z gap from a module's caption/header down to its content
  rowStepZ            = 1.0, -- z between stacked rows inside a module (generic fallback)

  boardRotation       = { x = 0, y = 0, z = 0 },

  headerFontSize      = 500, -- standalone `header` module label
  modulHeaderFontSize = 400, -- module caption (section title)
  labelFontSize       = 500,

  -- Toggles
  toggleFontSize      = 200,
  toggleWidth         = 1800,
  toggleHeight        = 350,
  toggleColumns       = 3,   -- (5) default columns for a `toggles` grid (per-instance `columns` overrides)
  toggleColStepX      = 4,   -- (5) x spacing between toggle columns
  toggleRowStepZ      = 1.2, -- (5) z spacing between toggle rows

  -- Slider option layout, keyed by option count. `arrowGapX` = extra x beyond the outermost options
  -- for the < / > arrows. Per-instance optionStepX/Width/Height/FontSize/ArrowGapX override the preset.
  sliderOptions       = {
    [3]     = { stepX = 4.0, width = 1800, height = 350, fontSize = 200, arrowGapX = 2.5 }, -- (3) 3-option sliders
    [4]     = { stepX = 3.6, width = 1700, height = 350, fontSize = 170, arrowGapX = 2.3 }, -- (4) 4-option sliders (e.g. Exit Chips)
    default = { stepX = 4.5, width = 2000, height = 400, fontSize = 250, arrowGapX = 2.5 },
  },
  arrowFontSize       = 250,
  arrowWidth          = 400,
  arrowHeight         = 250,

  -- The current option is shown by highlighting its button (no marker, no animation).
  optionColor         = { 1, 1, 1 },       -- inactive option background (white)
  optionColorActive   = colorGoldVector,   -- current option background (gold highlight)
  optionColorPending  = { 1, 0.55, 0.55 }, -- pending option/toggle (light red): a deferred
  -- change that only applies on the next heist start (see applyTiming / applyPendingAdminChanges).
}

-- Per-instance runtime state (button indices, slider position), keyed by the instance table.
adminBoardState = { runtime = {} }

-- Creates one button on the board and returns its index, advancing the running index in ctx.
-- (createButton does not return an index — indices are assigned 0..N in creation order.)
function adminAddButton(obj, ctx, params)
  params.function_owner = Global
  obj.createButton(params)
  local index = ctx.idx
  ctx.idx = ctx.idx + 1
  return index
end

-- Returns the option index whose value matches a slider's current state (defaults to 1).
function adminSliderCurrentIndex(def)
  local current = def.get()
  for i, opt in ipairs(def.options) do
    if opt.value == current then return i end
  end
  return 1
end

-- Renders a module's section caption (if any) as a non-interactive gold label, then advances the
-- cursor by headerStepZ (the caption->content gap). Modules call this first.
function adminRenderCaption(obj, ctx, captionEntry)
  if not captionEntry then return end
  local L = ctx.L
  adminAddButton(obj, ctx, {
    click_function = "doNothing",
    label = LANG(captionEntry),
    position = { 0, L.buttonY, ctx.z },
    rotation = L.boardRotation,
    font_size = L.modulHeaderFontSize,
    width = 0,
    height = 0,
    font_color = colorGoldVector,
  })
  ctx.z = ctx.z + L.headerStepZ
end

-- Highlight color for a toggle/option button: gold when active, white when inactive.
function adminHighlightColor(active)
  local L = ADMIN_BOARD_LAYOUT
  return active and L.optionColorActive or L.optionColor
end

-- Module-level apply-timing for an Admin Board control (parallel to the challenge timing flag):
--   "instant"    (default) — applies the moment it is clicked, even mid-game.
--   "gameStart"            — deck/deal structure: deferred while a game runs, applied at round 1.
--   "roundStart"           — deferred while a game runs, applied at the next round start.
function getAdminTiming(def)
  return def.applyTiming or "instant"
end

-- True while a heist is actually in progress (rounds 1-5). Outside that window (setup / showdown
-- cleanup, round 0) admin changes apply immediately because the next round start is imminent.
function isGameInProgress()
  return round >= 1 and round <= 5
end

-- True if a control's change must be deferred (shown as a light-red "pending" mark) right now:
-- its timing is not instant AND a game is currently in progress.
function adminChangeDeferred(def)
  return getAdminTiming(def) ~= "instant" and isGameInProgress()
end

-- ===== Module types =====
-- Each module knows how to build itself, register its handlers, and refresh its visuals.
ADMIN_MODULES = {

  -- Non-interactive section label (standalone; most sections use a module `caption` instead).
  header = {
    build = function(obj, def, ctx)
      local L = ctx.L
      adminAddButton(obj, ctx, {
        click_function = "doNothing",
        label = LANG(def.label),
        position = { 0, L.buttonY, ctx.z },
        rotation = L.boardRotation,
        font_size = L.headerFontSize,
        width = 0,
        height = 0, -- 0 size = label only (non-interactive)
        font_color = colorGoldVector,
      })
      -- ctx.z stays on this row; the build loop adds moduleGapZ before the next module.
    end,
  },

  -- Single labelled toggle button bound to a boolean FLAG (e.g. Low CPU). Optional def.caption.
  toggle = {
    registerHandlers = function(def)
      local flagName = def.flag
      _G["onAdminBoardToggle_" .. flagName] = function(_, playerColor)
        setBoardFlag(flagName, playerColor)
      end
    end,
    build = function(obj, def, ctx)
      local L = ctx.L
      adminRenderCaption(obj, ctx, def.caption)
      local prefix = FLAGS[def.flag] and "[x] " or "[ ] "
      local index = adminAddButton(obj, ctx, {
        click_function = "onAdminBoardToggle_" .. def.flag,
        label = LANG(def.label, prefix),
        position = { 0, L.buttonY, ctx.z },
        rotation = L.boardRotation,
        font_size = L.toggleFontSize,
        width = L.toggleWidth,
        height = L.toggleHeight,
        color = adminHighlightColor(FLAGS[def.flag]),
        tooltip = def.tooltip and LANG(def.tooltip) or nil,
      })
      adminBoardState.runtime[def] = { buttonIndex = index }
      -- single row: leave ctx.z on it; the build loop adds moduleGapZ.
    end,
    update = function(def)
      local runtime = adminBoardState.runtime[def]
      if not adminBoardObj or not runtime then return end
      local prefix = FLAGS[def.flag] and "[x] " or "[ ] "
      adminBoardObj.editButton({
        index = runtime.buttonIndex,
        label = LANG(def.label, prefix),
        color = adminToggleColor(runtime, def.flag),
      })
    end,
  },

  -- Multiple toggle buttons laid out in a grid of `columns` columns (saves vertical space). Each
  -- item: { flag = "...", label = STRINGS.X }. Optional def.caption, def.columns (default
  -- L.toggleColumns), def.colStepX (default L.toggleColStepX), def.rowStepZ (default L.toggleRowStepZ).
  toggles = {
    registerHandlers = function(def)
      for _, item in ipairs(def.items) do
        local flagName = item.flag
        _G["onAdminBoardToggle_" .. flagName] = function(_, playerColor)
          setBoardFlag(flagName, playerColor)
        end
      end
    end,
    build = function(obj, def, ctx)
      local L = ctx.L
      adminRenderCaption(obj, ctx, def.caption)
      local columns = def.columns or L.toggleColumns
      local colStepX = def.colStepX or L.toggleColStepX
      local rowStepZ = def.rowStepZ or L.toggleRowStepZ
      local firstX = -((columns - 1) / 2) * colStepX
      local startZ = ctx.z
      for i, item in ipairs(def.items) do
        local col = (i - 1) % columns
        local gridRow = math.floor((i - 1) / columns)
        local prefix = FLAGS[item.flag] and "[x] " or "[ ] "
        local index = adminAddButton(obj, ctx, {
          click_function = "onAdminBoardToggle_" .. item.flag,
          label = LANG(item.label, prefix),
          position = { firstX + col * colStepX, L.buttonY, startZ + gridRow * rowStepZ },
          rotation = L.boardRotation,
          font_size = L.toggleFontSize,
          width = L.toggleWidth,
          height = L.toggleHeight,
          color = adminHighlightColor(FLAGS[item.flag]),
          tooltip = item.tooltip and LANG(item.tooltip) or nil,
        })
        adminBoardState.runtime[item] = { buttonIndex = index }
      end
      local gridRows = math.ceil(#def.items / columns)
      ctx.z = startZ + (gridRows - 1) * rowStepZ -- leave on the last grid row
    end,
    update = function(def)
      if not adminBoardObj then return end
      for _, item in ipairs(def.items) do
        local runtime = adminBoardState.runtime[item]
        if runtime then
          local prefix = FLAGS[item.flag] and "[x] " or "[ ] "
          adminBoardObj.editButton({
            index = runtime.buttonIndex,
            label = LANG(item.label, prefix),
            color = adminToggleColor(runtime, item.flag),
          })
        end
      end
    end,
  },

  -- Segmented selector: optional caption above, a row of option buttons with < / > arrows at the
  -- ends. The current option is shown by highlighting its button (color); arrows wrap around.
  -- Drives a discrete state var via get/set. Option layout comes from L.sliderOptions[#options]
  -- (presets for 3 / 4 / default); per-instance def.optionStepX/Width/Height/FontSize overrides it.
  slider = {
    registerHandlers = function(def)
      _G["onAdminBoardSliderPrev_" .. def.key] = function(_, playerColor)
        adminSliderStep(def, -1, playerColor)
      end
      _G["onAdminBoardSliderNext_" .. def.key] = function(_, playerColor)
        adminSliderStep(def, 1, playerColor)
      end
      for i = 1, #def.options do
        local optionIdx = i
        _G["onAdminBoardSliderJump_" .. def.key .. "_" .. optionIdx] = function(_, playerColor, altClick)
          adminSliderJump(def, optionIdx, playerColor, altClick)
        end
      end
    end,
    build = function(obj, def, ctx)
      local L = ctx.L
      local preset = L.sliderOptions[#def.options] or L.sliderOptions.default
      local optionStepX = def.optionStepX or preset.stepX
      local optionWidth = def.optionWidth or preset.width
      local optionHeight = def.optionHeight or preset.height
      local optionFont = def.optionFontSize or preset.fontSize
      local arrowGapX = def.arrowGapX or preset.arrowGapX

      adminRenderCaption(obj, ctx, def.caption)

      -- Track: option labels (click-to-jump) and the end arrows, all on one row (trackZ).
      -- The current option is shown by highlighting its button (no marker, no animation).
      local trackZ = ctx.z
      local count = #def.options
      local currentIdx = adminSliderCurrentIndex(def)
      local firstX = -((count - 1) / 2) * optionStepX
      local optionIndices = {}
      for i, opt in ipairs(def.options) do
        local x = firstX + (i - 1) * optionStepX
        local optTooltip = opt.tooltip or def.tooltip
        optionIndices[i] = adminAddButton(obj, ctx, {
          click_function = "onAdminBoardSliderJump_" .. def.key .. "_" .. i,
          label = LANG(opt.label),
          position = { x, L.buttonY, trackZ },
          rotation = L.boardRotation,
          font_size = optionFont,
          width = optionWidth,
          height = optionHeight,
          color = (i == currentIdx) and L.optionColorActive or L.optionColor,
          tooltip = optTooltip and LANG(optTooltip) or nil,
        })
      end

      local edgeX = firstX + (count - 1) * optionStepX + arrowGapX
      adminAddButton(obj, ctx, {
        click_function = "onAdminBoardSliderPrev_" .. def.key,
        label = "<",
        position = { -edgeX, L.buttonY, trackZ },
        rotation = L.boardRotation,
        font_size = L.arrowFontSize,
        width = L.arrowWidth,
        height = L.arrowHeight,
        color = colorGoldVector,
        font_color = colorDarkBlueVector,
      })
      adminAddButton(obj, ctx, {
        click_function = "onAdminBoardSliderNext_" .. def.key,
        label = ">",
        position = { edgeX, L.buttonY, trackZ },
        rotation = L.boardRotation,
        font_size = L.arrowFontSize,
        width = L.arrowWidth,
        height = L.arrowHeight,
        color = colorGoldVector,
        font_color = colorDarkBlueVector,
      })

      adminBoardState.runtime[def] = {
        optionIndices = optionIndices,
        currentIdx = currentIdx,
        pendingIdx = nil, -- a deferred (light-red) selection awaiting the next heist start
      }
      ctx.z = trackZ      -- single track row (no marker); the build loop adds moduleGapZ.
    end,
  },
}

