      { value = 1, label = STRINGS.EXIT_MODE_MASTER,  tooltip = STRINGS.TOOLTIP_ADMIN_EXIT_MASTER },
      { value = 2, label = STRINGS.EXIT_MODE_MEGA,    tooltip = STRINGS.TOOLTIP_ADMIN_EXIT_MEGA },
      { value = 3, label = STRINGS.EXIT_MODE_ULTRA,   tooltip = STRINGS.TOOLTIP_ADMIN_EXIT_ULTRA },
    }
  },
  {
    module = "slider",
    caption = STRINGS.ADMIN_HDR_CPU, -- 4 options → uses L.sliderOptions[4] preset for spacing/width
    key = "cpuMode",
    msg = STRINGS.MSG_CPU_MODE,
    applyTiming = "instant", -- live hand-rank display control: must apply immediately
    get = function() return cpuMode end,
    set = function(value)
      cpuMode = value; onCpuModeChanged()
    end,
    onAltJump = function(optionIdx) onCpuModeAltJump(optionIdx) end,
    options = {
      { value = 0, label = STRINGS.CPU_MODE_DISABLED, tooltip = STRINGS.TOOLTIP_ADMIN_CPU_DISABLED },
      { value = 1, label = STRINGS.CPU_MODE_LOW,      tooltip = STRINGS.TOOLTIP_ADMIN_CPU_LOW },
      { value = 2, label = STRINGS.CPU_MODE_RANK,     tooltip = STRINGS.TOOLTIP_ADMIN_CPU_RANK },
      { value = 3, label = STRINGS.CPU_MODE_FULL,     tooltip = STRINGS.TOOLTIP_ADMIN_CPU_FULL },
    }
  },
  {
    module = "toggles",
    caption = STRINGS.ADMIN_HDR_SYSTEM,
    columns = 3,
    applyTiming = "instant", -- system controls (auto-advance, permissions): must apply immediately
    items = {
      { flag = "Automode",   label = STRINGS.TOGGLE_AUTOMODE,    tooltip = STRINGS.TOOLTIP_ADMIN_AUTOMODE },
      { flag = "AntiTroll",  label = STRINGS.TOGGLE_ANTITROLL,   tooltip = STRINGS.TOOLTIP_ADMIN_ANTITROLL },
      { flag = "ValueChart", label = STRINGS.TOGGLE_VALUE_CHART, tooltip = STRINGS.TOOLTIP_ADMIN_VALUE_CHART },
    }
  },
}

-- (Re)generates each module's named global click handlers. TTS click_functions must be named
-- globals (no closures, no button-index argument), so each module declares its own dispatchers.
function registerAdminBoardHandlers()
  for _, def in ipairs(ADMIN_BOARD) do
    local module = ADMIN_MODULES[def.module]
    if module and module.registerHandlers then module.registerHandlers(def) end
  end
end

-- Builds (or rebuilds) the whole board from ADMIN_BOARD, delegating each row to its module type.
function buildAdminBoard()
  if not adminBoardObj then return end

  adminBoardObj.clearButtons()
  adminBoardState = { runtime = {} }
  registerAdminBoardHandlers()

  local ctx = { L = ADMIN_BOARD_LAYOUT, idx = 0, z = ADMIN_BOARD_LAYOUT.rowZ0 }
  for _, def in ipairs(ADMIN_BOARD) do
    local module = ADMIN_MODULES[def.module]
    if module then
      module.build(adminBoardObj, def, ctx)
      ctx.z = ctx.z + ADMIN_BOARD_LAYOUT.moduleGapZ -- (1) gap between modules
    end
  end

  adminBoardObj.interactable = DEFAULT_INTERACTABLE
end

-- Refreshes one module instance's visuals (used after a state change).
function updateAdminModule(def)
  local module = ADMIN_MODULES[def.module]
  if module and module.update then module.update(def) end
end

-- Locates the Admin Board module def + per-button runtime key driving a flag. For a single
-- `toggle` the runtime is keyed by the def itself; for a `toggles` grid it is keyed by the item.
function findAdminFlagDef(flagName)
  for _, def in ipairs(ADMIN_BOARD) do
    if def.module == "toggle" and def.flag == flagName then return def, def end
    if def.module == "toggles" then
      for _, item in ipairs(def.items) do
        if item.flag == flagName then return def, item end
      end
    end
  end
  return nil, nil
end

-- Color for a toggle button: light-red when a deferred change is pending, otherwise gold/white
-- per the live flag state. (runtime.pending is the awaited target value, or nil when none.)
function adminToggleColor(runtime, flagName)
  if runtime and runtime.pending ~= nil then return ADMIN_BOARD_LAYOUT.optionColorPending end
  return adminHighlightColor(FLAGS[flagName])
end

-- Commits a flag to a concrete value and runs its side effects. Shared by the instant toggle path
-- and applyPendingAdminChanges() (deferred commit at round/heist start).
function commitFlagChange(flagName, newValue)
  FLAGS[flagName] = newValue
  updateBoardFlag(flagName)
  if flagName == 'TwoHand' then
    setChipSpaceSnapPoints()
  end
  if flagName == 'ValueChart' then
    refreshValueChart() -- show/hide the chart tiles immediately
  end
  if FLAGS.Automode then
    refreshActivePlayerCount()
    updateChipsOnPlayers()
  else
    cancelCountdown()
  end
  hideHandRankObjects()
end

-- Toggles a setup FLAG from the Admin Board (replaces the old per-tile toggleFlag). Keyed by
-- flag name — the board is one object, so GMNotes can't disambiguate its buttons. Mid-game a
-- non-instant flag (its module's applyTiming) is deferred: the toggle shows light-red ("pending")
-- and the flip is committed by applyPendingAdminChanges() at the next round/heist start.
function setBoardFlag(flagName, playerColor)
  if not antiTrollClearance(playerColor) then return end
  if FLAGS[flagName] == nil then
    broadcastToAll(LANG(STRINGS.MSG_NO_FLAGS))
    return
  end

  local def, item = findAdminFlagDef(flagName)
  local runtime = item and adminBoardState.runtime[item]
  -- Toggle relative to the pending target if one is awaiting, else the live flag.
  local base
  if runtime and runtime.pending ~= nil then base = runtime.pending else base = FLAGS[flagName] end
  local target = not base

  -- Seat-count limits apply to the would-be ENABLED state (whether immediate or pending).
  if target == true and flagName == 'TwoHand' then
    if #getSeatedPlayers() > 5 then
      broadcastToAll(LANG(STRINGS.MSG_2HAND_MAX_ENABLE))
      return
    end
    -- Enabling 2Hand would double the hand count; Short Deck caps it at 4 hands.
    if FLAGS.ShortDeck and (#getSeatedPlayers() * 2) > 4 then
      broadcastToAll(LANG(STRINGS.MSG_SHORTDECK_MAX_ENABLE))
      return
    end
  end
  if target == true and flagName == 'ShortDeck' then
    -- Short Deck (36-card deck) can't supply hole + community cards for more than 4 hands.
    if (#getSeatedPlayers() * (FLAGS.TwoHand and 2 or 1)) > 4 then
      broadcastToAll(LANG(STRINGS.MSG_SHORTDECK_MAX_ENABLE))
      return
    end
  end

  if def and adminChangeDeferred(def) then
    -- Defer: record the pending target (or clear it if it matches the live flag again), repaint.
    if runtime then
      if target == FLAGS[flagName] then runtime.pending = nil else runtime.pending = target end
    end
    updateAdminModule(def)
    soundeffect.AssetBundle.playTriggerEffect(0)
    if runtime and runtime.pending ~= nil then
      broadcastToColor(LANG(STRINGS.MSG_ADMIN_PENDING_NEXT, item.label or def.label), playerColor, colorGoldVector)
    end
    return
  end

  -- Instant / setup: apply now.
  if runtime then runtime.pending = nil end
  commitFlagChange(flagName, target)
  soundeffect.AssetBundle.playTriggerEffect(0)
  -- A setup flag (e.g. Short Deck) can suppress challenges — refresh the "X" preview during setup
  -- (#14). Skip during a game (deferred flags don't take effect until the next round start).
  if not isGameInProgress() then
    refreshIncompatibleChallengeXMarks()
  end
end

-- Applies every pending (deferred) Admin Board change whose module timing matches `timing`
-- ("gameStart" at round 1, "roundStart" at each round start). Commits the value, repaints the
-- control from light-red back to gold, and clears the pending state.
function applyPendingAdminChanges(timing)
  local L = ADMIN_BOARD_LAYOUT
  for _, def in ipairs(ADMIN_BOARD) do
    if getAdminTiming(def) == timing then
      if def.module == "slider" then
        local runtime = adminBoardState.runtime[def]
        if runtime and runtime.pendingIdx then
          if adminBoardObj then
            adminBoardObj.editButton({ index = runtime.optionIndices[runtime.currentIdx], color = L.optionColor })
            adminBoardObj.editButton({ index = runtime.optionIndices[runtime.pendingIdx], color = L.optionColorActive })
          end
          runtime.currentIdx = runtime.pendingIdx
          runtime.pendingIdx = nil
          def.set(def.options[runtime.currentIdx].value)
        end
      elseif def.module == "toggle" then
        local runtime = adminBoardState.runtime[def]
        if runtime and runtime.pending ~= nil then
          local target = runtime.pending
          runtime.pending = nil
          commitFlagChange(def.flag, target)
        end
      elseif def.module == "toggles" then
        for _, item in ipairs(def.items) do
          local runtime = adminBoardState.runtime[item]
          if runtime and runtime.pending ~= nil then
            local target = runtime.pending
            runtime.pending = nil
            commitFlagChange(item.flag, target)
          end
        end
      end
    end
  end
end

-- Finds the toggle module driving flagName and refreshes its label.
function updateBoardFlag(flagName)
  for _, def in ipairs(ADMIN_BOARD) do
    if def.module == "toggle" and def.flag == flagName then
      updateAdminModule(def)
      return
    elseif def.module == "toggles" then
      for _, item in ipairs(def.items) do
        if item.flag == flagName then
          updateAdminModule(def) -- grid update relabels all its items
          return
        end
      end
    end
  end
end

-- Steps a slider by dir (-1 / +1), wrapping around at the ends (circular: past the last option
-- jumps to the first, and before the first jumps to the last).
function adminSliderStep(def, dir, playerColor)
  if not antiTrollClearance(playerColor) then return end
  local runtime = adminBoardState.runtime[def]
  if not runtime then return end
  local count = #def.options
  -- Step from the pending selection if one is awaiting (so arrows nudge the light-red preview).
  local base = runtime.pendingIdx or runtime.currentIdx
  local newIdx = ((base - 1 + dir) % count) + 1
  adminSliderApply(def, newIdx, playerColor)
end

-- Jumps a slider straight to a clicked option index. Right-clicking (altClick) the already-selected
-- option fires the optional def.onAltJump hook instead of re-selecting (used by the CPU-mode slider's
-- Disabled option for a one-shot recalc).
function adminSliderJump(def, optionIdx, playerColor, altClick)
  if not antiTrollClearance(playerColor) then return end
  local runtime = adminBoardState.runtime[def]
  if not runtime then return end
  if altClick and def.onAltJump then
    def.onAltJump(optionIdx, playerColor)
    return
  end
  -- Already selected with nothing pending → nothing to do. (Clicking the current option while a
  -- pending change exists is allowed: it cancels the pending preview, handled in adminSliderApply.)
  if optionIdx == runtime.currentIdx and not runtime.pendingIdx then return end
  if optionIdx == runtime.pendingIdx then return end -- already the pending choice
  adminSliderApply(def, optionIdx, playerColor)
end

-- Applies (or defers) a slider selection. Mid-game, a non-instant control is deferred: the chosen
-- option is marked light-red ("pending") while the current value stays gold, and the change is
-- committed later by applyPendingAdminChanges() at the next round/heist start. Otherwise it applies
-- immediately: moves the gold highlight, sets the state var, and announces it.
function adminSliderApply(def, newIdx, playerColor)
  local runtime = adminBoardState.runtime[def]
  if not runtime then return end
  if not adminBoardObj then return end
  local L = ADMIN_BOARD_LAYOUT
  local opt = def.options[newIdx]

  if adminChangeDeferred(def) then
    -- Clear any previous pending highlight back to the inactive color.
    if runtime.pendingIdx and runtime.pendingIdx ~= runtime.currentIdx then
      adminBoardObj.editButton({ index = runtime.optionIndices[runtime.pendingIdx], color = L.optionColor })
    end
    if newIdx == runtime.currentIdx then
      runtime.pendingIdx = nil -- clicking the active option cancels the pending preview
    else
      runtime.pendingIdx = newIdx
      adminBoardObj.editButton({ index = runtime.optionIndices[newIdx], color = L.optionColorPending })
    end
    -- Keep the live value gold (also restores it if newIdx happened to equal it).
    adminBoardObj.editButton({ index = runtime.optionIndices[runtime.currentIdx], color = L.optionColorActive })
    soundeffect.AssetBundle.playTriggerEffect(0)
    if playerColor and runtime.pendingIdx then
      broadcastToColor(LANG(STRINGS.MSG_ADMIN_PENDING_NEXT, opt.label), playerColor, colorGoldVector)
    end
    return
  end

  -- Instant / setup: apply now, clearing any leftover pending highlight first.
  if runtime.pendingIdx and runtime.pendingIdx ~= newIdx then
    adminBoardObj.editButton({ index = runtime.optionIndices[runtime.pendingIdx], color = L.optionColor })
  end
  runtime.pendingIdx = nil
  adminBoardObj.editButton({ index = runtime.optionIndices[runtime.currentIdx], color = L.optionColor })
  adminBoardObj.editButton({ index = runtime.optionIndices[newIdx], color = L.optionColorActive })
  runtime.currentIdx = newIdx
  def.set(opt.value)
  soundeffect.AssetBundle.playTriggerEffect(0)
  broadcastToAll(LANG(def.msg, opt.label))
  -- Changing the game mode can suppress challenges — refresh the "X" preview during setup (#14).
  -- Mode changes only take effect at the next round start, so skip while a game is in progress.
  if def.key == "gameMode" and not isGameInProgress() then
    refreshIncompatibleChallengeXMarks()
    refreshValueChart() -- move the value chart tile to the newly selected mode's position
  end
end

-- Displays large centered text overlay on screen (e.g. countdown numbers).
function showBigText(text)
  bigTextContent = text
  if hasActiveJokerPanels() or hasActiveDealerPanel() then
    -- Active panels — avoid rebuilding XML which resets drag positions
    UI.setAttribute("bigCountdown", "text", text)
    UI.show("bigCountdown")
  else
    refreshGlobalUI()
  end
end

-- Hides the big text overlay from screen.
function hideBigText()
  bigTextContent = nil
  if hasActiveJokerPanels() or hasActiveDealerPanel() then
    UI.hide("bigCountdown")
  else
    refreshGlobalUI()
  end
end

------------------------------------------------------------------------
-- Value Chart Tile
-- A flat tile showing the deck's live card-value order (low → high), and,
-- when at least one Math Wiz specialist is active, a second row with each
-- value's Math Wiz face value. The chart reflects the same evaluation flags
-- that shape the deck this game: Short Deck (2-5 removed), Extra Hours
-- (extended B/C/D), Cluttered Toolbox (a value blanked → Ø), and Quantum
-- Chaos (reversed order). Driven from global.lua so it can refresh the
-- moment those flags or Math Wiz change — no polling needed.
------------------------------------------------------------------------

-- Returns the ordered list of card values currently in the deck. Each entry:
--   { label = "<display>", math = <Math Wiz face value> }.
-- Order is low → high, or high → low when Quantum Chaos reverses ranking.
function getDeckValueChart()
  -- Single baseline built up conditionally: 6-A is always in the deck; 2-5 exist
  -- only outside Short Deck; B/C/D only with Extra Hours (extended values).
  local ordered = { "6", "7", "8", "9", "10", "J", "Q", "K", "A" }
  if not shortDeck then
    for _, v in ipairs({ "5", "4", "3", "2" }) do table.insert(ordered, 1, v) end
  end
  if extendedValues then
    for _, v in ipairs({ "B", "C", "D" }) do table.insert(ordered, v) end
  end
  -- Cluttered Toolbox removes its blanked value from the deck.
  local values = {}
  for _, v in ipairs(ordered) do
    if v ~= blankedValue then table.insert(values, v) end
  end
  -- Quantum Chaos: ranking reverses (highest card becomes the lowest). The chart always reads
  -- low rank → high rank left→right, so reversing the list re-sorts the display accordingly.
  if not sortNormal then
    local reversed = {}
    for i = #values, 1, -1 do table.insert(reversed, values[i]) end
    values = reversed
  end
  -- Cluttered Toolbox (and, later, Too Many Colors) adds a Ø (value-0) group. Ø is ALWAYS the
  -- lowest rank regardless of Quantum Chaos, so it always sits at the leftmost (low) position.
  -- It never joins a straight/flush.
  -- TODO(too-many-colors): also add "0" when the all-suit-wilds challenge is active.
  if activeChallenges.CLUTTERED_TOOLBOX and blankedValue or activeChallenges.TOO_MANY_COLORS then
    table.insert(values, 1, "0")
  end

  local chart = {}
  for _, v in ipairs(values) do
    local label = (v == "0") and LANG_NOTAGS(STRINGS.CARD_BLANKED) or v
    table.insert(chart, { label = label, math = getCardFaceValue(v) })
  end
  return chart
end

-- Draws the value chart (value row + Math Wiz row when active) onto a specific tile
-- object at the given placement { position, rotation }. Shared by every chart tile.
function drawValueChartOn(tileObj, placement)
  if not tileObj or tileObj.isDestroyed() then return end
  local L = valueChartLayout

  if placement then
    tileObj.setPosition(placement.position)
    tileObj.setRotation(placement.rotation)
  end

  tileObj.clearButtons()

  local chart = getDeckValueChart()
  local n = #chart
  if n == 0 then return end
  local mathActive = next(mathWizData) ~= nil

  local startX = -((n - 1) / 2) * L.columnSpacing

  -- Header
  tileObj.createButton({
    click_function = "doNothing",
    label          = LANG(STRINGS.VALUE_CHART_HEADER),
    position       = { 0, L.labelY, L.headerZ },
    width          = 0,
    height         = 0,
    font_size      = L.headerFontSize,
    font_color     = colorGoldVector,
  })

  if mathActive then
    tileObj.createButton({
      click_function = "doNothing",
      label          = LANG(STRINGS.VALUE_CHART_MATHWIZ),
      position       = { 0, L.labelY, L.mathHeaderZ },
      width          = 0,
      height         = 0,
      font_size      = L.headerFontSize,
      font_color     = colorWhiteVector,
    })
  end

  -- One column per value: label row on top, Math Wiz value below (when active).
  for i, entry in ipairs(chart) do
    local x = startX + (i - 1) * L.columnSpacing
    tileObj.createButton({
      click_function = "doNothing",
      label          = entry.label,
      position       = { x, L.labelY, L.labelZ },
      width          = 0, --L.buttonWidth,
      height         = 0, --L.buttonHeight,
      font_size      = L.fontSize,
      color          = colorDarkBlueVector,
      font_color     = colorWhiteVector,
    })
    if mathActive then
      tileObj.createButton({
        click_function = "doNothing",
        label          = tostring(entry.math),
        position       = { x, L.labelY, L.mathZ },
        width          = 0, --L.buttonWidth,
        height         = 0, --L.buttonHeight,
        font_size      = L.fontSizeMath,
        color          = colorDarkBlueVector,
        font_color     = colorGoldVector,
      })
    end
  end
end

-- Rebuilds every value chart tile: the primary (all modes, positioned per game mode)
-- and the secondary (Texas Hold'em only, mirrored across X; blank in other modes).
function refreshValueChart()
  -- System toggle off → hide both chart tiles entirely.
  if FLAGS and FLAGS.ValueChart == false then
    if valueChartTileObj and not valueChartTileObj.isDestroyed() then valueChartTileObj.clearButtons() end
    if valueChartTile2Obj and not valueChartTile2Obj.isDestroyed() then valueChartTile2Obj.clearButtons() end
    return
  end

  -- Primary chart — shown in every mode. Use the UI-selected mode so it previews correctly
  -- during setup; it equals the locked activeGameMode once a round is running.
  local modeCfg = valueChartPositionByMode[gameMode] or valueChartPositionByMode[0]
  drawValueChartOn(valueChartTileObj, modeCfg)

  -- Secondary chart — Texas Hold'em (mode 0) only. Cleared in every other mode.
  -- Placement mirrors the primary Texas position across X (rest identical), computed from
  -- valueChartPositionByMode[0] so tuning the primary keeps the mirror in sync.
  if valueChartTile2Obj and not valueChartTile2Obj.isDestroyed() then
    if gameMode == 0 then
      local base = valueChartPositionByMode[0]
      local placement = {
        position = { x = -base.position.x, y = base.position.y, z = base.position.z },
        rotation = base.rotation,
      }
      drawValueChartOn(valueChartTile2Obj, placement)
    else
      valueChartTile2Obj.clearButtons()
    end
  end
end

-- Returns true if any player has active joker choice panels
function hasActiveJokerPanels()
  for _, _ in pairs(jokerPendingUI) do
    return true
  end
  return false
end

------------------------------------------------------------------------
-- Global UI Management
-- Uses a snapshot approach: only calls UI.setXml when the set of active
-- panels changes (structural change). Content-only updates use
-- UI.setAttribute to avoid resetting dragged panel positions.
------------------------------------------------------------------------
uiCurrentSnapshot = "" -- fingerprint of which panels are active

function buildUISnapshot()
  local parts = {}
  if bigTextContent then table.insert(parts, "BT") end
  for color, _ in pairs(jokerPendingUI) do
    if jokerQueue[color] then
      for _, entry in ipairs(jokerQueue[color]) do
        table.insert(parts, "J" .. color .. entry.id)
      end
    end
  end
  if dealerPendingUI then
    local pendingJokerCount = 0
    for _, _ in pairs(dealerJokerReplacements) do pendingJokerCount = pendingJokerCount + 1 end
    local dealerPhase = pendingJokerCount > 0 and ("J" .. pendingJokerCount) or tostring(dealerChosenCount or 0)
    table.insert(parts, "D" .. dealerPendingUI .. dealerPhase)
  end
  if handRankFrozen then table.insert(parts, "RH" .. revealCurrentTurn) end
  for color, _ in pairs(handRankInfoPanelOpen) do
    table.insert(parts, "HRI" .. color)
  end
  for color, s in pairs(statsOverlay) do
    if s.open then
      table.insert(parts, "STATS|" .. color .. "|" .. s.view .. "|" .. s.scope
        .. "|" .. tostring(s.round) .. "|" .. (s.search or "")
        .. "|" .. tostring(s.playerKey) .. "|" .. tostring(s.gameId)
        .. "|" .. tostring(s.connectedOnly))
    end
  end
  if challengeVoteState and not challengeVoteState.hidden then
    local cv = { "CVOTE" }
    if challengeVoteState.reviewing then table.insert(cv, "reviewing") end
    for _, k in ipairs(challengeVoteState.kinds) do
      table.insert(cv, k)
      if challengeVoteState.skipArmed[k] then table.insert(cv, k .. "#armed") end
      if challengeVoteState.closed[k] then
        local r = challengeVoteState.result[k] or {}
        table.insert(cv, k .. "#" .. (r.status or "") .. ":" .. (r.option or ""))
      end
      for color, v in pairs(challengeVoteState.votes[k] or {}) do
        table.insert(cv, k .. ":" .. color .. "=" .. v)
      end
    end
    table.sort(cv)
    table.insert(parts, table.concat(cv, "|"))
  end
  table.sort(parts)
  return table.concat(parts, "|")
end

function refreshGlobalUI()
  local newSnapshot = buildUISnapshot()
  local structureChanged = (newSnapshot ~= uiCurrentSnapshot)

  if structureChanged then
    -- Full rebuild — panels were added or removed
    uiCurrentSnapshot = newSnapshot
    local xmlParts = {}

    -- Always emit the bigCountdown element (hidden when no content) so that
    -- showBigText's fast path (UI.setAttribute + UI.show) works even when a
    -- joker or dealer panel is open. If we only emitted it when bigTextContent
    -- was set, a rebuild triggered while no big text was active (e.g. opening a
    -- replacement joker panel) would omit the element, and a later flash would
    -- silently fail because there is nothing to show/update.
    table.insert(xmlParts,
      '<Text id="bigCountdown" active="' .. (bigTextContent and "true" or "false") ..
      '" fontSize="150" color="#FFFF00" alignment="MiddleCenter" offsetXY="0 250" fontStyle="Bold">'
      .. (bigTextContent or "") .. '</Text>')

    for color, _ in pairs(jokerPendingUI) do
      local panelXml = buildJokerChoiceXml(color)
      if panelXml then table.insert(xmlParts, panelXml) end
    end

    if dealerPendingUI then
      local panelXml = buildDealerChoiceXml(dealerPendingUI)
      if panelXml then table.insert(xmlParts, panelXml) end
    end

    if handRankFrozen then
      local revealColors = {}
      for _, color in ipairs(getSeatedPlayers()) do
        if color ~= "Grey" and color ~= "Black" then
          -- Skip players who have no hand cards (e.g. joined after cards were dealt)
          local hasCards = dealtCards[color] and dealtCards[color]["Top"] and #dealtCards[color]["Top"] > 0
          if hasCards then
            -- In non-TwoHand mode, exclude players who already revealed their hand
            if not FLAGS.TwoHand then
              if not (revealedHandCards[color] and revealedHandCards[color]["Top"]) then
                table.insert(revealColors, color)
              end
            else
              table.insert(revealColors, color)
            end
          end
        end
      end
      if #revealColors > 0 then
        local currentEntry = revealTurnOrder[revealCurrentTurn]
        if FLAGS.TwoHand then
          -- Build per-button visibility: exclude players who already revealed that hand
          local topViewers, botViewers = {}, {}
          for _, rc in ipairs(revealColors) do
            if not (revealedHandCards[rc] and revealedHandCards[rc]["Top"]) then
              table.insert(topViewers, rc)
            end
            if not (revealedHandCards[rc] and revealedHandCards[rc]["Bot"]) then
              table.insert(botViewers, rc)
            end
          end
          -- Split each list into active (current turn entry matches color+hand) and waiting (greyed out)
          local topActive, topWaiting, botActive, botWaiting = {}, {}, {}, {}
          for _, rc in ipairs(topViewers) do
            if currentEntry and rc == currentEntry.color and currentEntry.hand == "Top" then
              table.insert(topActive, rc)
            else
              table.insert(topWaiting, rc)
            end
          end
          for _, rc in ipairs(botViewers) do
            if currentEntry and rc == currentEntry.color and currentEntry.hand == "Bot" then
              table.insert(botActive, rc)
            else
              table.insert(botWaiting, rc)
            end
          end
          if #topActive > 0 then
