          end
          if #botWaiting > 0 then
            table.insert(xmlParts,
              '<Panel id="revealHandPanelBotWaiting" visibility="' .. table.concat(botWaiting, "|") ..
              '" rectAlignment="LowerCenter" offsetXY="0 60" width="220" height="55">'
              ..
              '<Button id="revealHandBtnBotWaiting" onClick="onRevealHandClick" colors="#444444FF|#555555FF|#333333FF|#444444FF" preferredWidth="220" preferredHeight="55">'
              .. '<Text fontSize="22" color="#777777" alignment="MiddleCenter">Reveal Bot</Text></Button>'
              .. '</Panel>')
          end
        else
          -- Split into active (current turn) and waiting (greyed out)
          local activeVis = nil
          local waitingColors = {}
          for _, rc in ipairs(revealColors) do
            if currentEntry and rc == currentEntry.color then activeVis = rc else table.insert(waitingColors, rc) end
          end
          if activeVis then
            table.insert(xmlParts,
              '<Panel id="revealHandPanel" visibility="' ..
              activeVis .. '" rectAlignment="LowerCenter" offsetXY="0 60" width="220" height="55">'
              ..
              '<Button id="revealHandBtn" onClick="onRevealHandClick" colors="#335533FF|#447744FF|#223322FF|#112211FF" preferredWidth="220" preferredHeight="55">'
              .. '<Text id="revealHandTxt" fontSize="22" color="#44FF44" alignment="MiddleCenter">Reveal Hand</Text></Button>'
