              .. '</Panel>')
          end
        end

        -- Host/promoted override reveal button — single button targeting the current turn entry.
        -- Visible to all host/promoted players; shows current player name; double-click to confirm.
        local hostColors = getHostPromotedColors()
        if #hostColors > 0 and currentEntry then
          local targetColor = currentEntry.color
          local targetHex   = "#" .. colorToRGBHex(targetColor)
          local targetName  = getPlayerDisplayName(targetColor)
          local yOffset     = FLAGS.TwoHand and "190" or "125"
          local btnText, btnBg
          if revealOverridePendingConfirm == revealCurrentTurn then
            btnText = LANG_NOTAGS(STRINGS.MSG_REVEAL_OVERRIDE_SURE, targetName)
            btnBg   = "#553300FF|#774400FF|#331100FF|#553300FF"
          else
            btnText = targetName
            btnBg   = "#2A2A2AFF|#3A3A3AFF|#1A1A1AFF|#2A2A2AFF"
          end
          table.insert(xmlParts,
            '<Panel id="revealOverridePanel" visibility="' .. table.concat(hostColors, "|") ..
            '" rectAlignment="LowerCenter" offsetXY="0 ' .. yOffset .. '" width="200" height="40">' ..
