            targetHex .. '" alignment="MiddleCenter">' .. btnText .. '</Text>' ..
            '</Button></Panel>')
        end
      end
    end

    for color, _ in pairs(handRankInfoPanelOpen) do
      table.insert(xmlParts, buildHandRankInfoXml(color))
    end

    for color, s in pairs(statsOverlay) do
      if s.open then
        table.insert(xmlParts, buildStatsOverlayXml(color))
      end
    end

    if challengeVoteState and not challengeVoteState.hidden then
      for i, k in ipairs(challengeVoteState.kinds) do
        table.insert(xmlParts, buildChallengeVoteXml(k, i, #challengeVoteState.kinds))
      end
    end

    UI.setXml(table.concat(xmlParts, "\n"))
  else
    -- Content-only update — same panels, just update their contents via setAttribute
    if bigTextContent then
      UI.setAttribute("bigCountdown", "text", bigTextContent)
    end

    -- Hand rank info panels content update
    for color, _ in pairs(handRankInfoPanelOpen) do
      updateHandRankInfoContent(color)
    end
  end
end

