-- Locks decorative objects and sets them non-interactable.
function setupDecoObjects()
  if decoObjGUIDs then
    for _, decoObjGroups in pairs(decoObjGUIDs) do
      for _, decoObj in ipairs(decoObjGroups) do
        local obj = getObjectFromGUID(decoObj)
        if obj then
          obj.interactable = false
          obj.setLock(true)
        end
      end
    end
  end
end

-- Update the Text uptop the vault bag to show the current number of vaults in the bag
-- e.g. "2 / 5" if there are currently 2 vaults in the bag out of a total of 5
function updateVaultButtonLabel()
  if not bagVaultObj then return end
  local total = 5 -- Default Max Number of Vaults

  local bagVaultObjContents = bagVaultObj.getObjects()
  local vaultCount = 0
  for _, obj in ipairs(bagVaultObjContents) do
    for _, tag in ipairs(obj.tags or {}) do
      if tag == TAGS.vault then
        vaultCount = vaultCount + 1
        break
      end
    end
  end

  local label = vaultCount .. " / " .. total
  bagVaultObj.editButton({ index = 0, label = label })

  -- When all 5 vaults are back in the bag, play looping effect 1 (closing door)
  -- Else play looping effect 0 (opening door)
  if vaultCount >= 5 then
    bagVaultObj.AssetBundle.playLoopingEffect(1)
  else
    bagVaultObj.AssetBundle.playLoopingEffect(0)
  end

  updateDecoVisibility(vaultCount)
end

-- Show/hide loot deco objects based on vault count with staggered animation.
-- Iterates decoLootTiers from tier 5 down to 1; tier[v] visible when vaultCount >= v.
function updateDecoVisibility(vaultCount)
  decoLootAnimVersion = decoLootAnimVersion + 1
  local myVersion = decoLootAnimVersion

  for v = 5, 1, -1 do
    local tier = decoLootTiers[v]
    if tier then
      local shouldBeVisible = (vaultCount >= v)
      local elapsed = tier.extraDelay or 0
      for _, guid in ipairs(tier.guids) do
        local delay = elapsed
        elapsed = elapsed + (tier.stagger or 0)
        Wait.time(function()
          if decoLootAnimVersion ~= myVersion then return end
          local obj = getObjectFromGUID(guid)
          if obj then
            if shouldBeVisible then
              obj.setInvisibleTo({})
            else
              obj.setInvisibleTo(Player.getColors())
            end
          end
        end, delay)
      end
    end
  end
end

-- Instantly show all loot deco objects after a 1-second delay (no stagger). Used by vault reset.
function resetDecoVisibility()
  decoLootAnimVersion = decoLootAnimVersion + 1
  local myVersion = decoLootAnimVersion
  Wait.time(function()
    if decoLootAnimVersion ~= myVersion then return end
    for v = 1, 5 do
      local tier = decoLootTiers[v]
      if tier then
        for _, guid in ipairs(tier.guids) do
          local obj = getObjectFromGUID(guid)
          if obj then
            obj.setInvisibleTo({})
          end
        end
      end
    end
  end, 2)
end

-- Resolves player object GUIDs into live references and builds handZoneLookup.
function playerSetup()
  -- Set up player objects based on GUIDs and positions

  for color, params in pairs(playerParameters) do
    local topHandObj = getObjectFromGUID(params.topHandGUID)
    if topHandObj then
      playerParameters[color].topHandObj = topHandObj
    end

    local toolHandObj = getObjectFromGUID(params.toolHandGUID)
    if toolHandObj then
      playerParameters[color].toolHandObj = toolHandObj
      toolHandZoneLookup[params.toolHandGUID] = color
    end

    local botHandObj = getObjectFromGUID(params.botHandGUID)
    if botHandObj then
      playerParameters[color].botHandObj = botHandObj
    end

    local namePlateObj = getObjectFromGUID(params.nameplateGUID)
    if namePlateObj then
      playerParameters[color].namePlateObj = namePlateObj
    end

    local topHandRankObj = getObjectFromGUID(params.topHandRankGUID)
    if topHandRankObj then
      playerParameters[color].topHandRankObj = topHandRankObj

      createhandRankObjects(topHandRankObj)
    end

    local botHandRankObj = getObjectFromGUID(params.botHandRankGUID)
    if botHandRankObj then
      playerParameters[color].botHandRankObj = botHandRankObj

      createhandRankObjects(botHandRankObj)
    end

    -- Build hand zone lookup for event-driven joker detection
    if topHandObj then
      handZoneLookup[params.topHandGUID] = { color = color, source = "Top" }
    end
    if botHandObj then
      handZoneLookup[params.botHandGUID] = { color = color, source = "Bot" }
    end

    local topScriptZone = getObjectFromGUID(params.topScriptZoneGUID)
    if topScriptZone then
      topScriptZone.setRotation({ 0, 0, 0 })
      playerParameters[color].topScriptZoneObj = topScriptZone
    end

    local botScriptZone = getObjectFromGUID(params.botScriptZoneGUID)
    if botScriptZone then
      botScriptZone.setRotation({ 0, 0, 0 })
      playerParameters[color].botScriptZoneObj = botScriptZone
    end

    local topChipSpace = getObjectFromGUID(params.chipSpaceTopGUID)
    if topChipSpace then
      topChipSpace.interactable = DEFAULT_INTERACTABLE
      topChipSpace.setLock(true)
      playerParameters[color].topChipSpaceObj = topChipSpace
      topChipSpace.setColorTint({ 0.5, 0.5, 0.5 })
    end

    local botChipSpace = getObjectFromGUID(params.chipSpaceBotGUID)
    if botChipSpace then
      botChipSpace.interactable = DEFAULT_INTERACTABLE
      botChipSpace.setLock(true)
      playerParameters[color].botChipSpaceObj = botChipSpace

      botChipSpace.setColorTint({ 0.5, 0.5, 0.5 })
    end

    local dealerTile = getObjectFromGUID(params.dealerChipTileGUID)
    if dealerTile then
      dealerTile.interactable = DEFAULT_INTERACTABLE
      dealerTile.setLock(true)
      playerParameters[color].dealerChipTileObj = dealerTile
      dealerTile.setSnapPoints({
        { position = { 0, 0.4, 0 }, rotation = { 0, 0, 0 }, rotation_snap = true }
      })
    end

    local dealerScriptZone = getObjectFromGUID(params.dealerChipScriptZoneGUID)
    if dealerScriptZone then
      dealerScriptZone.setRotation({ 0, 0, 0 })
      playerParameters[color].dealerChipScriptZoneObj = dealerScriptZone
    end
  end

  setChipSpaceSnapPoints()
  updatePlayerMats()
end

-- Sets snap points on chip space objects for proper chip placement.
-- Bot chip spaces only get snap points in TwoHand mode (otherwise they're hidden but still snap).
function setChipSpaceSnapPoints()
  local chipSpaceSnaps = {}
  for chipColor, chipPosition in pairs(chipSpaceSnapPositions) do
    table.insert(chipSpaceSnaps, {
      position = {
        x = chipPosition.x,
        y = chipPosition.y,
        z = chipPosition.z
      },
      tag = chipColor
    })
  end
  for _, params in pairs(playerParameters) do
    if params.topChipSpaceObj then
      params.topChipSpaceObj.setSnapPoints(chipSpaceSnaps)
    end
    if params.botChipSpaceObj then
      if FLAGS.TwoHand then
        params.botChipSpaceObj.setSnapPoints(chipSpaceSnaps)
      else
        params.botChipSpaceObj.setSnapPoints({})
      end
    end
  end
end

-- Removes all snap points from chip space objects to prevent cards sticking at showdown.
function clearChipSpaceSnapPoints()
  for _, params in pairs(playerParameters) do
    if params.topChipSpaceObj then
      params.topChipSpaceObj.setSnapPoints({})
    end
    if params.botChipSpaceObj then
      params.botChipSpaceObj.setSnapPoints({})
    end
  end
end

