-- Builds a freshly shuffled cycle of every name a seat can show: the real name plus all
-- of its funny replacements. Stepping through this (rather than re-rolling each click) means
-- the admin visits every option once before any repeats, instead of bouncing between two.
-- avoidFirst (optional) keeps the new shuffle from opening on the name already displayed,
-- so reshuffling at the seam never looks like a no-op repeat.
local function buildNameCycle(color, avoidFirst)
  local realName = getPlayerDisplayName(color)
  local order = { realName }
  local options = nameReplacements and nameReplacements[realName]
  if options then
    for _, option in ipairs(options) do
      order[#order + 1] = option
    end
  end

  -- Fisher-Yates shuffle.
  for i = #order, 2, -1 do
    local j = math.random(i)
    order[i], order[j] = order[j], order[i]
  end

  -- If the shuffle happens to lead with the currently shown name and there is another
  -- option, swap it away from the front so the next click is always a visible change.
  if avoidFirst and #order > 1 and order[1] == avoidFirst then
    order[1], order[2] = order[2], order[1]
  end

  return order
end

-- Steps a seat's nameplate to the next name in its shuffled cycle (admin right-click).
function advanceNameVariant(color)
  local realName = getPlayerDisplayName(color)
  local options = nameReplacements and nameReplacements[realName]
  if not options or #options == 0 then return end

  local order = nameCycleOrder[color]
  local index = (nameCycleIndex[color] or 0) + 1
  if not order or index > #order then
    -- Exhausted (or first use): reshuffle, avoiding an immediate repeat of the shown name.
    order = buildNameCycle(color, nameVariants[color] or realName)
    nameCycleOrder[color] = order
    index = 1
  end
  nameCycleIndex[color] = index

  local chosen = order[index]
  -- nil means "show the real name"; updateNameplates only overrides when a variant is set.
  nameVariants[color] = (chosen == realName) and nil or chosen
  updateNameplates()
end

-- Toggles hand rank visibility when a player clicks their own nameplate.
function onNamePlateClick(obj, playerColor, alt_click)
  -- Only allow the seated player at this nameplate to toggle their own hand rank
  local seatColor = obj.getGMNotes()
  if not seatColor or seatColor == "" then return end
  if not isPlayerSeated(seatColor) then return end

  -- Only the player sitting in this seat can toggle
  if playerColor ~= seatColor and Player[playerColor] and not randomCheck(Player[playerColor]) then
    return
  end

  if alt_click and Player[playerColor] and randomCheck(Player[playerColor]) then
    advanceNameVariant(seatColor)
    return
  end

  handRankDisabled[seatColor] = not handRankDisabled[seatColor]

  if handRankDisabled[seatColor] then
    broadcastToColor(LANG(STRINGS.MSG_HAND_RANK_OFF), seatColor, { 1, 0.3, 0.3 })
  else
    broadcastToColor(LANG(STRINGS.MSG_HAND_RANK_ON), seatColor, { 0.3, 1, 0.3 })
  end

  -- Immediately update display
  hideHandRankObjects()
end

-- Updates nameplate labels with seated player names and applies color tints.
function updateNameplates()
  -- update Nameplates with the seated players' names and colors
  -- also update the ChipSpace color tints to match the color

  for color, params in pairs(playerParameters) do
    -- Get the nameplate
    local namePlateObj = params.namePlateObj
    local topChipSpaceObj = params.topChipSpaceObj
    local botChipSpaceObj = params.botChipSpaceObj
    if isPlayerSeated(color) then
      local playerName = getPlayerDisplayName(color)

      -- Deterministic render: only show an override when one was explicitly set (admin
      -- right-click, or the round-start roll in rollNameVariants). The random chance lives
      -- there, NOT here, so refreshing one nameplate never re-rolls everyone else's.
      if nameVariants[color] then
        playerName = nameVariants[color]
      end

      -- Truncate over-long names (variants / random replacements included) before sizing.
      -- The 1/width font formula in calculateFontSize shrinks wide names to fit, so this cap
      -- only guards against unreadably small fonts — raised a little now that sizing is better.
      if utf8CharLength(playerName) > 18 then
        playerName = utf8SubChars(playerName, 17) .. "…"
      end

      local fontSize = calculateFontSize(playerName)
      if namePlateObj then
        namePlateObj.editButton({
          index = 0,
          label = playerName,
          font_color = color, --{ 1, 1, 1 },
          color = { 0, 0, 0 },
          font_size = fontSize,
          width = 4500,
          height = 1000,
        })
        namePlateObj.setColorTint(color)
      end
      if topChipSpaceObj then topChipSpaceObj.setColorTint(color) end
      if botChipSpaceObj then botChipSpaceObj.setColorTint(color) end
    else
      if namePlateObj then
        namePlateObj.editButton({
          index = 0,
          label = "",
          font_color = { 0, 0, 0 },
          color = { 0, 0, 0 },
          font_size = 1000,
          width = 0,
          height = 0,
        })
        namePlateObj.setColorTint({ 0.5, 0.5, 0.5 })
      end
      if topChipSpaceObj then topChipSpaceObj.setColorTint({ 0.5, 0.5, 0.5 }) end
      if botChipSpaceObj then botChipSpaceObj.setColorTint({ 0.5, 0.5, 0.5 }) end
    end
  end
end

-- Round-start roll: each seated player has a 1% chance to have their nameplate show a funny
-- alternative for the round. The result is persisted into nameVariants so it stays stable
-- across every updateNameplates() re-render — clicking one nameplate can't re-roll another.
function rollNameVariants()
  for color in pairs(playerParameters) do
    if isPlayerSeated(color) then
      local realName = getPlayerDisplayName(color)
      local options = nameReplacements and nameReplacements[realName]
      if options and #options > 0 and math.random(100) > 99 then
        nameVariants[color] = options[math.random(1, #options)]
      end
    end
  end
end

