--- SECTION 7: Chip Management
------------------------------------

-- Recalculates numPlayersStartofRound from currently seated players.
-- Called when automode is toggled or when players join/leave during an active round,
-- so the chip threshold stays in sync with the actual player count.
function refreshActivePlayerCount()
  if round < 1 then return end
  local count = #getActiveParticipants() -- benched mid-game joiners (#19) don't count toward the threshold
  if FLAGS.TwoHand then count = count * 2 end
  numPlayersStartofRound = count
end

-- Counts current-round chips on player zones and triggers automode countdown when all placed.
function updateChipsOnPlayers()
  local chipRound = round - 1
  if chipRound < 1 or chipRound > 4 then return end

  -- Build a set of valid chip GUIDs for the current round (regular + zero chips for numPlayersStartofRound)
  local activeChipMap = getActiveChipMap(chipRound, numPlayersStartofRound)
  local currentRoundChipGUIDs = {}
  for guid, _ in pairs(activeChipMap) do
    currentRoundChipGUIDs[guid] = true
  end

  -- Reset the count for this round
  chipsOnPlayers[chipRound] = 0

  -- Count current-round chips inside each seated player's script zone (at most 1 per zone)
  for color, params in pairs(playerParameters) do
    if isActiveParticipant(color) then -- benched seats (#19) are not counted
      if params.topScriptZoneObj then
        local zoneObjects = params.topScriptZoneObj.getObjects()
        for _, obj in ipairs(zoneObjects) do
          if obj.hasTag(TAGS.chips) and currentRoundChipGUIDs[obj.getGUID()] then
            chipsOnPlayers[chipRound] = chipsOnPlayers[chipRound] + 1
            break
          end
        end
      end
      if params.botScriptZoneObj then
        local zoneObjects = params.botScriptZoneObj.getObjects()
        for _, obj in ipairs(zoneObjects) do
          if obj.hasTag(TAGS.chips) and currentRoundChipGUIDs[obj.getGUID()] then
            chipsOnPlayers[chipRound] = chipsOnPlayers[chipRound] + 1
            break
          end
        end
      end
    end
  end

  local threshold = numPlayersStartofRound + (chipRound == 4 and getExitChipCount() or 0)
  local totalPlaced = chipsOnPlayers[chipRound] + countExitChipsOnPlayers() + countExitChipsInSupply()
  if FLAGS.Automode and totalPlaced > 0 and totalPlaced >= threshold then
    startCountdown()
  else
    cancelCountdown()
  end
end

-------------------------------
-- Notepad Ranking System
-------------------------------

-- Get the star value for a chip at a given round and index.
-- Regular chips: star value = index (1-8). Zero chips: star value = 0.
function getChipStarValue(chipRound, index)
  if index > #chipGUIDs[chipRound] then
    return 0 -- zero chip
  end
  return index
end

-- Build a map of all active chip GUIDs -> star values for a round, given the player count.
-- Includes regular chips (1..min(numPlayers, 8)) and zero chips when numPlayers > 8.
function getActiveChipMap(chipRound, numPlayers)
  local map = {}
  local regularCount = math.min(numPlayers, #chipGUIDs[chipRound])
  for i = 1, regularCount do
    if chipGUIDs[chipRound][i] then
      map[chipGUIDs[chipRound][i]] = i -- star value = index
    end
  end
  -- Add zero chips for players 9+
  if numPlayers > #chipGUIDs[chipRound] and zeroChipGUIDs[chipRound] then
    local zeroNeeded = numPlayers - #chipGUIDs[chipRound]
    for z = 1, math.min(zeroNeeded, #zeroChipGUIDs[chipRound]) do
      if zeroChipGUIDs[chipRound][z] then
        map[zeroChipGUIDs[chipRound][z]] = 0 -- star value = 0
      end
    end
  end
  return map
end

-- Build a flat list of all chip GUIDs for a round (regular + zero), regardless of player count.
-- Used for cleanup operations that need to iterate all possible chips.
function getAllChipGUIDsForRound(chipRound)
  local guids = {}
  if chipGUIDs[chipRound] then
    for _, guid in ipairs(chipGUIDs[chipRound]) do
      table.insert(guids, guid)
    end
  end
  if zeroChipGUIDs[chipRound] then
    for _, guid in ipairs(zeroChipGUIDs[chipRound]) do
      table.insert(guids, guid)
    end
  end
  return guids
end

-- Compute the number of active exit chips from exitChipMode and the current player count.
-- Base count: 7 players=1, 8-9=2, 10+=3. Mode reduces by 0/1/2/3, clamped to [0, 3].
function getExitChipCount()
  if exitChipMode >= 3 then return 0 end
  local n = numPlayersStartofRound
  local base = 0
  if n >= 10 then
    base = 3
  elseif n >= 8 then
    base = 2
  elseif n >= 7 then
    base = 1
  end
  return math.max(0, math.min(base - EXIT_CHIP_MODES[exitChipMode].reduction, #exitChipGUIDs))
end

-- Build a set of currently active exit chip GUIDs (based on getExitChipCount).
-- "Active" = the exit chips the current mode auto-places and requires in zones. Used for
-- placement and the automode threshold contribution — NOT for whether a grabbed chip works.
function getActiveExitChipSet()
  local guids = {}
  for i = 1, getExitChipCount() do
    if exitChipGUIDs[i] then guids[exitChipGUIDs[i]] = true end
  end
  return guids
end

-- Build a set of ALL exit chip GUIDs, regardless of exitChipMode / player count. An exit chip
-- always functions when a player physically takes it into their chip space (even at low player
-- counts or a mode that auto-places fewer/zero chips), so recognition of a placed exit chip
-- uses this set. Only the auto-placement count and the required-in-zone threshold use the
-- mode-limited getActiveExitChipSet().
function getAllExitChipSet()
  local guids = {}
  for _, guid in ipairs(exitChipGUIDs) do
    guids[guid] = true
  end
  return guids
end

-- Returns a set of color..hand keys (e.g. "YellowTop", "GreenBot") for every player/hand
-- whose script zone currently contains an active exit chip. Used to exclude those
-- players from the showdown reveal order.
function buildExitChipPlayerSet()
  local result = {}
  -- Include players with a physical exit chip on their zone. Any exit chip works once taken,
  -- so we scan the full exit-chip set — not the mode-limited active set.
  local exitGUIDs = getAllExitChipSet()
  for color, params in pairs(playerParameters) do
    if isPlayerSeated(color) then
      if params.topScriptZoneObj then
        for _, obj in ipairs(params.topScriptZoneObj.getObjects()) do
          if obj.hasTag(TAGS.chips) and exitGUIDs[obj.getGUID()] then
            result[color .. "Top"] = true
            break
          end
        end
      end
      if FLAGS.TwoHand and params.botScriptZoneObj then
        for _, obj in ipairs(params.botScriptZoneObj.getObjects()) do
          if obj.hasTag(TAGS.chips) and exitGUIDs[obj.getGUID()] then
            result[color .. "Bot"] = true
            break
          end
        end
      end
    end
  end
  -- Include players who activated the Backdoor Key tool
  for color, data in pairs(backdoorKeyActivated) do
    if isPlayerSeated(color) then
      result[color .. data.hand] = true
    end
  end
  return result
end

-- Count exit chips placed on player zones that also contain a normal round-4 chip.
-- Returns 0 if not round 4 or getExitChipCount() is 0.
function countExitChipsOnPlayers()
  if getExitChipCount() == 0 then return 0 end
  local chipRound = round - 1
  if chipRound ~= 4 then return 0 end

  local activeChipMap = getActiveChipMap(4, numPlayersStartofRound)
  local activeExitGUIDs = getActiveExitChipSet()

  local count = 0
  for color, params in pairs(playerParameters) do
    if isPlayerSeated(color) then
      for _, zone in ipairs(getPlayerScriptZones(params)) do
        local hasNormalChip = false
        local exitCount = 0
        for _, obj in ipairs(zone.getObjects()) do
          if obj.hasTag(TAGS.chips) then
            if activeChipMap[obj.getGUID()] then
              hasNormalChip = true
            elseif activeExitGUIDs[obj.getGUID()] then
              exitCount = exitCount + 1
            end
          end
        end
        if hasNormalChip then
          count = count + exitCount
        end
      end
    end
  end
  return count
end

-- Count active exit chips resting in the chip supply / reset zone. Leaving (or returning) an
-- exit chip in supply is a resolved "not exiting" decision, so it counts toward the automode
-- threshold just like an exit chip placed on a player — players no longer have to "take" an
-- unneeded exit chip (and hurt their score) just to let automode proceed.
function countExitChipsInSupply()
  if getExitChipCount() == 0 then return 0 end
  if (round - 1) ~= 4 then return 0 end
  local zone = chipScriptZoneGUID and getObjectFromGUID(chipScriptZoneGUID)
  if not zone then return 0 end
  local activeExitGUIDs = getActiveExitChipSet()
  local count = 0
  for _, obj in ipairs(zone.getObjects()) do
    if obj.hasTag(TAGS.chips) and activeExitGUIDs[obj.getGUID()] then
      count = count + 1
    end
  end
  return count
end

-- Build reverse lookup table from chipGUIDs + zeroChipGUIDs: chipGUIDToIndex[guid] = { round, index }
-- For regular chips, index = star value. For zero chips, index = 0.
function buildChipGUIDToIndex()
  chipGUIDToIndex = {}
  for chipRound, chips in pairs(chipGUIDs) do
    for index, guid in pairs(chips) do
      chipGUIDToIndex[guid] = { round = chipRound, index = index }
    end
  end
  for chipRound, chips in pairs(zeroChipGUIDs) do
    for _, guid in pairs(chips) do
      chipGUIDToIndex[guid] = { round = chipRound, index = 0 }
    end
  end
end

-- Positions chips along the community board for a given round.
-- ============================================================
-- Chip "Stamp" context menu
-- Lets a player register a chip's high/low peak without physically placing it —
-- handles the chip "as if" it had been dropped into the player's chip space and
-- returned to the middle. Purely a peak update: it mirrors onObjectEnterScriptingZone
-- but never touches chip placement counts or the Automode threshold.
-- ============================================================

-- Applies a chip's star value to a player's round peak (high + low), exactly as a
-- physical placement would, then refreshes the notepad + chip-space peak labels.
-- hand ("Top"/"Bot") selects the chip space in TwoHand mode; ignored otherwise.
function stampChipPeak(chipObj, playerColor, hand)
  if not chipObj or not playerColor then return end

  -- Peaks are only meaningful while the current round's chips are in play. The active
  -- chip set at any moment is the previous round's (chipRound = round - 1), matching
  -- the gating in onObjectEnterScriptingZone.
  local chipRound = round - 1
  if chipRound < 1 or chipRound > 4 then
    broadcastToColor(LANG(STRINGS.MSG_STAMP_NOT_NOW), playerColor, colorGoldVector)
    return
  end

  local chipValue = getActiveChipMap(chipRound, numPlayersStartofRound)[chipObj.getGUID()]
  if not chipValue then
    broadcastToColor(LANG(STRINGS.MSG_STAMP_NOT_NOW), playerColor, colorGoldVector)
    return
  end

  -- Blacked chips can't be stamped, whether blacked by a Yellow/Orange vault or a chip-flip
  -- challenge (Noise Sensor / Ventilation Shaft). Derived from game state, not rotation. The
  -- menu is normally absent on them, but guard here too in case a stale entry survives.
  if getBlackedChipGUIDs(chipRound, numPlayersStartofRound)[chipObj.getGUID()] then
    broadcastToColor(LANG(STRINGS.MSG_STAMP_NOT_NOW), playerColor, colorGoldVector)
    return
  end

  if not isPlayerSeated(playerColor) then
    broadcastToColor(LANG(STRINGS.MSG_STAMP_NOT_SEATED), playerColor, colorRedVector)
    return
  end

  local steamId = getPlayerSteamId(playerColor)
  local key = FLAGS.TwoHand and (steamId .. hand) or steamId
  peakChipIndex[key] = math.max(peakChipIndex[key] or 0, chipValue)
  lowPeakChipIndex[key] = math.min(lowPeakChipIndex[key] or chipValue, chipValue)

  updateNotepadRankings()
  broadcastToColor(LANG(STRINGS.MSG_STAMP_DONE, chipValue), playerColor, colorWhiteVector)
end

-- Attaches the "Stamp" context menu item(s) to a chip. One entry normally; in TwoHand
-- mode, one per hand (Top/Bottom) since a context-menu click can't indicate which chip
-- space the way a physical drop does. The chip is captured in the closure so we don't
-- depend on the optional object argument of the menu callback.
function addStampContextMenu(chipObj)
  if not chipObj then return end
  chipObj.clearContextMenu()
  if FLAGS.TwoHand then
    chipObj.addContextMenuItem(LANG_NOTAGS(STRINGS.STAMP_MENU_TOP), function(pc)
      stampChipPeak(chipObj, pc, "Top")
    end)
    chipObj.addContextMenuItem(LANG_NOTAGS(STRINGS.STAMP_MENU_BOT), function(pc)
      stampChipPeak(chipObj, pc, "Bot")
    end)
  else
    chipObj.addContextMenuItem(LANG_NOTAGS(STRINGS.STAMP_MENU), function(pc)
      stampChipPeak(chipObj, pc, "Top")
    end)
  end
end

-- Returns a set { [guid] = true } of chips that are blacked (black-side-up) for the given
-- round and player count, derived from active game state — NOT from physical rotation,
-- since chips can be flipped accidentally. Mirrors the flip logic in placeTiles():
--   1) Yellow/Orange vault blacks the whole round (round 2 / round 3 respectively),
--   2) Noise Sensor flips the lowest chip(s) — every zero chip, or the lowest regular chip,
--   3) Ventilation Shaft flips the highest (last) regular chip.
-- Exit chips are excluded from the menu separately (getActiveChipMap never includes them).
function getBlackedChipGUIDs(chipRound, numPlayers)
  local blacked = {}
  if not chipRound or chipRound < 1 or chipRound > 4 then return blacked end

  -- 1) Vault blacks the entire round.
  if isChipRoundFaceDown(chipRound) then
    for _, guid in ipairs(getAllChipGUIDsForRound(chipRound)) do
      blacked[guid] = true
    end
    return blacked
  end

  -- Single-chip flip challenges only apply in rounds 1-3 (matching placeTiles).
  if chipRound >= 4 then return blacked end

  local regularCount = math.min(numPlayers, #chipGUIDs[chipRound])
  local zeroNeeded = 0
  if numPlayers > #chipGUIDs[chipRound] and zeroChipGUIDs[chipRound] then
    zeroNeeded = math.min(numPlayers - #chipGUIDs[chipRound], #zeroChipGUIDs[chipRound])
  end

  -- 2) Noise Sensor: flips every zero chip, or the lowest regular chip when none exist.
  if activeChallenges.NOISE_SENSOR then
    if zeroNeeded > 0 then
      for z = 1, zeroNeeded do
        if zeroChipGUIDs[chipRound][z] then blacked[zeroChipGUIDs[chipRound][z]] = true end
      end
    elseif chipGUIDs[chipRound][1] then
      blacked[chipGUIDs[chipRound][1]] = true
    end
  end

  -- 3) Ventilation Shaft: flips the highest (last) regular chip (placeTiles uses i == numPlayers).
  if activeChallenges.VENTILATION_SHAFT and numPlayers <= regularCount and chipGUIDs[chipRound][numPlayers] then
    blacked[chipGUIDs[chipRound][numPlayers]] = true
  end

  return blacked
end

-- Strips the Stamp menu from every chip, then re-adds it only to the chips that are
-- currently admissible: the active round's chips (regular + zero only — exit chips are
-- excluded by getActiveChipMap) that are NOT blacked per getBlackedChipGUIDs.
-- activeChipRound is passed explicitly because `round` isn't incremented until after the
-- round function (and its placeTiles call) returns; pass nil to clear menus everywhere.
function refreshChipStampMenus(activeChipRound)
  -- Clear stale entries from all chips (every round's regular + zero, plus exit chips).
  for r = 1, 4 do
    for _, guid in ipairs(getAllChipGUIDsForRound(r)) do
      local chip = getObjectFromGUID(guid)
      if chip then chip.clearContextMenu() end
    end
  end
  for _, guid in ipairs(exitChipGUIDs) do
    local chip = getObjectFromGUID(guid)
    if chip then chip.clearContextMenu() end
  end

  if not activeChipRound or activeChipRound < 1 or activeChipRound > 4 then return end
  local blacked = getBlackedChipGUIDs(activeChipRound, numPlayersStartofRound)
  for guid in pairs(getActiveChipMap(activeChipRound, numPlayersStartofRound)) do
    if not blacked[guid] then
      addStampContextMenu(getObjectFromGUID(guid))
    end
  end
end

function placeTiles(numPlayers, roundNumber)
  -- Per-player modes (Banana Split, 7-Card Stud): chips placed to the right of the deck
  -- instead of along a central community board.
  local isPerPlayer = getGameMode().perPlayer

  -- Newly placed chips start locked and are released by releasePendingChipLocks()
  -- once the round's first hand rank calculation has finished (see updatehandRankObjects).
  local placedChipGUIDs = {}

  local maxCommunityTiles = 1
  if not isPerPlayer then
    for round, roundData in pairs(communityTileGUIDs) do
      for column, columnData in pairs(roundData) do
        if #columnData > maxCommunityTiles then
          maxCommunityTiles = #columnData
        end
      end
    end
  end

  -- based on the color of the GANG logo, moving chips down to lowest position (3) always
  maxCommunityTiles = 3

  -- Per-player chip base: to the right of the deck, at deck height. Tracks the deck's live
  -- position (not the static base) so modes that shift the deck — e.g. 7-Card Stud moves it
  -- forward in communityCreateTilesStud() — keep the chips beside the deck instead of clipping
  -- into the per-player tiles. communityCreateTiles() runs before placeTiles(), so by now the
  -- deck is already at its shifted position.
  local deckLivePos = (deckTile and deckTile.getPosition()) or deckTileBasePosition
  local perPlayerChipBase = {
    x = deckLivePos.x - communityOffsetTile.x, -- one tile width to the right of deck
    y = deckTileBasePosition.y,
    z = deckLivePos.z
  }

  -- Determine how many zero-star chips are needed (players 9+)
  local regularCount = math.min(numPlayers, #chipGUIDs[roundNumber])
  local zeroNeeded = 0
  if numPlayers > #chipGUIDs[roundNumber] and zeroChipGUIDs[roundNumber] then
    zeroNeeded = math.min(numPlayers - #chipGUIDs[roundNumber], #zeroChipGUIDs[roundNumber])
  end

  -- Place zero-star chips first (leftmost positions, value 0 is lowest)
  for z = 1, zeroNeeded do
    local chip = getObjectFromGUID(zeroChipGUIDs[roundNumber][z])
    if chip then
      local chipIndex = z
      chip.setLock(true)
      table.insert(placedChipGUIDs, chip.getGUID())
      if isPerPlayer then
        chip.setPosition({
          perPlayerChipBase.x - communityChipOffset.x * (chipIndex - 1),
          perPlayerChipBase.y,
          perPlayerChipBase.z
        })
      else
        chip.setPosition({
          communityChipPosition.x - communityChipOffset.x * (chipIndex - 1),
          communityChipPosition.y,
          communityChipPosition.z + communityChipOffset.z * (maxCommunityTiles - 1)
        })
      end

      if roundNumber < 4 and activeChallenges.NOISE_SENSOR then
        chip.setRotation({ 0, 0, 180 })
      end
    end
  end

  -- Place regular chips (1..8) after zero chips
  for i = 1, regularCount do
    local chip = getObjectFromGUID(chipGUIDs[roundNumber][i])
    if chip then
      local chipIndex = zeroNeeded + i
      chip.setLock(true)
      table.insert(placedChipGUIDs, chip.getGUID())
      if isPerPlayer then
        chip.setPosition({
          perPlayerChipBase.x - communityChipOffset.x * (chipIndex - 1),
          perPlayerChipBase.y,
          perPlayerChipBase.z
        })
      else
        chip.setPosition({
          communityChipPosition.x - communityChipOffset.x * (chipIndex - 1),
          communityChipPosition.y,
          communityChipPosition.z + communityChipOffset.z * (maxCommunityTiles - 1)
        })
      end

      if roundNumber < 4 then
        if activeChallenges.NOISE_SENSOR and zeroNeeded == 0 and i == 1 then
          chip.setRotation({ 0, 0, 180 })
        elseif activeChallenges.VENTILATION_SHAFT and i == numPlayers then
          chip.setRotation({ 0, 0, 180 })
        end
      end
    end
  end

  -- Place exit chips in round 4 (continue after regular + zero chips)
  local exitCount = getExitChipCount()
  if roundNumber == 4 and exitCount > 0 then
    local totalPlaced = regularCount
    if numPlayers > #chipGUIDs[roundNumber] and zeroChipGUIDs[roundNumber] then
      totalPlaced = totalPlaced + math.min(numPlayers - #chipGUIDs[roundNumber], #zeroChipGUIDs[roundNumber])
    end
    for e = 1, math.min(exitCount, #exitChipGUIDs) do
      local chip = getObjectFromGUID(exitChipGUIDs[e])
      if chip then
        local chipIndex = totalPlaced + e
        chip.setLock(true)
        table.insert(placedChipGUIDs, chip.getGUID())
        if isPerPlayer then
          chip.setPosition({
            perPlayerChipBase.x - communityChipOffset.x * (chipIndex - 1),
            perPlayerChipBase.y,
            perPlayerChipBase.z
          })
        else
          chip.setPosition({
            communityChipPosition.x - communityChipOffset.x * (chipIndex - 1),
            communityChipPosition.y,
            communityChipPosition.z + communityChipOffset.z * (maxCommunityTiles - 1)
          })
        end
      end
    end
  end

  -- Keep these chips locked until the round's first hand rank calc finishes, so players
  -- can't place chips while the displayed hand ranks are still stale from the previous round.
  pendingChipUnlockGUIDs = placedChipGUIDs
  pendingChipUnlockRound = roundNumber -- capture now; `round` may advance before the async release
  chipsAwaitingHandRank = #placedChipGUIDs > 0
end

-- Unlocks chips placed by placeTiles once the round's first hand rank calculation has finished.
-- Called from updatehandRankObjects after labels are applied. No-op when nothing is pending.
function releasePendingChipLocks()
  if not chipsAwaitingHandRank then return end
  chipsAwaitingHandRank = false
  for _, chipGUID in ipairs(pendingChipUnlockGUIDs) do
    local chip = getObjectFromGUID(chipGUID)
    if chip then chip.setLock(false) end
  end
  pendingChipUnlockGUIDs = {}

  -- Offer the Stamp context menu now that this round's chips are unlocked (interactive) and
  -- their face-up/down orientation is settled. pendingChipUnlockRound is the admissible round.
  refreshChipStampMenus(pendingChipUnlockRound)

  showReminderAlarmFlash(pendingChipUnlockRound) -- big flash + sound for Quantum Chaos / Foot in the Door (per-challenge round config)
end

-- Finds chips not in any player zone and resets them to their default positions.
function cleanUpChips()
  -- Collect all player script zone GUIDs for fast lookup
  local noResetZones = {}
  for _, params in pairs(playerParameters) do
    for _, zone in ipairs(getPlayerScriptZones(params)) do
      noResetZones[zone.getGUID()] = true
    end
  end
  if chipScriptZoneGUID then noResetZones[chipScriptZoneGUID] = true end

  -- Loop through all chipGUIDs (regular + zero) and find chips not in any player zone
  local chipsToClean = {}
  for chipRound = 1, 4 do
    local allGuids = getAllChipGUIDsForRound(chipRound)
    for _, chipGUID in ipairs(allGuids) do
      local chipObj = getObjectFromGUID(chipGUID)
      if chipObj then
        local inSafeZone = false
        local zones = chipObj.getZones()
        for _, zone in ipairs(zones) do
          if noResetZones[zone.guid] then
            inSafeZone = true
            break
          end
        end
        if not inSafeZone then
          chipsToClean[chipRound] = chipsToClean[chipRound] or {}
          table.insert(chipsToClean[chipRound], chipGUID)
        end
      end
    end
  end

  -- Also check exit chips (round 4 only)
  for _, chipGUID in ipairs(exitChipGUIDs) do
    local chipObj = getObjectFromGUID(chipGUID)
    if chipObj then
      local inSafeZone = false
      local zones = chipObj.getZones()
      for _, zone in ipairs(zones) do
        if noResetZones[zone.guid] then
          inSafeZone = true
          break
        end
      end
      if not inSafeZone then
        chipsToClean[4] = chipsToClean[4] or {}
        table.insert(chipsToClean[4], chipGUID)
      end
    end
  end

  for chipRound, chipData in pairs(chipsToClean) do
    resetChipPosition(chipRound, chipData)
  end
end

-- Flips chips face-down if a special vault (Yellow/Orange) was activated.
function flipChips()
  -- Record which rounds end up black-side-up so isChipRoundFaceDown() has a persistent
  -- source of truth for the rest of the game — lastSpecialVault is cleared right after this
  -- call (in round1()) and mutated by round flow, so it can't be trusted later.
  vaultBlackedRounds = {}

  -- Yellow blacks round-2 chips, Orange blacks round-3 chips. Both the current
  -- (lastSpecialVault) and previous (lastSpecialVault2) special vault count.
  local function markVault(vault)
    if vault == "Yellow" then
      vaultBlackedRounds[2] = true
    elseif vault == "Orange" then
      vaultBlackedRounds[3] = true
    end
  end
  markVault(lastSpecialVault)
  markVault(lastSpecialVault2)

  -- Normalize every round's orientation up front: black side up when that round's vault is
  -- active this heist, white side up otherwise. Whitening the inactive rounds clears stale
  -- black rotations left over from a previous heist — cleanUp() rotates chips using the old
  -- vaultBlackedRounds before this runs, and placeTiles() only ever rotates chips *to* black,
  -- so without this a round would stay black across heists even after its vault is gone.
  for chipRound = 1, 4 do
    rotateChips(chipRound, vaultBlackedRounds[chipRound] == true)
  end
end

-- Rotates all chips in a round to face-down (black, 180°) when faceDown is true,
-- or face-up (white, 0°) otherwise. Preserves each chip's x/y rotation.
function rotateChips(chipRound, faceDown)
  if not chipGUIDs[chipRound] then return end

  local zRotation = faceDown and 180 or 0
  local allGuids = getAllChipGUIDsForRound(chipRound)
  for _, chipGUID in ipairs(allGuids) do
    local chipObj = getObjectFromGUID(chipGUID)
    if chipObj then
      local currentRotation = chipObj.getRotation()
      chipObj.setRotation({ currentRotation.x, currentRotation.y, zRotation })
    end
  end
end

-- Whether a round's chips should rest face-down (black side up) given the active special
-- vaults: Yellow flips round-2 chips, Orange flips round-3 chips. Both the current
-- (lastSpecialVault) and previous (lastSpecialVault2) vault count.
function isChipRoundFaceDown(chipRound)
  -- Read the record captured by flipChips() (game start) rather than lastSpecialVault, which is
  -- consumed in round1() and reshuffled by round flow — so it stays correct all game.
  return vaultBlackedRounds[chipRound] == true
end

-- Moves chips back to their default storage positions.
-- startIndex lets a second batch (e.g. exit chips) stack ON TOP of chips already reset into
-- the same column instead of restarting at index 1 — otherwise both batches land at the same
-- heights, collide, and pop the chips into the air. Returns the next free stack index.
function resetChipPosition(chipRound, chipData, startIndex)
  chipData = chipData or chipGUIDs[chipRound]
  if not chipData then return startIndex or 1 end

  -- Restore the vault-driven orientation: a reset round-2/3 chip stays black-side-up if its
  -- Yellow/Orange vault is active, instead of always flipping back to white-side-up.
  local faceDownZ = isChipRoundFaceDown(chipRound) and 180 or 0
  local index = startIndex or 1
  for _, chipGUID in ipairs(chipData) do
    local chipObj = getObjectFromGUID(chipGUID)
    if chipObj then
      chipObj.setLock(false)
      chipObj.setPositionSmooth({
        x = chipPosition.x + (chipPositionOffset.x * chipRound),
        y = chipPosition.y + 2 + (index * chipPositionOffset.y),
        z = chipPosition.z + (chipPositionOffset.z * chipRound)
      })
      chipObj.setRotation({ 0, 0, faceDownZ })
      index = index + 1
    end
  end
  return index
end

-- Exit chip mode is selected via the Admin Board (exitChipMode slider); the old cycle button
-- (onExitChipModeClick) was retired with it. getExitChipModeInfoLabels is kept for reuse.

-- Build the 3 info label strings for a given exit chip mode.
function getExitChipModeInfoLabels(mode)
  local reduction = EXIT_CHIP_MODES[mode].reduction
  local function count(base)
    return math.max(0, math.min(base - reduction, #exitChipGUIDs))
  end
  local function chipStr(n)
    if n == 0 then return STRINGS.LBL_EXIT_NONE end
    return n == 1 and LANG_TABLE(STRINGS.LBL_EXIT_CHIP, n) or LANG_TABLE(STRINGS.LBL_EXIT_CHIPS, n)
  end
  return {
    LANG(STRINGS.LBL_PLAYERS, "7", chipStr(count(1))),
    LANG(STRINGS.LBL_PLAYERS, "8-9", chipStr(count(2))),
    LANG(STRINGS.LBL_PLAYERS, "10", chipStr(count(3))),
  }
end

------------------------------------
--- SECTION 8: Notepad Ranking System
------------------------------------

-- Scan player zones to find which chip (by star value) each player/hand has for the given chip round.
-- Returns a sorted list of { color, steam_id, chipIndex, hand } entries (descending by chipIndex = best first).
function scanPlayerChipRankings(chipRound)
  if chipRound < 1 or chipRound > 4 then return {} end

  -- Build set of valid chip GUIDs for this round, mapping guid -> star value
  local validChipGUIDs = getActiveChipMap(chipRound, numPlayersStartofRound)

  local rankings = {}

  -- Build set of exit chip GUIDs for round 4. Any exit chip works once taken, so recognition
  -- uses the full exit-chip set, not the mode-limited active set.
  local activeExitGUIDs = {}
  if chipRound == 4 then activeExitGUIDs = getAllExitChipSet() end

  for color, params in pairs(playerParameters) do
    if isActiveParticipant(color) then -- benched seats (#19) never enter the chip ranking
      local steamId = getPlayerSteamId(color)
      -- Check Top zone
      if params.topScriptZoneObj then
        local topChipIndex = nil
        local topHasExitChip = false
        for _, obj in ipairs(params.topScriptZoneObj.getObjects()) do
          if obj.hasTag(TAGS.chips) then
            if validChipGUIDs[obj.getGUID()] then
              topChipIndex = validChipGUIDs[obj.getGUID()]
            elseif activeExitGUIDs[obj.getGUID()] then
              topHasExitChip = true
            end
          end
        end
        if topChipIndex then
          table.insert(rankings, {
            color = color,
            steam_id = steamId,
            steam_name = getPlayerDisplayName(color),
            chipIndex = topChipIndex,
            hand = "Top",
            hasExitChip = topHasExitChip
          })
        end
      end
      -- Check Bot zone (only relevant in TwoHand mode)
      if params.botScriptZoneObj then
        local botChipIndex = nil
        local botHasExitChip = false
        for _, obj in ipairs(params.botScriptZoneObj.getObjects()) do
          if obj.hasTag(TAGS.chips) then
            if validChipGUIDs[obj.getGUID()] then
              botChipIndex = validChipGUIDs[obj.getGUID()]
            elseif activeExitGUIDs[obj.getGUID()] then
              botHasExitChip = true
            end
          end
        end
        if botChipIndex then
          table.insert(rankings, {
            color = color,
            steam_id = steamId,
            steam_name = getPlayerDisplayName(color),
            chipIndex = botChipIndex,
            hand = "Bot",
            hasExitChip = botHasExitChip
          })
        end
      end
    end
  end

  -- Sort descending by chipIndex (highest star = best rank)
  table.sort(rankings, function(a, b)
    return a.chipIndex > b.chipIndex
  end)

  return rankings
end

-- Round-4 chip rankings with EXITED hands removed (exit chip or backdoor key), still sorted
-- best-first. [1] = the effective "leader" the Scan Challenges target; [2] = runner-up.
-- An exited top player bailed, so the leader/reminder/vote shifts to the next non-exit hand.
function scanNonExitChipRankings()
  local rankings = scanPlayerChipRankings(4)
  local exitSet = buildExitChipPlayerSet()
  local out = {}
  for _, e in ipairs(rankings) do
    if not exitSet[e.color .. e.hand] and not e.hasExitChip then
      table.insert(out, e)
    end
  end
  return out
end

-- Build revealTurnOrder for the showdown: ascending by round-4 chip value (lowest reveals first),
-- ties broken by seat order. Players with no chip sort first (treated as -1).
function buildRevealTurnOrder()
  -- Each entry in revealTurnOrder is { color, hand }; in TwoHand mode Top and Bot are separate
  -- entries sorted by their individual chip values.
  local chipRankings = scanPlayerChipRankings(4)
  local chipValueByHand = {}
  for _, entry in ipairs(chipRankings) do
    chipValueByHand[entry.color .. entry.hand] = entry.chipIndex
  end
  local seatPos = {}
  for i, c in ipairs(SEAT_ORDER) do seatPos[c] = i end
  local candidates = {}
  for _, c in ipairs(SEAT_ORDER) do
    if isActiveParticipant(c) then -- benched seats (#19) are not in the reveal order
      local hasCards = dealtCards[c] and dealtCards[c]["Top"] and #dealtCards[c]["Top"] > 0
      if hasCards then
        if FLAGS.TwoHand then
          table.insert(candidates,
            { color = c, hand = "Top", chip = chipValueByHand[c .. "Top"] or -1, seat = seatPos[c] or 99 })
          table.insert(candidates,
            { color = c, hand = "Bot", chip = chipValueByHand[c .. "Bot"] or -1, seat = seatPos[c] or 99 })
        else
          table.insert(candidates,
            { color = c, hand = "Top", chip = chipValueByHand[c .. "Top"] or -1, seat = seatPos[c] or 99 })
        end
      end
    end
  end
  table.sort(candidates, function(a, b)
    if a.chip ~= b.chip then return a.chip < b.chip end
    return a.seat < b.seat
  end)
  revealTurnOrder = {}
  revealCurrentTurn = 1
  for _, entry in ipairs(candidates) do
    table.insert(revealTurnOrder, { color = entry.color, hand = entry.hand, chip = entry.chip })
  end
end

-- Save current chip rankings as history for the given chip round (for comparison with next round).
function snapshotRoundRankings(chipRound)
  if chipRound < 1 or chipRound > 4 then return end
  -- BLACKOUT challenge: suppress history so previous rounds cannot be reconstructed from the notepad
  if activeChallenges.BLACKOUT then return end
  local rankings = scanPlayerChipRankings(chipRound)
  if #rankings > 0 then
    rankingHistory[chipRound] = rankings
  end
end

-- Saves each chip owner's hand rank for that round. Must be called BEFORE roundSetup or any
-- new community cards are drawn, so the cache still reflects the ending round's state.
function snapshotChipHandRanks(chipRound)
  local validChipGUIDs = getActiveChipMap(chipRound, numPlayersStartofRound)

  local function scanZone(zoneObj, color, hand)
    if not zoneObj then return end
    local cached = handRankCache[color]
    if not cached then return end
    for _, obj in ipairs(zoneObj.getObjects()) do
      if obj.hasTag(TAGS.chips) then
        local guid = obj.getGUID()
        -- Never override: only write if this chip has not been snapshotted yet.
        if validChipGUIDs[guid] and chipHandRankSnapshot[guid] == nil then
          local handStr = FLAGS.TwoHand and
              ((hand == "Top") and cached.top or cached.bot) or cached.top
          if handStr and handStr ~= "" then
            chipZoneOwner[guid] = { color = color, hand = hand }
            chipHandRankSnapshot[guid] = handStr
            local chipNum = computeMagic8BallChipNumber(color, hand:lower())
            chipPositionSnapshot[guid] = chipNum
          end
        end
      end
    end
  end

  for color, params in pairs(playerParameters) do
    if isPlayerSeated(color) then
      scanZone(params.topScriptZoneObj, color, "Top")
      scanZone(params.botScriptZoneObj, color, "Bot")
    end
  end
end

------------------------------------------------------------------------
-- Accuracy ("The Gang Sense") producer
--
-- Scores each chip round with the rank-position-within-pool metric, stores
-- raw per-round tuples, and at showdown pushes one finished game record to
-- every Stats Book on the table (GMNotes == "StatsBook"). The book owns
-- storage / merge / display (statsbook.lua). See FEATURE_IDEAS.md.
------------------------------------------------------------------------

-- Player key: steamId in single-hand mode; steamId + hand in TwoHand so the
-- two hands are tracked (and later scored) independently.
-- Start a new accuracy-tracked game: mint the gameId, reset per-round state.
-- Called at the start of round1().
function beginAccuracyGame()
  accuracyRounds = {}
  accuracyPlayers = {}
  local hostId = "host"
  for _, p in ipairs(Player.getPlayers()) do
    if p.host then
      hostId = p.steam_id or "host"
      break
    end
  end
  accuracyGameId = tostring(os.time()) .. "-" .. hostId .. "-" .. tostring(math.random(100000, 999999))
  refreshStatsBookFaces() -- new game starting → safe to show the previous game's now-final result
end

-- Score one completed chip round into the in-progress game.
-- Call right after snapshotChipHandRanks(chipRound), while handRankCodeCache
-- and the chip zones still reflect that round's locked-in state.
function scoreAccuracyRound(chipRound)
  if not accuracyGameId then return end
  if chipRound < 1 or chipRound > 4 then return end

  local exited = buildExitChipPlayerSet() -- color..hand -> true (only meaningful in round 4)
  local rankings = scanPlayerChipRankings(chipRound)

  accuracyRounds[chipRound] = accuracyRounds[chipRound] or {}
  local store = accuracyRounds[chipRound]

  -- Each hand is scored individually within the pool, then a player's hands are
  -- AVERAGED into one steamId entry — so TwoHand players get a single score / one
  -- leaderboard row, identical in shape to a single-hand game.
  local pool = {}      -- competing hands: { steamId, rank, score, chip }
  local exitHands = {} -- voluntarily exited hands: { steamId, chip }
  for _, e in ipairs(rankings) do
    accuracyPlayers[e.steam_id] = { steamId = e.steam_id, name = e.steam_name }

    -- True hand strength = rank category first (handRankPriority), score only as
    -- tiebreaker within a category — the same comparison the game uses (isRankBetter).
    local cache = handRankCodeCache[e.color]
    local rank, score
    if cache then
      if e.hand == "Bot" then
        rank, score = cache.bot, cache.botScore
      else
        rank, score = cache.top, cache.topScore
      end
    end

    if exited[e.color .. e.hand] then
      table.insert(exitHands, { steamId = e.steam_id, chip = e.chipIndex })
    elseif activeChallenges.BALANCE and chipRound < 4 and (rank == "HC" or rank == "B0") then
      -- Balance meta (rounds 1-3 only): the convention is to NOT reposition for a
      -- high-card-only improvement (balancing a 2 into an Ace is still just high card).
      -- Such hands park at a low chip on purpose, so we exclude them from the pool —
      -- not penalized for parking, and they don't blame anyone via inversions.
      -- ROUND 4 (red) always scores everyone: the meta says fix your position on the
      -- final round even if you never hit, so high-card hands are graded there.
    elseif rank ~= nil then
      table.insert(pool, { steamId = e.steam_id, rank = rank, score = score or 0, chip = e.chipIndex })
    end
  end

  local n = #pool
  local handOutcomes = {} -- { steamId, score, chip } per scored hand

  if n >= 2 then
    -- Two hands are equal strength only if BOTH rank priority and score match.
    local function strengthPrio(h) return handRankPriority[h.rank] or 0 end
    local function sameStrength(a, b)
      return strengthPrio(a) == strengthPrio(b) and a.score == b.score
    end

    -- strengthRank with tie-blocks: sort by (priority desc, score desc), group equal
    -- strengths into a contiguous position range [strLo, strHi] (any chip in range is correct).
    table.sort(pool, function(a, b)
      local pa, pb = strengthPrio(a), strengthPrio(b)
      if pa ~= pb then return pa > pb end
      return a.score > b.score
    end)
    local i = 1
    while i <= n do
      local j = i
      while j < n and sameStrength(pool[j + 1], pool[i]) do j = j + 1 end
      for k = i, j do
        pool[k].strLo = i
        pool[k].strHi = j
      end
      i = j + 1
    end

    -- chipRank: ordinal position by chip value, descending.
    local byChip = {}
    for _, h in ipairs(pool) do table.insert(byChip, h) end
    table.sort(byChip, function(a, b) return a.chip > b.chip end)
    for pos, h in ipairs(byChip) do h.chipRank = pos end

    -- Displacement = distance from chipRank to the nearest end of the strength
    -- tie-block (how far out of place this hand is).
    for _, h in ipairs(pool) do
      local d = 0
      if h.chipRank < h.strLo then
        d = h.strLo - h.chipRank
      elseif h.chipRank > h.strHi then
        d = h.chipRank - h.strHi
      end
      h.disp = d
      h.blame = 0
    end

    -- Blame attribution: for each out-of-order pair (the stronger hand holds the
    -- LOWER chip), pin the blame on whoever is more displaced. So one player's bad
    -- misplacement lands on THAT player, not on the correctly-placed people their
    -- chip shifted. Equal displacement (e.g. a straight two-player swap) splits it.
    for a = 1, n do
      for b = a + 1, n do
        local ha, hb = pool[a], pool[b]
        local pa, pb = strengthPrio(ha), strengthPrio(hb)
        local stronger, weaker
        if pa ~= pb then
          if pa > pb then stronger, weaker = ha, hb else stronger, weaker = hb, ha end
        elseif ha.score ~= hb.score then
          if ha.score > hb.score then stronger, weaker = ha, hb else stronger, weaker = hb, ha end
        end
        -- inverted only if a strict strength order exists AND the stronger hand
        -- holds the lower chip (its chipRank number is higher).
        if stronger and stronger.chipRank > weaker.chipRank then
          if ha.disp > hb.disp then
            ha.blame = ha.blame + 1
          elseif hb.disp > ha.disp then
            hb.blame = hb.blame + 1
          else
            ha.blame = ha.blame + 0.5
            hb.blame = hb.blame + 0.5
          end
        end
      end
    end

    -- roundScore = 100 × (1 − blame / (n−1)). srank (=strLo) is stored as the raw
    -- strength rank so games stay recomputable under any future model.
    for _, h in ipairs(pool) do
      h.handScore = 100 * (1 - h.blame / (n - 1))
      table.insert(handOutcomes, { steamId = h.steamId, score = h.handScore, chip = h.chip, srank = h.strLo })
    end

    -- Voluntary exit: instead of a flat 0 (which tanked the score), give the table's
    -- average accuracy this round, capped at EXIT_MAX_SCORE — roughly neutral, but
    -- you can't lock in a top score by bailing on the read.
    if #exitHands > 0 then
      local sum = 0
      for _, h in ipairs(pool) do sum = sum + h.handScore end
      local exitScore = math.min(sum / n, EXIT_MAX_SCORE)
      for _, x in ipairs(exitHands) do
        table.insert(handOutcomes, { steamId = x.steamId, score = exitScore, chip = x.chip })
      end
    end
  end
  -- n < 2: no positions to compare → no hands scored this round (weight redistributes).

  -- Collapse per-hand outcomes to one entry per steamId (average a player's hands).
  local agg = {}
  for _, o in ipairs(handOutcomes) do
    local a = agg[o.steamId]
    if not a then
      a = { sum = 0, count = 0, chip = o.chip, srank = o.srank }
      agg[o.steamId] = a
    else
      a.srank = nil -- >1 hand (TwoHand / exit) → no single strength rank to store
    end
    a.sum = a.sum + o.score
    a.count = a.count + 1
  end
  for steamId, a in pairs(agg) do
    store[steamId] = { score = a.sum / a.count, chip = a.chip, n = n, srank = a.srank }
  end
end

-- Push a finished game record to every Stats Book on the table. Books are
-- discovered by GMNotes ("StatsBook") because saved career books spawn with
-- fresh GUIDs. No-op (returns 0) if no book is present.
-- The record is sent as a JSON string: a live table passed across the script
-- boundary stays owned by this script and the book cannot store it (TTS throws
-- "operations with resources owned by different scripts"). The book decodes it.
function pushGameRecordToBooks(record)
  local payload = JSON.encode(record)
  local count = 0
  for _, obj in ipairs(getAllObjects()) do
    if obj.getGMNotes() == "StatsBook" then
      obj.call("recordGame", payload)
      count = count + 1
    end
  end
  return count
end

-- Refresh the at-a-glance leaderboard on every Stats Book. Called only when it's
-- safe to reveal results — game cleanup and new-game start — NOT at the showdown
-- push, so the book face doesn't spoil the showdown before hands are revealed.
function refreshStatsBookFaces()
  for _, obj in ipairs(getAllObjects()) do
    if obj.getGMNotes() == "StatsBook" then
      obj.call("updateBookFace")
    end
  end
end

-- steamIds of players currently seated (incl. test players). The book face uses
-- this to show only people at the table. Returned as JSON (cross-script safe).
function getSeatedSteamIdsJson()
  local ids = {}
  for color, _ in pairs(playerParameters) do
    if isPlayerSeated(color) then
      table.insert(ids, getPlayerSteamId(color))
    end
  end
  return JSON.encode(ids)
end

------------------------------------------------------------------------
-- The Gang Sense overlay (screen-space). Scaffold (2a): open/close + tabs.
-- Data tabs (leaderboard / drill-down / bars / sparklines) come next.
-- Opened from a Stats Book (book button → Global.call("toggleStatsOverlay")).
------------------------------------------------------------------------

-- Per-player overlay state (init on first access).
function statsState(color)
  local s = statsOverlay[color]
  if not s then
    s = {
      open = false,
      view = "board",
      scope = "career",
      round = 4,
      search = "",
      playerKey = nil,
      gameId = nil,
      bookGUID = nil,
      connectedOnly = false
    }
    statsOverlay[color] = s
  end
  return s
end

-- Resolve the Stats Book a player's overlay reads from: the one they opened it
-- on, else the first StatsBook found.
function getStatsOverlayBook(color)
  local guid = statsState(color).bookGUID
  if guid then
    local o = getObjectFromGUID(guid)
    if o and o.getGMNotes() == "StatsBook" then return o end
  end
  for _, obj in ipairs(getAllObjects()) do
    if obj.getGMNotes() == "StatsBook" then return obj end
  end
  return nil
end

-- Call a book JSON query and decode it into a locally-owned table (or nil).
local function statsBookQuery(color, fn, arg)
  local book = getStatsOverlayBook(color)
  if not book then return nil end
  local json = book.call(fn, arg)
  if type(json) ~= "string" or json == "" then return nil end
  local ok, t = pcall(function() return JSON.decode(json) end)
  if ok then return t end
  return nil
end

-- Green→red hex for an accuracy %; used for the bars.
local function accuracyColorHex(pct)
  local t = math.max(0, math.min(1, (pct or 0) / 100))
  local r = math.min(255, math.floor((1 - t) * 215 + 40))
  local g = math.min(255, math.floor(t * 200 + 45))
  return string.format("#%02X%02X44", r, g)
end

-- Display-only rescale for the leaderboard: real ratings cluster near 100, so stretch
-- [FLOOR, 100] → [0, 100] for the shown % and bar fill. This changes nothing in the data
-- or the rank order — it just spreads the cluster so differences are visible. Tier badges
-- stay computed on the real rating.
local STATS_DISPLAY_FLOOR = 0
local function statsDisplayPct(real)
  real = real or 0
  if real <= STATS_DISPLAY_FLOOR then return 0 end
  if real >= 100 then return 100 end
  return (real - STATS_DISPLAY_FLOOR) / (100 - STATS_DISPLAY_FLOOR) * 100
end

-- Career-ranked leaderboard, tagged with original rank, then filtered by the
-- search text. Used by both the board renderer and the row-click handler so the
-- displayed list and the click indices always match.
local function getStatsLeaderboardRows(color)
  local s = statsState(color)
  local rows = statsBookQuery(color, "queryLeaderboardJson", s.scope) or {}
  -- Assign global ranks first, so a player keeps their true leaderboard position even when
  -- the list is filtered down to connected players.
  for i, r in ipairs(rows) do r.rank = i end
  if s.connectedOnly then
    local connected = {}
    for _, pl in ipairs(Player.getPlayers()) do
      if pl.steam_id then connected[tostring(pl.steam_id)] = true end
    end
    local kept = {}
    for _, r in ipairs(rows) do
      if r.key and connected[tostring(r.key)] then table.insert(kept, r) end
    end
    rows = kept
  end
  local q = s.search or ""
  if q == "" then return rows end
  q = string.lower(q)
  local filtered = {}
  for _, r in ipairs(rows) do
    if r.name and string.find(string.lower(r.name), q, 1, true) then
      table.insert(filtered, r)
    end
  end
  return filtered
end

-- BOARD tab: leaderboard rows with accuracy bars + tier badges.
local function buildStatsBoardContent(color)
  local s = statsState(color)
  local rows = getStatsLeaderboardRows(color)
  if #rows == 0 then
    local msg = "(no games yet)"
    if s.search ~= "" then
      msg = 'no players match "' .. s.search .. '"'
    elseif s.connectedOnly then
      msg = "no connected players have games yet"
    end
    return '<Text fontSize="18" color="#888888" alignment="MiddleCenter">' .. msg .. '</Text>'
  end
  local c = {}
  -- Explicit content height drives the scroll range: each row is 34 + 4 spacing, plus the
  -- 6+6 vertical padding and a bottom buffer so the last row fully clears the viewport.
  -- preferredHeight (not just minHeight) is required — the scroll view sizes its scrollable
  -- content by the child's PREFERRED height; minHeight alone gets clamped to the viewport,
  -- which capped the list (e.g. at ~13 rows) regardless of how many players there are.
  local contentH = #rows * 38 + 24
  table.insert(c,
    '<VerticalLayout spacing="0"><VerticalScrollView flexibleHeight="1" scrollSensitivity="30" color="#141414F0">')
  table.insert(c, '<VerticalLayout spacing="4" padding="6 6 6 6" childForceExpandHeight="false"'
    .. ' preferredHeight="' .. contentH .. '" minHeight="' .. contentH .. '" flexibleHeight="0">')
  do
    for i, r in ipairs(rows) do
      local pct = statsDisplayPct(r.rating) -- rescaled for display; rank order unchanged
      table.insert(c, '<HorizontalLayout preferredHeight="34" minHeight="34" spacing="8">')
      table.insert(c,
        '<Text preferredWidth="34" fontSize="17" color="#CCCCCC" alignment="MiddleRight">' .. r.rank .. '</Text>')
      table.insert(c, '<Button id="statsRow_' .. i .. '_' .. color .. '" onClick="onStatsRowClick"'
        .. ' colors="#00000000|#FFFFFF22|#FFFFFF11|#00000000" preferredWidth="150" preferredHeight="30">'
        .. '<Text fontSize="17" color="#FFFFFF" alignment="MiddleLeft">' .. (r.name or "?") .. '</Text></Button>')
      table.insert(c, '<ProgressBar percentage="' .. string.format("%.0f", pct) .. '" fillImageColor="'
        .. accuracyColorHex(pct) .. '" color="#2A2A2A" flexibleWidth="1" preferredHeight="18" />')
      table.insert(c, '<Text preferredWidth="55" fontSize="17" color="#FFFFFF" alignment="MiddleRight">'
        .. string.format("%.0f%%", pct) .. '</Text>')
      table.insert(c, '<Text preferredWidth="52" fontSize="14" color="#999999" alignment="MiddleCenter">'
        .. (r.gameCount or 0) .. 'g</Text>')
      -- Provisional players (below the games threshold) are sorted to the bottom and labelled
      -- so a low position next to a high % is self-explanatory.
      local tierText, tierCol
      if r.ranked == false then
        tierText = string.format("Prov. %d/%d", r.gameCount or 0, r.minRankedGames or 10)
        tierCol = "#888888"
      else
        tierText, tierCol = (r.tier or ""), "#D9AD33"
      end
      table.insert(c, '<Text preferredWidth="120" fontSize="15" color="' .. tierCol .. '" alignment="MiddleLeft">'
        .. tierText .. '</Text>')
      table.insert(c, '</HorizontalLayout>')
    end
  end
  table.insert(c, '</VerticalLayout></VerticalScrollView></VerticalLayout>')
  return table.concat(c, "\n")
end

-- perRound may survive the JSON round-trip with string keys; accept either.
local function statsPerRound(t, r)
  if not t then return nil end
  return t[r] or t[tostring(r)]
end

-- PLAYER tab: one player's career detail + this-session comparison.
local function buildStatsPlayerContent(color)
  local key = statsState(color).playerKey
  if not key then
    return
    '<Text fontSize="18" color="#888888" alignment="MiddleCenter">Click a player on the BOARD, or search by name.</Text>'
  end
  local d = statsBookQuery(color, "queryPlayerDetailJson", key)
  if not d or not d.career or (d.career.gameCount or 0) == 0 then
    return '<Text fontSize="18" color="#888888" alignment="MiddleCenter">No games for this player.</Text>'
  end
  local car, ses = d.career, d.session or {}
  local hist = car.history or {}
  local contentH = 350 + 34 * math.min(5, #hist) -- explicit height so the detail scrolls
  local c = {}
  table.insert(c,
    '<VerticalLayout spacing="0"><VerticalScrollView flexibleHeight="1" scrollSensitivity="30" color="#141414F0">')
  table.insert(c,
    '<VerticalLayout spacing="8" padding="4 4 4 4" childForceExpandHeight="false" flexibleHeight="0" minHeight="'
    .. contentH .. '">')

  -- Header: name + career rating + tier
  table.insert(c, '<HorizontalLayout preferredHeight="36" spacing="10">')
  table.insert(c,
    '<Text fontSize="24" color="#FFFFFF" alignment="MiddleLeft" flexibleWidth="1">' .. (car.name or "?") .. '</Text>')
  table.insert(c,
    '<Text fontSize="24" color="' .. accuracyColorHex(car.rating) .. '" alignment="MiddleRight" preferredWidth="90">'
    .. string.format("%.0f%%", car.rating or 0) .. '</Text>')
  table.insert(c,
    '<Text fontSize="16" color="#D9AD33" alignment="MiddleRight" preferredWidth="130">' .. (car.tier or "") .. '</Text>')
  table.insert(c, '</HorizontalLayout>')

  -- Career stats + this-session comparison
  local sessText, sessColor
  if (ses.gameCount or 0) > 0 then
    local delta = (ses.rating or 0) - (car.rating or 0)
    local mark = (delta >= 0.5) and ("▲" .. string.format("%.0f", delta))
        or (delta <= -0.5) and ("▼" .. string.format("%.0f", -delta)) or "="
    sessColor = (delta >= 0.5) and "#44CC66" or (delta <= -0.5) and "#CC4444" or "#AAAAAA"
    sessText = "This session " .. string.format("%.0f%%", ses.rating or 0) .. "  " .. mark
  else
    sessColor, sessText = "#777777", "This session —"
  end
  table.insert(c, '<HorizontalLayout preferredHeight="22" spacing="8">')
  table.insert(c, '<Text fontSize="14" color="#999999" alignment="MiddleLeft" flexibleWidth="1">'
    .. string.format("%d games  •  best %.0f%%  •  worst %.0f%%", car.gameCount or 0, car.best or 0, car.worst or 0)
    .. '</Text>')
  table.insert(c,
    '<Text fontSize="15" color="' ..
    sessColor .. '" alignment="MiddleRight" preferredWidth="200">' .. sessText .. '</Text>')
  table.insert(c, '</HorizontalLayout>')

  -- By-round bars (career averages)
  table.insert(c, '<Text fontSize="15" color="#CCCCCC" alignment="MiddleLeft">By round (career avg)</Text>')
  for r = 1, 4 do
    local v = statsPerRound(car.perRound, r)
    table.insert(c, '<HorizontalLayout preferredHeight="20" spacing="6">')
    table.insert(c, '<Text preferredWidth="32" fontSize="14" color="#CCCCCC" alignment="MiddleLeft">R' .. r .. '</Text>')
    if v then
      table.insert(c, '<ProgressBar percentage="' .. string.format("%.0f", v) .. '" fillImageColor="'
        .. accuracyColorHex(v) .. '" color="#2A2A2A" flexibleWidth="1" preferredHeight="13" />')
      table.insert(c,
        '<Text preferredWidth="46" fontSize="14" color="#FFFFFF" alignment="MiddleRight">' ..
        string.format("%.0f%%", v) .. '</Text>')
    else
      table.insert(c,
        '<Text flexibleWidth="1" fontSize="13" color="#666666" alignment="MiddleLeft">— not played —</Text>')
      table.insert(c, '<Text preferredWidth="46" fontSize="14" color="#666666" alignment="MiddleRight">--</Text>')
    end
    table.insert(c, '</HorizontalLayout>')
  end

  -- Game-history sparkline (most recent games, left→right oldest→newest)
  local N = 24
  local startIdx = math.max(1, #hist - N + 1)
  table.insert(c, '<Text fontSize="15" color="#CCCCCC" alignment="MiddleLeft">Recent games</Text>')
  table.insert(c, '<HorizontalLayout preferredHeight="54" spacing="2" childAlignment="LowerLeft"'
    .. ' childForceExpandHeight="false" childForceExpandWidth="false">')
  for i = startIdx, #hist do
    local acc = hist[i].acc or 0
    local h = math.max(3, math.floor(acc / 100 * 50 + 0.5))
    table.insert(c, '<Panel preferredWidth="11" minWidth="11" preferredHeight="' .. h .. '" minHeight="' .. h
      .. '" flexibleHeight="0" color="' .. accuracyColorHex(acc) .. '" />')
  end
  table.insert(c, '</HorizontalLayout>')

  -- Last 5 games (newest first), clickable into the per-game detail.
  local last5 = {}
  for i = #hist, math.max(1, #hist - 4), -1 do table.insert(last5, hist[i]) end
  if #last5 > 0 then
    table.insert(c, '<Text fontSize="15" color="#CCCCCC" alignment="MiddleLeft">Last 5 games</Text>')
    for idx, gh in ipairs(last5) do
      local acc = gh.acc or 0
      table.insert(c, '<HorizontalLayout preferredHeight="26" minHeight="26" spacing="8">')
      table.insert(c, '<Button id="statsPlayerGame_' .. idx .. '_' .. color .. '" onClick="onStatsPlayerGameClick"'
        .. ' colors="#00000000|#FFFFFF22|#FFFFFF11|#00000000" preferredWidth="150" preferredHeight="24">'
        ..
        '<Text fontSize="14" color="#9FD0FF" alignment="MiddleLeft">' ..
        os.date("%Y-%m-%d %H:%M", gh.ts or 0) .. '</Text></Button>')
      table.insert(c, '<ProgressBar percentage="' .. string.format("%.0f", acc) .. '" fillImageColor="'
        .. accuracyColorHex(acc) .. '" color="#2A2A2A" flexibleWidth="1" preferredHeight="14" />')
      table.insert(c, '<Text preferredWidth="50" fontSize="14" color="#FFFFFF" alignment="MiddleRight">'
        .. string.format("%.0f%%", acc) .. '</Text>')
      table.insert(c, '</HorizontalLayout>')
    end
  end

  table.insert(c, '</VerticalLayout></VerticalScrollView></VerticalLayout>')
  return table.concat(c, "\n")
end

-- SESSION tab: this-session group accuracy + a per-game breakdown.
local function buildStatsSessionContent(color)
  local sum = statsBookQuery(color, "querySessionJson") or { gameCount = 0, groupAccuracy = 0 }
  local sessGames = statsBookQuery(color, "querySessionGamesJson") or {}
  local c = {}
  table.insert(c, '<VerticalLayout spacing="6" padding="6 6 6 6" childForceExpandHeight="false">')
  table.insert(c, '<HorizontalLayout preferredHeight="34" flexibleHeight="0" spacing="10">')
  table.insert(c, '<Text fontSize="20" color="#FFFFFF" alignment="MiddleLeft" flexibleWidth="1">This session: '
    .. (sum.gameCount or 0) .. ' game(s)</Text>')
  table.insert(c,
    '<Text fontSize="20" color="' ..
    accuracyColorHex(sum.groupAccuracy) .. '" alignment="MiddleRight" preferredWidth="170">Group '
    .. string.format("%.0f%%", sum.groupAccuracy or 0) .. '</Text>')
  table.insert(c, '</HorizontalLayout>')
  if #sessGames == 0 then
    table.insert(c,
      '<Text fontSize="16" color="#888888" alignment="MiddleCenter">No games played this session yet.</Text>')
  else
    table.insert(c,
      '<Text preferredHeight="18" flexibleHeight="0" fontSize="14" color="#999999" alignment="MiddleLeft">Games (newest first)</Text>')
    table.insert(c, '<VerticalScrollView flexibleHeight="1" scrollSensitivity="30" color="#141414F0">')
    table.insert(c, '<VerticalLayout spacing="4" childForceExpandHeight="false" flexibleHeight="0" minHeight="'
      .. (#sessGames * 32 + 6) .. '">')
    for i, g in ipairs(sessGames) do
      local pct = g.groupAccuracy or 0
      table.insert(c, '<HorizontalLayout preferredHeight="28" minHeight="28" spacing="8">')
      table.insert(c, '<Button id="statsSessionRow_' .. i .. '_' .. color .. '" onClick="onStatsSessionRowClick"'
        .. ' colors="#00000000|#FFFFFF22|#FFFFFF11|#00000000" preferredWidth="150" preferredHeight="26">'
        .. '<Text fontSize="14" color="#9FD0FF" alignment="MiddleLeft">' .. (g.date or "?") .. '</Text></Button>')
      table.insert(c, '<ProgressBar percentage="' .. string.format("%.0f", pct) .. '" fillImageColor="'
        .. accuracyColorHex(pct) .. '" color="#2A2A2A" flexibleWidth="1" preferredHeight="16" />')
      table.insert(c,
        '<Text preferredWidth="55" fontSize="14" color="#FFFFFF" alignment="MiddleRight">' ..
        string.format("%.0f%%", pct) .. '</Text>')
      table.insert(c,
        '<Text preferredWidth="46" fontSize="13" color="#999999" alignment="MiddleCenter">' ..
        (g.playerCount or 0) .. 'p</Text>')
      table.insert(c, '</HorizontalLayout>')
    end
    table.insert(c, '</VerticalLayout></VerticalScrollView>')
  end
  table.insert(c, '</VerticalLayout>')
  return table.concat(c, "\n")
end

-- ROUND tab: pick R1-R4, see every player's average accuracy for that round.
local function buildStatsRoundContent(color)
  local s = statsState(color)
  local c = {}
  table.insert(c, '<VerticalLayout spacing="6" padding="6 6 6 6" childForceExpandHeight="false">')
  -- Round selector
  table.insert(c, '<HorizontalLayout preferredHeight="36" flexibleHeight="0" spacing="6" childAlignment="MiddleLeft">')
  for r = 1, 4 do
    local active = (s.round == r)
    local cols = active and "#D9AD33FF|#E5BD55FF|#C89B2BFF|#777777FF" or "#2A2A2AFF|#444444FF|#1E1E1EFF|#111111FF"
    local txt = active and "#1B1B1B" or "#DDDDDD"
    table.insert(c, '<Button id="statsRound_' .. r .. '_' .. color .. '" onClick="onStatsRound" colors="' .. cols
      ..
      '" preferredWidth="70" preferredHeight="32"><Text fontSize="16" color="' ..
      txt .. '" alignment="MiddleCenter">R' .. r .. '</Text></Button>')
  end
  table.insert(c, '</HorizontalLayout>')
  local rows = statsBookQuery(color, "queryRoundJson", JSON.encode({ r = s.round, scope = s.scope })) or {}
  if #rows == 0 then
    table.insert(c,
      '<Text fontSize="16" color="#888888" alignment="MiddleCenter">No data for R' .. s.round .. '.</Text>')
  else
    table.insert(c, '<VerticalScrollView flexibleHeight="1" scrollSensitivity="30" color="#141414F0">')
    table.insert(c, '<VerticalLayout spacing="4" childForceExpandHeight="false" flexibleHeight="0" minHeight="'
      .. (#rows * 34 + 6) .. '">')
    for i, r in ipairs(rows) do
      local pct = r.avg or 0
      table.insert(c, '<HorizontalLayout preferredHeight="30" minHeight="30" spacing="8">')
      table.insert(c,
        '<Text preferredWidth="30" fontSize="16" color="#CCCCCC" alignment="MiddleRight">' .. i .. '</Text>')
      table.insert(c, '<Button id="statsRoundRow_' .. i .. '_' .. color .. '" onClick="onStatsRoundRowClick"'
        .. ' colors="#00000000|#FFFFFF22|#FFFFFF11|#00000000" preferredWidth="150" preferredHeight="28">'
        .. '<Text fontSize="16" color="#FFFFFF" alignment="MiddleLeft">' .. (r.name or "?") .. '</Text></Button>')
      table.insert(c, '<ProgressBar percentage="' .. string.format("%.0f", pct) .. '" fillImageColor="'
        .. accuracyColorHex(pct) .. '" color="#2A2A2A" flexibleWidth="1" preferredHeight="16" />')
      table.insert(c,
        '<Text preferredWidth="55" fontSize="16" color="#FFFFFF" alignment="MiddleRight">' ..
        string.format("%.0f%%", pct) .. '</Text>')
      table.insert(c,
        '<Text preferredWidth="46" fontSize="13" color="#999999" alignment="MiddleCenter">' ..
        (r.games or 0) .. 'g</Text>')
      table.insert(c, '</HorizontalLayout>')
    end
    table.insert(c, '</VerticalLayout></VerticalScrollView>')
  end
  table.insert(c, '</VerticalLayout>')
  return table.concat(c, "\n")
end

-- GAME detail (opened from a SESSION row): every player's per-round scores for
-- one game, ranked by accuracy. Player names link to their PLAYER tab.
local function buildStatsGameContent(color)
  local gameId = statsState(color).gameId
  if not gameId then
    return '<Text fontSize="18" color="#888888" alignment="MiddleCenter">No game selected.</Text>'
  end
  local g = statsBookQuery(color, "queryGameJson", gameId)
  if not g or not g.players or #g.players == 0 then
    return '<Text fontSize="18" color="#888888" alignment="MiddleCenter">No data for this game.</Text>'
  end
  local c = {}
  table.insert(c, '<VerticalLayout spacing="5" padding="4 4 4 4" childForceExpandHeight="false">')

  -- Header: back to session + date
  table.insert(c, '<HorizontalLayout preferredHeight="30" flexibleHeight="0" spacing="10">')
  table.insert(c,
    '<Button id="statsBackSession_' ..
    color .. '" onClick="onStatsBackToSession" colors="#2A2A2AFF|#444444FF|#1E1E1EFF|#111111FF"'
    ..
    ' preferredWidth="92" preferredHeight="26"><Text fontSize="15" color="#DDDDDD" alignment="MiddleCenter">← Back</Text></Button>')
  table.insert(c,
    '<Text fontSize="18" color="#FFFFFF" alignment="MiddleLeft" flexibleWidth="1">Game — ' ..
    (g.date or "?") .. '</Text>')
  table.insert(c, '</HorizontalLayout>')

  -- Column headers
  table.insert(c, '<HorizontalLayout preferredHeight="20" flexibleHeight="0" spacing="6">')
  table.insert(c, '<Text preferredWidth="150" fontSize="13" color="#999999" alignment="MiddleLeft">Player</Text>')
  for r = 1, 4 do
    table.insert(c,
      '<Text preferredWidth="52" fontSize="13" color="#999999" alignment="MiddleCenter">R' .. r .. '</Text>')
  end
  table.insert(c, '<Text preferredWidth="60" fontSize="13" color="#999999" alignment="MiddleRight">Game</Text>')
  table.insert(c, '</HorizontalLayout>')

  -- One row per player (scrollable)
  table.insert(c, '<VerticalScrollView flexibleHeight="1" scrollSensitivity="30" color="#141414F0">')
  table.insert(c, '<VerticalLayout spacing="3" childForceExpandHeight="false" flexibleHeight="0" minHeight="'
    .. (#g.players * 29 + 6) .. '">')
  for i, pl in ipairs(g.players) do
    table.insert(c, '<HorizontalLayout preferredHeight="26" minHeight="26" spacing="6">')
    table.insert(c, '<Button id="statsGameRow_' .. i .. '_' .. color .. '" onClick="onStatsGameRowClick"'
      .. ' colors="#00000000|#FFFFFF22|#FFFFFF11|#00000000" preferredWidth="150" preferredHeight="24">'
      .. '<Text fontSize="15" color="#FFFFFF" alignment="MiddleLeft">' .. (pl.name or "?") .. '</Text></Button>')
    for r = 1, 4 do
      local t = statsPerRound(pl.rounds, r)
      local txt = t and string.format("%.0f", t.score) or "–"
      local col = t and accuracyColorHex(t.score) or "#666666"
      table.insert(c,
        '<Text preferredWidth="52" fontSize="14" color="' .. col .. '" alignment="MiddleCenter">' .. txt .. '</Text>')
    end
    table.insert(c, '<Text preferredWidth="60" fontSize="15" color="' .. accuracyColorHex(pl.accuracy)
      .. '" alignment="MiddleRight">' .. string.format("%.0f%%", pl.accuracy or 0) .. '</Text>')
    table.insert(c, '</HorizontalLayout>')
  end
  table.insert(c, '</VerticalLayout></VerticalScrollView>')

  table.insert(c, '</VerticalLayout>')
  return table.concat(c, "\n")
end

-- Build a single tab button; the active view is highlighted gold. The GAME
-- detail view keeps the SESSION tab highlighted (it's opened from there).
local function statsTabButton(color, id, label)
  local view = statsState(color).view
  local active = (view == id) or (id == "session" and view == "game")
  local cols = active and "#D9AD33FF|#E5BD55FF|#C89B2BFF|#777777FF"
      or "#2A2A2AFF|#444444FF|#1E1E1EFF|#111111FF"
  local txt = active and "#1B1B1B" or "#DDDDDD"
  return '<Button id="statsTab_' .. id .. '_' .. color .. '" onClick="onStatsTab" colors="' .. cols
      .. '" preferredWidth="150" preferredHeight="42">'
      .. '<Text fontSize="18" color="' .. txt .. '" alignment="MiddleCenter">' .. label .. '</Text></Button>'
end

-- One player's panel. visibility="<color>" makes it client-side: only that
-- player sees and interacts with it, so nobody can close another's overlay.
function buildStatsOverlayXml(color)
  local s = statsState(color)
  local scopeLabel = (s.scope == "career") and "Scope: Career" or "Scope: Session"
  local search = string.gsub(s.search or "", '"', "")
  local p = {}

  table.insert(p, '<Panel id="statsOverlay_' .. color .. '" visibility="' .. color .. '"'
    .. ' allowDragging="true" returnToOriginalPositionWhenReleased="false"'
    .. ' rectAlignment="MiddleCenter" width="760" height="540" offsetXY="0 0">')
  table.insert(p, '<Panel color="#0A0A0AF2" padding="16 16 14 16">')
  -- childForceExpandHeight="false": the fixed rows keep their preferredHeight and
  -- only the content panel (flexibleHeight=1) grows. Without this, the scroll view
  -- collapses the content's reported height and the layout splits height ~evenly.
  table.insert(p, '<VerticalLayout spacing="10" childForceExpandHeight="false">')

  -- Header: title + close
  table.insert(p, '<HorizontalLayout preferredHeight="46" flexibleHeight="0" spacing="10">')
  table.insert(p, '<Text fontSize="28" color="#D9AD33" alignment="MiddleLeft" flexibleWidth="1">THE GANG SENSE</Text>')
  table.insert(p,
    '<Button id="statsClose_' .. color .. '" onClick="onStatsClose" colors="#661111FF|#882222FF|#441111FF|#331111FF"'
    ..
    ' preferredWidth="46" preferredHeight="40"><Text fontSize="22" color="#FFDDDD" alignment="MiddleCenter">X</Text></Button>')
  table.insert(p, '</HorizontalLayout>')

  -- Tabs
  table.insert(p, '<HorizontalLayout preferredHeight="46" flexibleHeight="0" spacing="8" childAlignment="MiddleLeft">')
  table.insert(p, statsTabButton(color, "board", "BOARD"))
  table.insert(p, statsTabButton(color, "player", "PLAYER"))
  table.insert(p, statsTabButton(color, "session", "SESSION"))
  table.insert(p, statsTabButton(color, "round", "ROUND"))
  table.insert(p, '</HorizontalLayout>')

  -- Scope toggle + player search
  table.insert(p, '<HorizontalLayout preferredHeight="40" flexibleHeight="0" spacing="10">')
  table.insert(p,
    '<Button id="statsScope_' .. color .. '" onClick="onStatsScope" colors="#2A2A2AFF|#444444FF|#1E1E1EFF|#111111FF"'
    .. ' preferredWidth="190" preferredHeight="36"><Text fontSize="16" color="#DDDDDD" alignment="MiddleCenter">'
    .. scopeLabel .. '</Text></Button>')
  -- Connected-only toggle: filter the BOARD to players currently at the table (keeping ranks).
  local connOn = s.connectedOnly
  local connCols = connOn and "#3A5A3AFF|#4A7A4AFF|#2A4A2AFF|#111111FF" or "#2A2A2AFF|#444444FF|#1E1E1EFF|#111111FF"
  table.insert(p,
    '<Button id="statsConnected_' .. color .. '" onClick="onStatsConnected" colors="' .. connCols
    .. '" preferredWidth="170" preferredHeight="36"><Text fontSize="16" color="#DDDDDD" alignment="MiddleCenter">'
    .. (connOn and "Connected only" or "All players") .. '</Text></Button>')
  table.insert(p,
    '<InputField id="statsSearch_' .. color .. '" onEndEdit="onStatsSearch" placeholder="Search player..." text="'
    .. search .. '" fontSize="16" preferredHeight="36" flexibleWidth="1" color="#1E1E1E" textColor="#FFFFFF" />')
  table.insert(p, '<Button id="statsSearchClear_' .. color .. '" onClick="onStatsSearchClear"'
    .. ' colors="#2A2A2AFF|#444444FF|#1E1E1EFF|#111111FF" preferredWidth="40" preferredHeight="36">'
    .. '<Text fontSize="18" color="#DDDDDD" alignment="MiddleCenter">✕</Text></Button>')
  table.insert(p, '</HorizontalLayout>')

  -- Content area — dispatch by active tab.
  table.insert(p, '<Panel color="#141414F0" flexibleHeight="1" padding="10 10 10 10">')
  if s.view == "board" then
    table.insert(p, buildStatsBoardContent(color))
  elseif s.view == "player" then
    table.insert(p, buildStatsPlayerContent(color))
  elseif s.view == "session" then
    table.insert(p, buildStatsSessionContent(color))
  elseif s.view == "round" then
    table.insert(p, buildStatsRoundContent(color))
  elseif s.view == "game" then
    table.insert(p, buildStatsGameContent(color))
  end
  table.insert(p, '</Panel>')

  table.insert(p, '</VerticalLayout>')
  table.insert(p, '</Panel>')
  table.insert(p, '</Panel>')
  return table.concat(p, "\n")
end

-- Toggle a player's own overlay open/closed. Called from a Stats Book via
-- Global.call with a JSON payload { guid, color } (the clicking player + book).
function toggleStatsOverlay(payload)
  local guid, color
  if type(payload) == "string" then
    local ok, d = pcall(function() return JSON.decode(payload) end)
    if ok and type(d) == "table" then guid, color = d.guid, d.color end
  end
  if not color then return end
  local s = statsState(color)
  if type(guid) == "string" then s.bookGUID = guid end
  s.open = not s.open
  refreshGlobalUI()
end

function onStatsClose(player)
  statsState(player.color).open = false
  refreshGlobalUI()
end

-- Tab button id is "statsTab_<view>_<color>".
function onStatsTab(player, _value, id)
  local view = string.match(id or "", "^statsTab_(%a+)_")
  if view then
    statsState(player.color).view = view
    refreshGlobalUI()
  end
end

function onStatsScope(player)
  local s = statsState(player.color)
  s.scope = (s.scope == "career") and "session" or "career"
  refreshGlobalUI()
end

-- BOARD filter: toggle between all players and only those currently at the table.
function onStatsConnected(player)
  local s = statsState(player.color)
  s.connectedOnly = not s.connectedOnly
  refreshGlobalUI()
end

-- Round selector on the ROUND tab (id "statsRound_<r>_<color>").
function onStatsRound(player, _value, id)
  local r = tonumber(string.match(id or "", "^statsRound_(%d+)_"))
  if r and r >= 1 and r <= 4 then
    statsState(player.color).round = r
    refreshGlobalUI()
  end
end

-- Click a leaderboard row (id "statsRow_<i>_<color>") to open that player's detail.
-- Indexes into the same filtered list the board rendered, so it stays in sync.
function onStatsRowClick(player, _value, id)
  local idx = tonumber(string.match(id or "", "^statsRow_(%d+)_"))
  if not idx then return end
  local row = getStatsLeaderboardRows(player.color)[idx]
  if row then
    local s = statsState(player.color)
    s.playerKey = row.key
    s.view = "player"
    refreshGlobalUI()
  end
