-- Click a player on the ROUND tab (id "statsRoundRow_<i>_<color>") → their detail.
function onStatsRoundRowClick(player, _value, id)
  local idx = tonumber(string.match(id or "", "^statsRoundRow_(%d+)_"))
  if not idx then return end
  local s = statsState(player.color)
  local rows = statsBookQuery(player.color, "queryRoundJson", JSON.encode({ r = s.round, scope = s.scope })) or {}
  local row = rows[idx]
  if row then
    s.playerKey = row.key
    s.view = "player"
    refreshGlobalUI()
  end
