-- Click a game on the SESSION tab (id "statsSessionRow_<i>_<color>") → its detail.
function onStatsSessionRowClick(player, _value, id)
  local idx = tonumber(string.match(id or "", "^statsSessionRow_(%d+)_"))
  if not idx then return end
  local list = statsBookQuery(player.color, "querySessionGamesJson") or {}
  local g = list[idx]
  if g then
    local s = statsState(player.color)
    s.gameId = g.gameId
    s.gameBackView = "session"
    s.view = "game"
    refreshGlobalUI()
  end
end

-- Click one of a player's "Last 5 games" (id "statsPlayerGame_<i>_<color>") → its detail.
function onStatsPlayerGameClick(player, _value, id)
  local idx = tonumber(string.match(id or "", "^statsPlayerGame_(%d+)_"))
  if not idx then return end
  local s = statsState(player.color)
  local d = statsBookQuery(player.color, "queryPlayerDetailJson", s.playerKey)
  local hist = (d and d.career and d.career.history) or {}
  local last5 = {}
  for i = #hist, math.max(1, #hist - 4), -1 do table.insert(last5, hist[i]) end
  local entry = last5[idx]
  if entry then
    s.gameId = entry.gameId
    s.gameBackView = "player"
    s.view = "game"
    refreshGlobalUI()
  end
end

-- Back from a game detail to wherever it was opened from (SESSION list or PLAYER).
function onStatsBackToSession(player)
  local s = statsState(player.color)
  s.view = s.gameBackView or "session"
  refreshGlobalUI()
end

-- Click a player in a game detail (id "statsGameRow_<i>_<color>") → their detail.
function onStatsGameRowClick(player, _value, id)
  local idx = tonumber(string.match(id or "", "^statsGameRow_(%d+)_"))
  if not idx then return end
  local s = statsState(player.color)
  local g = statsBookQuery(player.color, "queryGameJson", s.gameId)
