--- SECTION 9: Circle Drawing
------------------------------------

function drawCircles()
  local circleRadius = 2
  local circleThickness = 0.2
  local circleSpacing = 5
  local circleColors = { "White", "Yellow", "Orange", "Red" }

  -- Check challenge tokens for skipped rows
  if activeChallenges.QUICK_ACCESS then circleColors[1] = "Black" end
  if activeChallenges.QUICK_EXECUTION then circleColors[2] = "Black" end
  if activeChallenges.HASTY_GETAWAY then circleColors[3] = "Black" end

  for playerColor, _ in pairs(playerParameters) do
    if playerParameters[playerColor] and playerParameters[playerColor].topChipSpaceObj and playerParameters[playerColor].botChipSpaceObj then
      local topChipSpaceObj = playerParameters[playerColor].topChipSpaceObj
      local botChipSpaceObj = playerParameters[playerColor].botChipSpaceObj

      if isActiveParticipant(playerColor) then -- benched seats (#19) get no circles (fall to blank branch)
        local discarded = discardedChipSpaces[playerColor] or {}

        -- Build vector lines for one chip space, blacking out only the discarded circle index.
        local function buildLines(hand)
          local discardedRound = discarded[hand]
          local lines = {}
          for j, color in ipairs(circleColors) do
            local offsetZ = (j - 1) * circleSpacing - (circleSpacing * (#circleColors - 1) / 2)
            local points = getCircleVectorPoints(circleRadius, 32, 0.01, 0, offsetZ)
            table.insert(lines, {
              points    = points,
              color     = (discardedRound == j) and "Black" or color,
              thickness = circleThickness,
              rotation  = { 0, -90, 0 }
            })
          end
          return lines
        end

        topChipSpaceObj.setVectorLines(buildLines("Top"))
        botChipSpaceObj.setVectorLines(buildLines("Bot"))
      else
        topChipSpaceObj.setVectorLines({})
        botChipSpaceObj.setVectorLines({})
      end
    end
  end
end

function getCircleVectorPoints(radius, steps, offsetY, offsetX, offsetZ)
  offsetX = offsetX or 0
  offsetZ = offsetZ or 0

  local t = {}
  local d, s, c, r = 360 / steps, math.sin, math.cos, math.rad
  for i = 0, steps do
    table.insert(t, {
      c(r(d * i)) * radius + offsetX,
      offsetY,
      s(r(d * i)) * radius + offsetZ
    })
  end
  return t
end

