-- Offset for replacement cards dealt when a Joker is found in a player's hand
-- Two cards are placed at nameplate.x ± jokerOffset.x, jokerOffset.y, nameplate.z + jokerOffset.z * jokerIndex
-- Fixed return positions for Joker cards removed from hands
function communityCreateTiles()
  local mode = getGameMode()

  -- Per-player modes use completely different tile layouts
  if mode.perGap or mode.perPlayer then
    if mode.perGap then
      communityCreateTilesBanana()
    else
      communityCreateTilesStud()
    end
    -- Position challenge reminder buttons at center of table
    if challengeReminderHandRankObj and challengeReminderNumberObj then
      local tileY = deckTileBasePosition.y - 0.2
      challengeReminderHandRankObj.setPosition({
        x = -challengeReminderOffset.x,
        y = tileY + challengeReminderOffset.y,
        z = deckTileBasePosition.z + challengeReminderOffset.z
      })
      challengeReminderNumberObj.setPosition({
        x = challengeReminderOffset.x,
        y = tileY + challengeReminderOffset.y,
        z = deckTileBasePosition.z + challengeReminderOffset.z
      })
    end
    return
  end

  local pocketCards = mode.pocketCards
  local flopCards = mode.flopCards
  local turnCards = mode.turnCards
  local riverCards = mode.riverCards

  local extraPocketCards = 0
  local extraFlopCards = 0
  local extraTurnCards = 0
  local extraRiverCards = 0
  if isChallengeCompatible("REVERSE_RUN") and activeChallenges.REVERSE_RUN then
    flopCards = 1
    riverCards = 3
  end
  if isChallengeCompatible("FOOT_DOOR") then
    extraPocketCards = extraPocketCards + math.min((activeChallenges.FOOT_DOOR or 0), 2)
  end
  if isChallengeCompatible("UNINVITED_GUEST") then
    extraTurnCards = extraTurnCards + math.min((activeChallenges.UNINVITED_GUEST or 0), 2)
  end
  if isChallengeCompatible("LENGTHY_FINISH") then
    extraRiverCards = extraRiverCards + math.min((activeChallenges.LENGTHY_FINISH or 0), 2)
  end
  if isChallengeCompatible("ROUGH_KICKOFF") then
    extraFlopCards = extraFlopCards + math.min((activeChallenges.ROUGH_KICKOFF or 0), 2)
  end
  pocketCards = pocketCards + extraPocketCards
  flopCards = flopCards + extraFlopCards
  turnCards = turnCards + extraTurnCards
  riverCards = riverCards + extraRiverCards

  -- LIL_OMAHA: if total extra community cards >= 2, must play at least 1 hand card
  -- Suppressed when user has toggled lilOmahaEnabled off, or when All Out Attack / Sleeping Guard
  -- is active (those challenges already force exactly one hand card to be played).
  lilOmahaTriggered = (extraPocketCards + extraTurnCards + extraRiverCards + extraFlopCards) >= 2
  lilOmaha = lilOmahaTriggered and lilOmahaEnabled and not (forceHighCard or forceLowCard)

  -- Track which round is the first with tiles (for positioning formula)
  communityFirstActiveRound = (pocketCards > 0) and 1 or 2

  -- Reposition deck tile and related objects based on total community cards
  -- Shifts left by half a tile offset for each card beyond 5 to keep the board centered
  local totalCommunityCards = pocketCards + flopCards + turnCards + riverCards
  local extraCards = math.max(0, totalCommunityCards - 5)
  local deckNewPos = {
    x = deckTileBasePosition.x + extraCards * 0.5 * communityOffsetTile.x,
    y = deckTileBasePosition.y,
    z = deckTileBasePosition.z
  }
  positionDeckAndRelatedTiles(deckNewPos)

  -- Spawn Pre-Flop Tiles (challenge 39)
  for i = 1, pocketCards do
    if bagCommunityTiles[1] then
      communitySpawnTile(1, i, bagCommunityTiles[1])
    end
  end

  -- Spawn Flop Tiles
  for i = 1, flopCards do
    if bagCommunityTiles[2] then
      communitySpawnTile(2, i + pocketCards, bagCommunityTiles[2])
    end
  end

  -- Spawn Turn Tiles
  for i = 1, turnCards do
    if bagCommunityTiles[3] then
      communitySpawnTile(3, i + flopCards + pocketCards, bagCommunityTiles[3])
    end
  end

  -- Spawn River Tiles
  for i = 1, riverCards do
    if bagCommunityTiles[4] then
      communitySpawnTile(4, i + turnCards + flopCards + pocketCards, bagCommunityTiles[4])
    end
  end

  -- Move Reminder Buttons
  if challengeReminderHandRankObj and challengeReminderNumberObj then
    local lastColumn = riverCards + turnCards + flopCards + pocketCards
    local basePosition = getObjectFromGUID(communityTileGUIDs[4][lastColumn][1].guid)
        .getPosition()

    challengeReminderHandRankObj.setPosition({
      x = basePosition.x - challengeReminderOffset.x,
      y = basePosition.y + challengeReminderOffset.y,
      z = basePosition.z + challengeReminderOffset.z
    })
    challengeReminderNumberObj.setPosition({
      x = basePosition.x + challengeReminderOffset.x,
      y = basePosition.y + challengeReminderOffset.y,
      z = basePosition.z + challengeReminderOffset.z
    })
  end
end

function communityDrawCard(tileObj)
  refreshDeckReference()
  if not tileObj or not deck then return end

  local tilePosition = tileObj.getPosition()
  local tileRotation = tileObj.getRotation()
  local drawnCard = nil or deck.takeObject({
    position = { tilePosition.x, tilePosition.y + 2, tilePosition.z },
    rotation = { 0, tileRotation.y, 0 },
    smooth = true
  })

  return drawnCard
end

-- Draws a card for a tile, discarding any Joker cards and redrawing until a non-Joker is found.
-- Used by 7-Card Stud and Banana Split where community Jokers are simply skipped.
function communityDrawCardSkipJoker(tileObj)
  for attempt = 1, 10 do
    local drawnCard = communityDrawCard(tileObj)
    if not drawnCard then return nil end

    if drawnCard.getGMNotes() ~= "Joker" then
      return drawnCard
    end

    -- Discard the Joker and try again
    if cardDiscardTileObj then
      local discardPos = cardDiscardTileObj.getPosition()
      drawnCard.setPosition({ discardPos.x, discardPos.y + 0.5, discardPos.z })
      drawnCard.setRotation({ 0, 0, 180 })
    end
  end
  return nil
end

function communityDrawCardsForRound(currentRound)
  if not currentRound then return end

  communityDrawing = true
  hideHandRankObjects()
  -- Disabled CPU mode never recomputes, so the prior round's ranks would linger. Blank the text
  -- now; a manual right-click recalc is the only way to repopulate them this round.
  if cpuMode == 0 then blankHandRankObjects() end
  Wait.time(function()
    communityDrawing = false
    handRankFingerprint = ""
  end, 1.5)

  local mode = getGameMode()
  if mode.perGap then
    -- Banana Split: draw cards for all gaps in this round
    for gapIndex, gapData in pairs(bananaGapTileGUIDs) do
      if gapData[currentRound] then
        for tileColumn, _ in pairs(gapData[currentRound]) do
          bananaDrawCardsForColumn(gapIndex, currentRound, tileColumn)
        end
      end
    end
  elseif mode.perPlayer then
    -- 7-Card Stud: draw cards for all players in this round
    for color, playerData in pairs(studTileGUIDs) do
      if playerData[currentRound] then
        for tileColumn, _ in pairs(playerData[currentRound]) do
          studDrawCardsForColumn(color, currentRound, tileColumn)
        end
      end
    end
  else
    -- Standard: draw cards for the central board
    if communityTileGUIDs[currentRound] then
      for tileColumn, _ in pairs(communityTileGUIDs[currentRound]) do
        if communityTileGUIDs[currentRound][tileColumn] then
          communityDrawCardsForColumn(currentRound, tileColumn)
        end
      end
    end
  end

  Wait.time(function() communityLagFix() end, 1)
end

function communityDrawCardsForColumn(currentRound, currentColumn)
  if not currentRound or
      not currentColumn or
      not communityTileGUIDs[currentRound] or
      not communityTileGUIDs[currentRound][currentColumn] then
    return
  end

  local jokerTiles = {}
  for _, tileData in ipairs(communityTileGUIDs[currentRound][currentColumn]) do
    local tileObj = getObjectFromGUID(tileData.guid)
    if tileObj and not tileData.card then
      local newCard = communityDrawCard(tileObj)
      if newCard then tileData.card = newCard end

      if newCard and newCard.getGMNotes() == "Joker" then
        table.insert(jokerTiles, {
          currentRound = currentRound,
          currentColumn = currentColumn,
          tileGUID = tileData.guid,
          card = newCard
        })
      end
    end
  end
  communityHandleJokerColumn(jokerTiles)
end

function communityHandleJokerColumn(jokerTiles)
  -- handle Joker in the community cards by replacing the original card with two new ones
  if #jokerTiles == 0 then return end

  for _, jokerData in ipairs(jokerTiles) do
    local tileObj = getObjectFromGUID(jokerData.tileGUID)
    if tileObj and jokerData.card then
      local numTilesInColumn = #communityTileGUIDs[jokerData.currentRound][jokerData.currentColumn]

      if numTilesInColumn < 3 then
        communitySpawnTile(jokerData.currentRound, jokerData.currentColumn, bagCommunityTiles[jokerData.currentRound])

        -- Reposition all tiles in the column based on the new number of tiles
        for index, tileData in ipairs(communityTileGUIDs[jokerData.currentRound][jokerData.currentColumn]) do
          local columnTileObj = getObjectFromGUID(tileData.guid)
          local columnTileScriptZoneObj = getObjectFromGUID(tileData.scriptZoneGUID)

          if columnTileObj then
            local basePos = getCommunityTilePosition(jokerData.currentRound, jokerData.currentColumn)
            local position = {
              x = basePos.x,
              y = basePos.y,
              z = basePos.z + (index - 1 - (numTilesInColumn - 1) / 2) * communityOffsetTile.z
            }
            columnTileObj.setPosition(position)
            if columnTileScriptZoneObj then
              columnTileScriptZoneObj.setPosition({ position.x, position.y, position.z })
            end
          end
        end
      end
    end

    for _, tileData in ipairs(communityTileGUIDs[jokerData.currentRound][jokerData.currentColumn]) do
      local tileObj = getObjectFromGUID(tileData.guid)
      if tileData.card and tileData.card.isDestroyed() then tileData.card = nil end
      if tileObj and tileData.card then
        local position = tileObj.getPosition()
        if tileData.card == jokerData.card then
          tileData.card.destruct()
          tileData.card = nil
        else
          tileData.card.setPositionSmooth({ position.x, position.y + 2, position.z })
        end
      end
    end

    -- Schedule a joker marker spawn/reposition above this column's topmost tile.
    -- Uses a version counter so only the LAST scheduled callback per column actually runs,
    -- ensuring correct position after all recursive joker processing finishes.
    local colKey = jokerData.currentRound .. "_" .. jokerData.currentColumn
    communityJokerMarkerVersion[colKey] = (communityJokerMarkerVersion[colKey] or 0) + 1
    local myVersion = communityJokerMarkerVersion[colKey]
    local spawnRound = jokerData.currentRound
    local spawnColumn = jokerData.currentColumn

    Wait.frames(function()
      -- Only the last scheduled callback for this column should execute
      if communityJokerMarkerVersion[colKey] ~= myVersion then return end

      -- Destroy any previously spawned marker for this column
      if communityJokerMarkers[colKey] and not communityJokerMarkers[colKey].isDestroyed() then
        communityJokerMarkers[colKey].destruct()
        communityJokerMarkers[colKey] = nil
      end

      local tiles = communityTileGUIDs[spawnRound] and communityTileGUIDs[spawnRound][spawnColumn]
      if not tiles or #tiles == 0 then return end

      local firstTileObj = getObjectFromGUID(tiles[1].guid)
      if not firstTileObj then return end

      local topPos = firstTileObj.getPosition()
      local markerPos = {
        x = topPos.x + jokerCommunityCardOffset.x,
        y = topPos.y + jokerCommunityCardOffset.y,
        z = topPos.z + jokerCommunityCardOffset.z
      }
      local markerRot = {
        x = jokerCommunityCardRotation.x,
        y = jokerCommunityCardRotation.y,
        z = jokerCommunityCardRotation.z
      }
      bagJokerObj.takeObject({
        position = markerPos,
        rotation = markerRot,
        smooth = false,
        callback_function = function(card)
          if card then
            card.setLock(true)
            communityJokerMarkers[colKey] = card
            -- Lag fix: nudge the marker card after 2s to force TTS to re-render it
            Wait.time(function()
              if card and not card.isDestroyed() then
                local pos = card.getPosition()
                card.setPosition({ pos.x, pos.y + communityOffsetFix, pos.z })
              end
            end, 2)
          end
        end
      })
    end, 5)

    communityDrawCardsForColumn(jokerData.currentRound, jokerData.currentColumn)
  end
end

function getCommunityTilePosition(tileRound, tileColumn)
  -- Derives community tile position from the deck tile.
  -- First tile spawns one tile width + a gap away from the deck.
  local deckPos = deckTile.getPosition()
  return {
    x = deckPos.x - tileColumn * communityOffsetTile.x -
        (tileRound - communityFirstActiveRound) * communityOffsetRound.x -
        communityOffsetRound.x,
    y = deckPos.y - 0.2,
    z = deckPos.z
  }
end

function communitySpawnTile(tileRound, tileColumn, tileBag)
  -- spawns a community tile from the bag to the given column and saves the GUID as [round][column]{GUID}
  if not tileRound or not tileColumn or not tileBag then return nil end

  local tilePosition = getCommunityTilePosition(tileRound, tileColumn)
  local tileRotation = { x = 0, y = 0, z = 0, }

  local newTile = tileBag.takeObject({
    position = tilePosition,
    rotation = tileRotation,
    smooth = false,
  })

  if newTile then
    newTile.setLock(true)
    newTile.setGMNotes("communityTile")
    newTile.interactable = DEFAULT_INTERACTABLE

    local scriptZonePosition = { tilePosition.x, tilePosition.y, tilePosition.z }
    local scriptZoneRotation = { tileRotation.x, tileRotation.y, tileRotation.z }
    local scriptZoneScale = communityScriptZoneScaleVertical
    local scriptZone = spawnObject({
      type = "ScriptingTrigger",
      position = scriptZonePosition,
      rotation = scriptZoneRotation,
      scale = scriptZoneScale,
    })
    scriptZone.setGMNotes("communityScriptZone")

    communityAddTileToGUIDList(tileRound, tileColumn, newTile.getGUID(), scriptZone.getGUID())
  end

  Wait.time(function() communityLagFix() end, 1) -- extra fix after a short delay to ensure proper positioning
  Wait.time(function() communityLagFix() end, 2) -- extra fix after a short delay to ensure proper positioning
  Wait.time(function() communityLagFix() end, 5) -- extra fix after a short delay to ensure proper positioning
end

function communityAddTileToGUIDList(tileRound, tileColumn, tileGUID, scriptZoneGUID)
  if not tileRound or not tileColumn or not tileGUID then return end

  communityTileGUIDs[tileRound] = communityTileGUIDs[tileRound] or {}
  communityTileGUIDs[tileRound][tileColumn] = communityTileGUIDs[tileRound][tileColumn] or {}
  table.insert(communityTileGUIDs[tileRound][tileColumn], {
    guid = tileGUID,
    card = nil,
    scriptZoneGUID = scriptZoneGUID,
  })
end

function communityCleanUp()
  -- remove all community tiles from the table and clear the GUID list
  local allObjects = getAllObjects()
  for _, obj in ipairs(allObjects) do
    if obj.getGMNotes() == "communityScriptZone" or obj.getGMNotes() == "communityTile" then
      obj.destruct()
    end
  end

  -- Reset deck tile and related objects to default position
  positionDeckAndRelatedTiles(deckTileBasePosition)

  -- Destroy cloned banana mirror cards and tiles
  for _, obj in ipairs(getAllObjects()) do
    if obj.hasTag(TAGS.bananaClone) then
      obj.destruct()
    end
  end

  communityTileGUIDs = {}
  studTileGUIDs = {}
  bananaGapTileGUIDs = {}
  bananaPlayerCommunityColumns = {}
  bananaGaps = {}
  bananaGapsByPlayer = {}
  bananaWrapMirrorTiles = {}
  communityJokerMarkers = {}
  communityJokerMarkerVersion = {}
end

function communityLagFix()
  -- Nudge a single tile (and its card) to fix TTS rendering lag
  local function nudgeTile(tileData)
    local columnTileObj = getObjectFromGUID(tileData.guid)
    if not columnTileObj then return end

    local tilePosition = columnTileObj.getPosition()
    columnTileObj.setPosition({ tilePosition.x, tilePosition.y + communityOffsetFix, tilePosition.z })

    -- A player can stack a manual card onto a community card; TTS merges both into a
    -- new Deck and destroys the original card object, leaving tileData.card a dead
    -- reference. Drop it so getPosition() doesn't throw a null-ref mid round flow.
    if tileData.card and tileData.card.isDestroyed() then tileData.card = nil end
    if tileData.card then
      local cardPosition = tileData.card.getPosition()
      if tilePosition.x == cardPosition.x and tilePosition.z == cardPosition.z then
        tileData.card.setPositionSmooth({ cardPosition.x,
          cardPosition.y + math.abs(communityOffsetFix),
          cardPosition.z })
      end
    end
  end

  -- Standard community tiles
  for round, roundTiles in pairs(communityTileGUIDs) do
    for column, columnTiles in pairs(roundTiles) do
      for _, tileData in ipairs(columnTiles) do
        nudgeTile(tileData)
      end
    end
  end

  -- Banana Split: per-gap tiles + mirror tiles
  for gapIndex, gapData in pairs(bananaGapTileGUIDs) do
    for round, roundData in pairs(gapData) do
      for column, columnTiles in pairs(roundData) do
        for _, tileData in ipairs(columnTiles) do
          nudgeTile(tileData)
        end
      end
    end
  end
  for gapIndex, gapData in pairs(bananaWrapMirrorTiles) do
    for round, roundData in pairs(gapData) do
      for column, mirrorTile in pairs(roundData) do
        if mirrorTile and not mirrorTile.isDestroyed() then
          local pos = mirrorTile.getPosition()
          mirrorTile.setPosition({ pos.x, pos.y + communityOffsetFix, pos.z })
        end
      end
    end
  end

  -- 7-Card Stud: per-player tiles
  for color, playerData in pairs(studTileGUIDs) do
    for round, roundData in pairs(playerData) do
      for column, columnTiles in pairs(roundData) do
        for _, tileData in ipairs(columnTiles) do
          nudgeTile(tileData)
        end
      end
    end
  end

  communityOffsetFix = communityOffsetFix * -1
end

