------------------------------------
--- Deck Tile Modifier Display
--- Shows active challenge modifiers as buttons on the deck tile.
--- Called after scanActiveChallenges() in roundSetup().
------------------------------------
function updateDeckTileModifiers()
  if not deckTile then return end
  deckTile.clearButtons()
  -- Re-apply snap point after clearing buttons
  deckTile.setSnapPoints({
    {
      position = { 0, 0, 0 },
      rotation = { 0, 0, 0 },
      rotation_snap = true
    }
  })

  -- Helper: build a modifier line from prefix + label
  -- Prefix is colored (via MODIFIER_COLORS) + italic + ":", label is gold
  local function buildModLine(prefix, label)
    local hex = MODIFIER_COLORS[prefix] or colorGold
    local result = ""
    for lang, prefixText in pairs(prefix) do
      local line = "[i][" .. hex .. "]" .. prefixText .. ":[-][/i]"
      if label and label ~= "" then
        local labelText
        if type(label) == "table" then
          labelText = label[lang] or label.en or ""
        else
          labelText = label
        end
        if labelText ~= "" then
          line = line .. " " .. labelText
        end
      end
      result = result .. "{" .. lang .. "}" .. line
    end
    return result
  end

  -- Build sorted list of active challenge keys that have a displayable modPrefix
  local activeKeys = {}
  for key, count in pairs(activeChallenges) do
    local entry = CHALLENGES[key]
    if entry and entry.modPrefix and entry.modPrefix ~= STRINGS.MOD_PREFIX_NONE then
      table.insert(activeKeys,
        {
          key = key,
          numId = tonumber(entry.id) or 0,
          count = count,
          prefixOrder = MODIFIER_PREFIX_ORDER
              [entry.modPrefix] or 99
        })
    end
  end
  table.sort(activeKeys, function(a, b)
    if a.prefixOrder ~= b.prefixOrder then return a.prefixOrder < b.prefixOrder end
    return a.numId < b.numId
  end)

  -- Collect formatted display lines
  local modifiers = {}
  for _, item in ipairs(activeKeys) do
    local entry = CHALLENGES[item.key]
    local label = entry.modLabel or ""
    -- Handle stacking: use stackFn if count > 1 and function exists
    if item.count > 1 and entry.stackFn then
      label = entry.stackFn(item.count)
    end

    -- Special case: Intricate Lock shows locked hand ranks (excluding force-locked flush ranks)
    if item.key == "INTRICATE_LOCK" then
      local forcedLocks = getForceLockedRanks()
      local locked = {}
      for _, rankData in ipairs(intricateLockRanks) do
        if lockedHandRanks[rankData.code] and not forcedLocks[rankData.code] then
          table.insert(locked, rankData.code)
        end
      end
      if #locked > 0 then
        label = table.concat(locked, ", ")
      else
        -- Skip entirely if nothing user-locked
        label = nil
      end
    end

    -- Special case: Grinding Gears label depends on rainbow toggle state
    if item.key == "GRINDING_GEARS" then
      label = rainbowEnabled and STRINGS.MOD_5TH_SUIT_RAINBOW or STRINGS.MOD_5TH_SUIT_ONLY
    end

    -- Special case: Cluttered Toolbox appends blanked value
    if item.key == "CLUTTERED_TOOLBOX" and blankedValue then
      local display = getBlankedValueDisplay(blankedValue)
      if type(label) == "table" then
        local combined = {}
        for lang, text in pairs(label) do
          combined[lang] = text .. ": " .. display
        end
        label = combined
      else
        label = label .. ": " .. display
      end
    end

    if label then
      table.insert(modifiers, buildModLine(entry.modPrefix, label))
    end
  end

  -- Append game mode header if not default
  if gameMode ~= 0 then
    local modeHeader = ""
    for lang, text in pairs(getGameMode().label) do
      modeHeader = modeHeader .. "{" .. lang .. "}[" .. colorGold .. "]★ " .. text .. " ★"
    end
    table.insert(modifiers, 1, modeHeader)
  end

  -- Append Omaha / Lil Omaha mode modifiers
  if FLAGS.Omaha then
    table.insert(modifiers, buildModLine(STRINGS.MOD_PREFIX_FORCE, STRINGS.MOD_OMAHA_TWO_HAND))
  elseif lilOmaha then
    table.insert(modifiers, buildModLine(STRINGS.MOD_PREFIX_FORCE, STRINGS.MOD_OMAHA_ONE_PLUS))
  end

  -- Append Short Deck modifier (flag, not a challenge token)
  if FLAGS.ShortDeck then
    table.insert(modifiers, buildModLine(STRINGS.MOD_PREFIX_MIXUP, STRINGS.MOD_SHORT_DECK))
  end

  -- Low Calc (cpuMode 1) bypasses the forced family during evaluation, so the shown ranks can
  -- diverge from the enforced rules. Warn (red) only when a bypassed rule is actually active.
  if cpuMode == 1 and (forceHighCard or forceLowCard or lilOmaha) then
    local warnLine = ""
    for lang, text in pairs(STRINGS.MOD_RANKS_APPROX) do
      warnLine = warnLine .. "{" .. lang .. "}[" .. colorRed .. "]" .. text
    end
    table.insert(modifiers, warnLine)
  end

  -- Append dealer mode header + current dealer name
  if dealerColor then
    local dealerHeader = ""
    for lang, text in pairs(STRINGS.DEALER_MODE_HEADER) do
      dealerHeader = dealerHeader .. "{" .. lang .. "}[" .. colorGold .. "]" .. text
    end
    table.insert(modifiers, 1, dealerHeader)
    local dealerHex = colorToRGBHex(dealerColor)
    local dealerName = getPlayerDisplayName(dealerColor)
    local dealerLine = ""
    for lang, text in pairs(STRINGS.DEALER_MODE_PREFIX) do
      dealerLine = dealerLine .. "{" .. lang .. "}[" .. colorGold .. "]" .. text .. "[" .. dealerHex .. "]" .. dealerName
    end
    table.insert(modifiers, 2, dealerLine)
  end

  -- Board hand rank (button index 0): the community board evaluated as its own hand, shown grey.
  -- Sits opposite the modifier stack (local -z = away from the players, above the deck). Created
  -- here FIRST so its index stays 0; the label is refreshed by updateBoardHandRankDisplay as the
  -- community changes. Empty label when there is no board (or in per-player modes) => nothing shown.
  deckTile.createButton({
    click_function = "doNothing",
    label = getBoardHandRank(),
    function_owner = self,
    position = { 0.8, -0.1, -1.2 },
    rotation = { 0, 0, 180 },
    width = 0,
    height = 0,
    font_size = 80,
    font_color = colorGreyVector,
  })

  -- Create buttons below the deck tile, stacked vertically
  local startZ = 1.2 -- starting offset below center (local +z = towards players)
  local stepZ = 0.3  -- vertical spacing between buttons
  for i, label in ipairs(modifiers) do
    deckTile.createButton({
      click_function = "doNothing",
      label = label,
      function_owner = self,
      position = { 1, -0.1, startZ + (i - 1) * stepZ },
      rotation = { 0, 0, 180 },
      width = 0,
      height = 0,
      font_size = 150,
      font_color = colorGoldVector,
    })
  end
end

------------------------------------
--- Round Setup (shared boilerplate for all rounds)
--- Handles: nameplates, circles, challenge scan, chip cleanup,
---          Blackout reset, seated players, deck reference.
--- Returns: numPlayers
------------------------------------
function roundSetup(roundNumber)
  -- Commit any admin changes deferred until a round start (light-red "pending"). No control uses
  -- "roundStart" today, but the timing is supported in parallel to the challenge timing flag.
  applyPendingAdminChanges("roundStart")
  scanActiveChallenges()
  applyChallengeEvalFlags() -- re-derive the four live eval flags every round; instant-timed
  -- challenges also apply them on token drop (applyInstantChallengeChange)

  nameVariants = {}   -- clear forced name overrides; real names shown each new round
  nameCycleOrder = {} -- reset admin name-cycle state so each round starts fresh
  nameCycleIndex = {}
  rollNameVariants()  -- 1% chance per seat to show a funny name this round (persisted)
  updateNameplates()
  drawCircles()

  -- Snapshot previous round's chip rankings before chips are cleaned up
  if roundNumber >= 2 then
    snapshotRoundRankings(roundNumber - 1)
  end
  peakChipIndex = {}           -- reset round peaks; new chips will build from scratch
  lowPeakChipIndex = {}
  applyChipSpacePeakLabels({}) -- wipe peak indicators on the chip spaces for the new round
  cleanUpMagic8Balls()         -- discard any active Magic 8 Ball cards at round change

  if roundNumber >= 2 then
    cleanUpChips()
  end


  if roundNumber >= 2 and activeChallenges.BLACKOUT then
    resetChipPosition(roundNumber - 1, getAllChipGUIDsForRound(roundNumber - 1))
  end

  -- Benched mid-game joiners (#19) don't count toward the player total or chip distribution.
  -- (At round 1 no one is benched yet, so this equals the seated count.)
  local seatedPlayers = getActiveParticipants()
  local numPlayers = #seatedPlayers
  if FLAGS.TwoHand then numPlayers = numPlayers * 2 end
  numPlayersStartofRound = numPlayers

  refreshDeckReference()

  updateDeckTileModifiers()

  return numPlayers
end

