-- Deck Preparation
-------------------------------

-- Re-resolves the `deck` global from the deck script zone.
-- Only sets `deck` when exactly one Deck object exists in the zone.
-- If multiple Decks are present (transient state during bag pulls), sets `deck = nil`.
function refreshDeckReference()
  if not scriptZoneDeck then return end
  local foundDeck = nil
  local deckCount = 0
  local cardCount = 0
  local otherCount = 0
  for _, obj in ipairs(scriptZoneDeck.getObjects()) do
    if obj.type == "Deck" then
      foundDeck = obj
      deckCount = deckCount + 1
    elseif obj.type == "Card" then
      cardCount = cardCount + 1
    else
      otherCount = otherCount + 1
    end
  end

  if deckCount == 1 then
    deck = foundDeck
    -- Reposition deck to tile after physics collisions may have displaced it
    if deckTile then
      deck.setPosition(deckTile.getPosition())
      deck.setRotation(deckTile.getRotation())
    end
  elseif deckCount == 0 then
    deck = nil
  else
    deck = nil
  end
end

-- Returns true when the deck in scriptZoneDeck has reached the expected card count
-- and is the only Deck in the zone (i.e. all cards have restacked after cleanup).
function deckReformed()
  if not scriptZoneDeck then return false end
  if not deckExpectedCount or deckExpectedCount <= 0 then return true end

  -- Check: exactly one deck in the zone with all expected Pokercard-tagged cards
  local foundDeck = nil
  local deckCount = 0
  for _, obj in ipairs(scriptZoneDeck.getObjects()) do
    if obj.type == "Deck" then
      foundDeck = obj
      deckCount = deckCount + 1
    end
  end
  if deckCount == 1 and foundDeck then
    local pokercardCount = 0
    local foreignGUIDs = {}
    for _, cardData in ipairs(foundDeck.getObjects()) do
      local isPokercard = false
      if cardData.tags then
        for _, tag in ipairs(cardData.tags) do
          if tag == TAGS.pokercard then
            isPokercard = true; break
          end
        end
      end
      if isPokercard then
        pokercardCount = pokercardCount + 1
      else
        table.insert(foreignGUIDs, cardData.guid)
      end
    end
    -- Eject non-Pokercard objects (tools, etc.) to discard tile
    if #foreignGUIDs > 0 and cardDiscardTileObj then
      local discardPos = cardDiscardTileObj.getPosition()
      for _, guid in ipairs(foreignGUIDs) do
        if not foundDeck.isDestroyed() then
          foundDeck.takeObject({
            guid = guid,
            position = { discardPos.x, discardPos.y + 1, discardPos.z },
            smooth = false,
          })
        end
      end
    end
    if pokercardCount >= deckExpectedCount then
      return true
    end
  end
  return false
end

-- Removes all cards with a given tag from the deck AND loose on the table, destroying them.
-- Two-pass approach for deck: collect GUIDs first, then remove and destroy.
-- Cards are placed far from the deck to prevent physics re-merge before destruction.
-- Also scans loose Card objects in the scene (handles cards missed by cleanUp, e.g. if they
-- were held by a player and not swept back into the deck).
function removeTaggedCardsFromDeck(tag)
  refreshDeckReference()
  if deck then
    -- Pass 1: collect GUIDs of tagged cards inside the deck
    local toRemove = {}
    local cardsInDeck = deck.getObjects()
    for _, card in ipairs(cardsInDeck) do
      if card and card.tags then
        for _, t in ipairs(card.tags) do
          if t == tag then
            table.insert(toRemove, card.guid)
            break
          end
        end
      end
    end

    local deckPos = deck.getPosition()
    -- Pass 2: take each card out and destroy it immediately
    for i, guid in ipairs(toRemove) do
      refreshDeckReference()
      if not deck then break end
      local ok, taken = pcall(function()
        return deck.takeObject({
          guid = guid,
          position = { deckPos.x, deckPos.y + 2 + (i * 0.1), deckPos.z },
          smooth = false,
        })
      end)
      if ok and taken then
        destroyObject(taken)
      end
    end
  end

  -- Also destroy any loose cards with this tag still on the table (not in the deck).
  -- Covers cards that cleanUp couldn't sweep (e.g. held by a player during cleanup).
  for _, obj in ipairs(getAllObjects()) do
    if not obj.isDestroyed() and obj.type == "Card" and obj.hasTag(tag) then
      destroyObject(obj)
    end
  end
end

-- Queues a bag for batch card addition. Call processPendingBags() after all bags are queued.
-- Cards are taken from bags and positioned above the deck in one batch,
-- then physics merges them. Avoids per-card putObject (which triggers TTS card popups).
pendingBagQueue = {}

function addCardsFromBag(bag)
  if bag then
    table.insert(pendingBagQueue, bag)
  end
end

-- Takes all queued bags at once, positioning cards above the deck with matching rotation.
-- All cards land simultaneously so physics merges them in one pass.
function processPendingBags()
  refreshDeckReference()
  if not deck or #pendingBagQueue == 0 then
    pendingBagQueue = {}
    return
  end
  local deckPos = deck.getPosition()
  local deckRot = deck.getRotation()
  for i, bag in ipairs(pendingBagQueue) do
    pcall(function()
      bag.takeObject({
        position = { deckPos.x, deckPos.y + (i * 0.1), deckPos.z },
        rotation = deckRot,
        smooth = false,
      })
    end)
  end
  pendingBagQueue = {}
end

-- Removes all cards from the deck whose value matches the blanked value,
-- placing them face-down on the discard tile. Returns the number of cards removed.
function removeBlankedCardsFromDeck(value)
  refreshDeckReference()
  if not deck or not value or not cardDiscardTileObj then return 0 end

  local discardPos = cardDiscardTileObj.getPosition()
  local discardRot = cardDiscardTileObj.getRotation()
  local removedCount = 0
  local toRemove = {}

  local cardsInDeck = deck.getObjects()
  for _, card in ipairs(cardsInDeck) do
    if card then
      local gmNotes = card.gm_notes or ""
      local cardName = string.match(gmNotes, "^([^\n]+)") or gmNotes
      -- Card format is {suit}{value}, e.g. H5, D5 — check if value portion matches
      local _, cardValue = string.match(cardName, "^(.)(.+)$")
      if cardValue == value then
        table.insert(toRemove, card.guid)
      end
    end
  end

  for i, guid in ipairs(toRemove) do
    refreshDeckReference()
    if not deck then break end
    pcall(function()
      deck.takeObject({
        guid = guid,
        position = { discardPos.x, discardPos.y + 0.5 + (i * 0.2), discardPos.z },
        rotation = { discardRot.x, discardRot.y, 180 },
        smooth = false,
      })
    end)
    removedCount = removedCount + 1
  end

  return removedCount
end

-- Short Deck (6+ Hold'em): pull every 2/3/4/5 (all suits, incl. gear) out of the formed deck
-- to the discard pile, leaving a 36-card 6-A deck. Same mechanism as removeBlankedCardsFromDeck;
-- cleanup sweeps them back each round and round1 re-removes them.
function removeShortDeckCardsFromDeck()
  refreshDeckReference()
  if not deck or not cardDiscardTileObj then return 0 end

  local lowValues = { ["2"] = true, ["3"] = true, ["4"] = true, ["5"] = true }
  local discardPos = cardDiscardTileObj.getPosition()
  local discardRot = cardDiscardTileObj.getRotation()
  local toRemove = {}

  for _, card in ipairs(deck.getObjects()) do
    if card then
      local gmNotes = card.gm_notes or ""
      local cardName = string.match(gmNotes, "^([^\n]+)") or gmNotes
      local _, cardValue = string.match(cardName, "^(.)(.+)$")
      if cardValue and lowValues[cardValue] then
        table.insert(toRemove, card.guid)
      end
    end
  end

  local removedCount = 0
  for i, guid in ipairs(toRemove) do
    refreshDeckReference()
    if not deck then break end
    pcall(function()
      deck.takeObject({
        guid = guid,
        position = { discardPos.x, discardPos.y + 0.5 + (i * 0.2), discardPos.z },
        rotation = { discardRot.x, discardRot.y, 180 },
        smooth = false,
      })
    end)
    removedCount = removedCount + 1
  end

  return removedCount
end

-- Prepares the deck for a new game by adding/removing special cards
-- based on active challenges. Called at the start of round 1.
-- Returns the expected final card count so callers can wait for completion.
function prepareDeck()
  refreshDeckReference()
  if not deck then return 0 end

  -- Challenge 14 (Master Key): wild joker cards
  removeTaggedCardsFromDeck(TAGS.wild)
  local wildCount = activeChallenges.MASTER_KEY or 0
  for i = 1, wildCount do
    addCardsFromBag(bagWildObj)
  end

  -- Challenge 11 (The Joker): replacement joker cards
  removeTaggedCardsFromDeck(TAGS.joker)
  local replaceCount = 2 * (activeChallenges.THE_JOKER or 0)
  for i = 1, replaceCount do
    addCardsFromBag(bagJokerObj)
  end

  -- Challenge 38 (Cluttered Toolbox): blank cards
  removeTaggedCardsFromDeck(TAGS.zero)
  local zeroCount = 0
  if activeChallenges.CLUTTERED_TOOLBOX then
    zeroCount = 4
    addCardsFromBag(bagStandardZeroObj)
  end

  -- Challenge 40 (Extra): B/C/D cards
  removeTaggedCardsFromDeck(TAGS.extra)
  local extraCount = 0
  if activeChallenges.EXTRA_HOURS and isChallengeCompatible("EXTRA_HOURS") then
    extraCount = 12
    addCardsFromBag(bagStandardExtraObj)
    -- If challenge 41 (Grinding Gears) is also active, add gear B/C/D cards
    if activeChallenges.GRINDING_GEARS then
      extraCount = extraCount + 3
      addCardsFromBag(bagGearExtraObj)
    end
  end

  -- Challenge 41 (Grinding Gears): gear suit cards
  removeTaggedCardsFromDeck(TAGS.gear)
  local gearCount = 0
  if activeChallenges.GRINDING_GEARS then
    gearCount = 13 -- 2 through A
    addCardsFromBag(bagGearDeckObj)
    -- If challenge 38 (Cluttered Toolbox) is also active, add gear zero card
    if activeChallenges.CLUTTERED_TOOLBOX then
      gearCount = gearCount + 1
      addCardsFromBag(bagGearZeroObj)
    end
  end

  -- Challenge 42 (Too Many Colors): color-wild (suit-wild, value 0) cards — 2 per token
  removeTaggedCardsFromDeck(TAGS.colorWild)
  local colorWildCount = 2 * (activeChallenges.TOO_MANY_COLORS or 0)
  for i = 1, colorWildCount do
    addCardsFromBag(bagColorWildObj)
  end

  -- Flush all queued bag additions in one batch above the deck
  processPendingBags()

  -- Compute expected total deterministically: 52-card baseline + challenge additions.
  -- This value persists through cleanup for deckReformed() — no scene scanning needed.
  -- Blanked cards are removed from deck but stay Pokercard-tagged, so they count toward the total.
  deckExpectedCount = 52 + wildCount + replaceCount + zeroCount + extraCount + gearCount + colorWildCount

  -- Return expected count for round1's deckReady() wait (cards merging into deck)
  local currentCount = #deck.getObjects()
  return currentCount + wildCount + replaceCount + zeroCount + extraCount + gearCount + colorWildCount
end

