-- Collects card names from a hand object (Player hand or scripting zone).
-- usePlayerHand: if true, uses Player[color].getHandObjects(); otherwise uses handObj.getObjects()
function collectCardsFromHand(handObj, color, usePlayerHand)
  local cards = {}
  if not handObj then return cards end
  local handObjects = usePlayerHand and Player[color].getHandObjects() or handObj.getObjects()
  for _, card in ipairs(handObjects) do
    if (card.hasTag(TAGS.pokercard) or card.hasTag(TAGS.jack)) and not card.hasTag(TAGS.joker) then
      if card.hasTag(TAGS.jack) then
        table.insert(cards, "XJ")
      else
        local cardName, _, _ = parseCardObj(card)
        if cardName ~= "" then
          table.insert(cards, cardName)
        end
      end
    end
  end
  return cards
end

function collectDealtCards()
  dealtCards = {}

  for color, params in pairs(playerParameters) do
    local topCards = collectCardsFromHand(params.topHandObj, color, true)
    local botCards = FLAGS.TwoHand
        and collectCardsFromHand(params.botHandObj, color, false)
        or {}
    -- Night Vision Goggles: card on NVG zone counts as an additional hand card for the activated hand
    local nvData = nightVisionData[color]
    if nvData and nvData.scriptZoneObj and not nvData.scriptZoneObj.isDestroyed() then
      local targetCards = (FLAGS.TwoHand and nvData.hand == "Bot") and botCards or topCards
      for _, obj in ipairs(nvData.scriptZoneObj.getObjects()) do
        if obj.type == "Card" and obj.hasTag(TAGS.pokercard) then
          local cardName = parseCardObj(obj)
          if cardName and cardName ~= "" then
            table.insert(targetCards, cardName)
          end
        end
      end
    end
    dealtCards[color] = {
      ["Top"] = sortCardsByValue(topCards),
      ["Bot"] = sortCardsByValue(botCards),
    }
  end
end

function collectCommunityCards()
  -- Scan community tiles and group cards by column.
  -- Each column can have multiple cards (due to replacement jokers),
  -- but only one card per column can be used for hand evaluation.
  communityCardColumns = {}
  local collectedGuids = {}

  for round, roundData in pairs(communityTileGUIDs) do
    for column, columnData in pairs(roundData) do
      local columnCards = collectCardsFromTileData(columnData, collectedGuids)
      if #columnCards > 0 then
        table.insert(communityCardColumns, columnCards)
      end
    end
  end
end

-- Collects cards from a set of tile data entries (used by both standard and Banana Split modes).
-- Returns an array of card name strings found in the tile's script zones.
function collectCardsFromTileData(tileDataList, collectedGuids)
  local cards = {}
  for _, tileData in ipairs(tileDataList) do
    if tileData.scriptZoneGUID then
      local zoneObj = getObjectFromGUID(tileData.scriptZoneGUID)
      if zoneObj then
        local scriptZoneObjects = zoneObj.getObjects()
        if scriptZoneObjects then
          for _, obj in ipairs(scriptZoneObjects) do
            if obj.type == "Card" and obj.hasTag(TAGS.pokercard) and not collectedGuids[obj.getGUID()] and not obj.hasTag(TAGS.joker) then
              local cardName, _, _ = parseCardObj(obj)
              if cardName ~= "" then
                table.insert(cards, cardName)
                collectedGuids[obj.getGUID()] = true
              end
            elseif obj.type == "Deck" then
              for _, deckCardData in ipairs(obj.getObjects()) do
                if not collectedGuids[deckCardData.guid] then
                  local isJoker = false
                  local isPokercard = false
                  if deckCardData.tags then
                    for _, tag in ipairs(deckCardData.tags) do
                      if tag == TAGS.joker then isJoker = true end
                      if tag == TAGS.pokercard then isPokercard = true end
                    end
                  end
                  if isPokercard and not isJoker then
                    local gmNotes = deckCardData.gm_notes or ""
                    local cardName = string.match(gmNotes, "^([^\n]+)")
                    if cardName and cardName ~= "" then
                      table.insert(cards, cardName)
                      collectedGuids[deckCardData.guid] = true
                    end
                  end
                end
              end
            end
          end
        end
      end
    end
  end
  return cards
end

-- handRankPriority is auto-generated from HAND_RANKS registry (see top of file)

function isRankBetter(rankA, scoreA, rankB, scoreB)
  if not rankA then return false end
  -- If rankA is locked (challenge 37), it cannot be considered better
  if lockedHandRanks[rankA] then return false end
  if not rankB then return true end
  -- If rankB is locked, rankA wins by default (as long as rankA is valid)
  if lockedHandRanks[rankB] then return true end
  local prioA = handRankPriority[rankA] or 0
  local prioB = handRankPriority[rankB] or 0
  if prioA ~= prioB then
    return prioA > prioB
  end
  return (scoreA or 0) > (scoreB or 0)
end

-- Generate all combinations of community cards (one per column)
-- Returns an array of flat card arrays
function getCommunityCardCombinations(columns)
  if not columns or #columns == 0 then
    return { {} }
  end

  local results = {}

  local function buildCombo(colIndex, current)
    if colIndex > #columns then
      table.insert(results, { table.unpack(current) })
      return
    end

    for _, card in ipairs(columns[colIndex]) do
      table.insert(current, card)
      buildCombo(colIndex + 1, current)
      table.remove(current)
    end
  end

  buildCombo(1, {})
  return results
end

function buildCardFingerprint()
  -- Build a string that uniquely represents the current card state
  -- If this string hasn't changed, no recalculation is needed
  local parts = {}
  for color, colorData in pairs(dealtCards) do
    if colorData["Top"] and #colorData["Top"] > 0 then
      table.insert(parts, color .. "M:" .. table.concat(colorData["Top"], ","))
    end
    if colorData["Bot"] and #colorData["Bot"] > 0 then
      table.insert(parts, color .. "O:" .. table.concat(colorData["Bot"], ","))
    end
  end
  -- Add community cards (mode-aware)
  if getGameMode().perPlayer then
    for color, columns in pairs(bananaPlayerCommunityColumns) do
      for i, col in ipairs(columns) do
        table.insert(parts, color .. "C" .. i .. ":" .. table.concat(col, ","))
      end
    end
  else
    for i, col in ipairs(communityCardColumns) do
      table.insert(parts, "C" .. i .. ":" .. table.concat(col, ","))
    end
  end
  -- Add flashlight cards
  for color, data in pairs(flashlightData) do
    if data.scriptZoneObj and not data.scriptZoneObj.isDestroyed() then
      for _, obj in ipairs(data.scriptZoneObj.getObjects()) do
        if obj.type == "Card" and obj.hasTag(TAGS.pokercard) then
          local cardName = parseCardObj(obj)
          if cardName and cardName ~= "" then
            table.insert(parts, color .. "FL:" .. cardName)
          end
        end
      end
    end
  end
  -- Add night vision goggles cards
  for color, data in pairs(nightVisionData) do
    if data.scriptZoneObj and not data.scriptZoneObj.isDestroyed() then
      for _, obj in ipairs(data.scriptZoneObj.getObjects()) do
        if obj.type == "Card" and obj.hasTag(TAGS.pokercard) then
          local cardName = parseCardObj(obj)
          if cardName and cardName ~= "" then
            table.insert(parts, color .. "NV:" .. cardName)
          end
        end
      end
    end
  end
  table.sort(parts) -- deterministic order
  return table.concat(parts, "|")
end

-- Fingerprint of community cards only (used to detect when all players need recalculation).
function buildCommunityFingerprint()
  local parts = {}
  local mode = getGameMode()
  if mode.perPlayer then
    for color, columns in pairs(bananaPlayerCommunityColumns) do
      for i, col in ipairs(columns) do
        table.insert(parts, color .. "C" .. i .. ":" .. table.concat(col, ","))
      end
    end
  else
    for i, col in ipairs(communityCardColumns) do
      table.insert(parts, "C" .. i .. ":" .. table.concat(col, ","))
    end
  end
  table.sort(parts)
  return table.concat(parts, "|")
end

-- Fingerprint of one player's hand cards + their tool-zone extras (flashlight, NVG).
function buildPlayerHandFingerprint(color)
  local parts = {}
  local colorData = dealtCards[color]
  if colorData then
    if colorData["Top"] and #colorData["Top"] > 0 then
      table.insert(parts, "M:" .. table.concat(colorData["Top"], ","))
    end
    if colorData["Bot"] and #colorData["Bot"] > 0 then
      table.insert(parts, "O:" .. table.concat(colorData["Bot"], ","))
    end
  end
  local flashData = flashlightData[color]
  if flashData and flashData.scriptZoneObj and not flashData.scriptZoneObj.isDestroyed() then
    for _, obj in ipairs(flashData.scriptZoneObj.getObjects()) do
      if obj.type == "Card" and obj.hasTag(TAGS.pokercard) then
        local cardName = parseCardObj(obj)
        if cardName and cardName ~= "" then table.insert(parts, "FL:" .. cardName) end
      end
    end
  end
  local nvData = nightVisionData[color]
  if nvData and nvData.scriptZoneObj and not nvData.scriptZoneObj.isDestroyed() then
    for _, obj in ipairs(nvData.scriptZoneObj.getObjects()) do
      if obj.type == "Card" and obj.hasTag(TAGS.pokercard) then
        local cardName = parseCardObj(obj)
        if cardName and cardName ~= "" then table.insert(parts, "NV:" .. cardName) end
      end
    end
  end
  table.sort(parts)
  return table.concat(parts, "|")
end

