-- Evaluates the community board on its own — treating every community card as if it were the
-- player's "hand" (empty community) — and returns the best hand rank display string, recolored
-- grey so it reads as public/board info. Reuses findBestHandRank + the played-card red highlight,
-- then swaps red -> grey (same trick as the Banana Split board-only rendering, getBoardStr).
-- Returns "" when there is no board to show.
-- Texas Hold'em only for now: per-player modes (7-Card Stud / Banana Split) have no single shared
-- board, so there is nowhere sensible to anchor one board label yet — they return "" here.
function getBoardHandRank()
  local mode = getGameMode()
  if mode.perPlayer or mode.perGap then return "" end

  local combos = getCommunityCardCombinations(communityCardColumns)
  local bestRank, bestScore, bestStr = nil, 0, nil
  for _, combo in ipairs(combos) do
    if #combo > 0 then
      local rank, str, score = findBestHandRank(combo, {})
      if isRankBetter(rank, score, bestRank, bestScore) then
        bestRank = rank
        bestScore = score or 0
        bestStr = str
      end
    end
  end

  if not bestStr then return "" end
  -- The board is community, not any player's hand: recolor the played-card highlight red -> grey.
  return (bestStr:gsub(colorToRGBHex("Red"), colorToRGBHex("Grey")))
end

-- Refreshes the board hand-rank label. The button itself is (re)created as deckTile button index 0
-- in updateDeckTileModifiers; here we only update its text as the community cards change. Called
-- from updatehandRankObjects whenever the community fingerprint changes.
function updateBoardHandRankDisplay()
  if not deckTile then return end
  local buttons = deckTile.getButtons()
  if not buttons or #buttons == 0 then return end
  deckTile.editButton({ index = 0, label = getBoardHandRank() })
end

