function getCombinations(cards, count)
  -- Add a new function to generate combinations
  local results = {}
  local function combine(start, combo)
    if #combo == count then
      table.insert(results, { table.unpack(combo) })
      return
    end
    for i = start, #cards do
      table.insert(combo, cards[i])
      combine(i + 1, combo)
      table.remove(combo)
    end
  end
  combine(1, {})
  return results
end

function findBestHandRankOmahaDualForced(handCards, communityCards, card1, card2)
  -- Omaha + both forces: the 2 hand cards are fixed (highest + lowest)
  if #handCards == 0 then
    return nil, nil, 0, {}
  end

  local handCombo
  if card2 and card1 ~= card2 then
    handCombo = { card1, card2 }
  else
    handCombo = { card1 }
  end

  local bestRank, bestStr, bestScore = nil, "", 0
  local bestPlayed = {}
  local bestWilds = {} -- snapshot of gLastWildResolved for the winning combo (Retina vote)

  -- Try all community card counts from 0 to min(3, available)
  for commUseCount = 0, math.min(#communityCards, 3) do
    local communityCombos = commUseCount > 0 and getCombinations(communityCards, commUseCount) or { {} }

    for _, communityCombo in ipairs(communityCombos) do
      local rank, str, score, played = findBestHandRank(handCombo, communityCombo)
      if isRankBetter(rank, score, bestRank, bestScore) then
        bestRank, bestStr, bestScore = rank, str, score
        bestPlayed = played or {}
        bestWilds = gLastWildResolved
      end
    end
  end

  return bestRank, bestStr, bestScore, bestPlayed, bestWilds
end

function findBestHandRankOmahaForced(handCards, communityCards, forcedCard, lowestNonWildValueStr, highestNonWildValueStr)
  -- Omaha + forced card: use exactly 2 from hand (one must be forcedCard), up to 3 from community
  -- lowestNonWildValueStr (optional): value string of the lowest non-wild hand card (e.g. "5").
  -- When set and forced card is a wild:
  --   1. Partner constraint: only allow partners that are wilds or have rank <= lowestNonWildRank
  --   2. Eval constraint: for all-wild combos, pass maxWildValueStr to findBestHandRank
  --      so wilds can only take values <= the lowest non-wild card (preventing them from
  --      exceeding the forced-low value and violating the challenge constraint).
  -- highestNonWildValueStr (optional): value string of the highest non-wild hand card (e.g. "K").
  -- When set and forced card is a wild:
  --   1. No partner constraint (any partner is valid for forced-high).
  --   2. Eval constraint: for all-wild combos, pass minWildValueStr to findBestHandRank
  --      so wilds can only take values >= the highest non-wild card (preventing them from
  --      going below the forced-high value and violating the challenge constraint).
  if #handCards == 0 then
    return nil, nil, 0, {}
  end

  local isForcedWild = string.sub(forcedCard, 1, 1) == "W"
  local maxPartnerRank = lowestNonWildValueStr and getCardValueRank(lowestNonWildValueStr) or nil
  local constrainPartner = isForcedWild and maxPartnerRank

  -- Build hand combos of size 2 that include the forced card
  -- Use forcedSkipped to skip exactly ONE instance of the forced card name
  -- (allows duplicate card names like two "WW" wilds to form a {WW, WW} combo)
  local handCombos = {}
  local forcedSkipped = false
  for _, card in ipairs(handCards) do
    if card == forcedCard and not forcedSkipped then
      forcedSkipped = true
    else
      local include = true
      if constrainPartner then
        local partnerSuit = string.sub(card, 1, 1)
        if partnerSuit ~= "W" then
          local partnerRank = getCardValueRank(string.sub(card, 2))
          if partnerRank > maxPartnerRank then
            include = false
          end
        end
      end
      if include then
        table.insert(handCombos, { forcedCard, card })
      end
    end
  end
  -- If only 1 hand card or all partners filtered out, use forced card alone
  if #handCombos == 0 then
    handCombos = { { forcedCard } }
  end

  local bestRank, bestStr, bestScore = nil, "", 0
  local bestPlayed = {}
  local bestWilds = {} -- snapshot of gLastWildResolved for the winning combo (Retina vote)

  -- Try all community card counts from 0 to min(3, available)
  for commUseCount = 0, math.min(#communityCards, 3) do
    local communityCombos = commUseCount > 0 and getCombinations(communityCards, commUseCount) or { {} }

    for _, handCombo in ipairs(handCombos) do
      -- For all-wild combos, constrain wild values to stay within forced-card bounds
      local evalMaxConstraint = nil
      local evalMinConstraint = nil
      if lowestNonWildValueStr or highestNonWildValueStr then
        local allWild = true
        for _, c in ipairs(handCombo) do
          if string.sub(c, 1, 1) ~= "W" then
            allWild = false; break
          end
        end
        if allWild then
          -- Force challenges judge highest/lowest by REAL card value, but findBestHandRank's wild
          -- bound lives in the active numValue space, which Quantum Chaos (sortNormal=false) inverts.
          -- Force-low (Sleeping Guard): wild real <= lowest hand card — numValue cap normally, floor
          -- reversed. Force-high (All Out Attack): wild real >= highest hand card — floor normally,
          -- cap reversed. (The partner filter above stays on real value and is mode-agnostic.)
          if lowestNonWildValueStr then
            if sortNormal then
              evalMaxConstraint = lowestNonWildValueStr
            else
              evalMinConstraint = lowestNonWildValueStr
            end
          end
          if highestNonWildValueStr then
            if sortNormal then
              evalMinConstraint = highestNonWildValueStr
            else
              evalMaxConstraint = highestNonWildValueStr
            end
          end
        end
      end

      for _, communityCombo in ipairs(communityCombos) do
        local rank, str, score, played = findBestHandRank(handCombo, communityCombo, evalMaxConstraint, evalMinConstraint)
        if isRankBetter(rank, score, bestRank, bestScore) then
          bestRank, bestStr, bestScore = rank, str, score
          bestPlayed = played or {}
          bestWilds = gLastWildResolved
        end
      end
    end
  end

  return bestRank, bestStr, bestScore, bestPlayed, bestWilds
end

function findBestHandRankOmaha(handCards, communityCards)
  -- Omaha: Use up to 2 from hand (minimum 1), up to 3 from community (no minimum)
  if #handCards == 0 then
    return nil, nil, 0, {}
  end

  local handUseCount = math.min(#handCards, 2)
  local handCombos = getCombinations(handCards, handUseCount)

  local bestRank, bestStr, bestScore = nil, "", 0
  local bestPlayed = {}
  local bestWilds = {} -- snapshot of gLastWildResolved for the winning combo (Retina vote)

  -- Try all community card counts from 0 to min(3, available)
  for commUseCount = 0, math.min(#communityCards, 3) do
    local communityCombos = commUseCount > 0 and getCombinations(communityCards, commUseCount) or { {} }

    for _, handCombo in ipairs(handCombos) do
      for _, communityCombo in ipairs(communityCombos) do
        local rank, str, score, played = findBestHandRank(handCombo, communityCombo)
        if isRankBetter(rank, score, bestRank, bestScore) then
          bestRank, bestStr, bestScore = rank, str, score
          bestPlayed = played or {}
          bestWilds = gLastWildResolved
        end
      end
    end
  end

  return bestRank, bestStr, bestScore, bestPlayed, bestWilds
end

