function createhandRankObjects(handRankObj)
  if not handRankObj then return end

  local buttonParams = {
    rotation = { 0, 0, 0 },
    position = Vector(0, 1, 0),
    scale = { 1, 1, 1 },
    font_size = 600,
    click_function = 'updateHandRank',
    width = 0,
