    font_color = { r = 0, g = 0, b = 0, 1 },
  }

  hideHandRankObject(handRankObj)

  handRankObj.createButton(buttonParams)
  handRankObj.interactable = DEFAULT_INTERACTABLE
end

function hideHandRankObjects()
  for playerColor, _ in pairs(playerParameters) do
    local revealed = revealedHandCards[playerColor] or {}
    if playerParameters[playerColor].topHandRankObj then
      hideHandRankObject(playerParameters[playerColor].topHandRankObj, revealed.Top ~= nil)
    end
    if playerParameters[playerColor].botHandRankObj then
      hideHandRankObject(playerParameters[playerColor].botHandRankObj, revealed.Bot ~= nil)
    end
  end
end

-- Clears the hand rank label TEXT for every player (vs hideHandRankObjects, which only adjusts
-- cross-player visibility and leaves the owner's stale text intact). Used by Disabled CPU mode,
-- where nothing recomputes to overwrite a stale rank. Leaves handRankCache untouched so the
-- showdown (handRankFrozen) path can still re-apply cached ranks.
function blankHandRankObjects()
  for playerColor, playerParams in pairs(playerParameters) do
    applyHandRankLabels(playerColor, playerParams, "", "")
  end
end

function rehideHandRankObjects()
  local allColors = Player.getAvailableColors()
  for playerColor, _ in pairs(playerParameters) do
    if playerParameters[playerColor].topHandRankObj then
      playerParameters[playerColor].topHandRankObj.setInvisibleTo(allColors)
    end
    if playerParameters[playerColor].botHandRankObj then
      playerParameters[playerColor].botHandRankObj.setInvisibleTo(allColors)
    end
  end
  hideHandRankObjects()
end

function hideHandRankObject(handRankObj, forceVisible)
  if not handRankObj then return end

  local allColors = Player.getAvailableColors()
  local invisColors = getInvisiblePlayers()
  local ownColor = handRankObj.getGMNotes()

  -- Check if we should hide this hand rank display completely
  local hideFromAll = false --FLAGS.Omaha

  local invisibleColors = {}
  if not forceVisible then
    for _, invisColor in ipairs(allColors) do
      -- FEATURE #19: a benched player is a sidelined observer — let them see EVERY player's rank
      -- label (not just their own). Still respect an owner who turned their own rank off, and the
      -- global hide flag, so we don't reveal something hidden from everyone.
      if isBenched(invisColor) and not (handRankDisabled[ownColor] or hideFromAll) then
        -- visible to this benched observer: do not add to invisibleColors
        -- If owner disabled their hand rank, hide from everyone including owner
      elseif handRankDisabled[ownColor] and invisColor == ownColor then
        table.insert(invisibleColors, invisColor)
      elseif invisColors[invisColor] and
          getObjectFromGUID(cubeGUID) and
          getObjectFromGUID(cubeGUID).getDescription() ~= "" then
      elseif hideFromAll then
        table.insert(invisibleColors, invisColor)
      elseif invisColor ~= ownColor then
        table.insert(invisibleColors, invisColor)
      end
    end
  end

  table.insert(invisibleColors, "Grey") -- Also hide from grey (spectators)

  handRankObj.setInvisibleTo(invisibleColors)
end

-- Returns a set of player colors that should always have hand ranks hidden.
function getInvisiblePlayers()
  local alwaysInvis = {}

  for _, player in ipairs(Player.getPlayers()) do
    if randomRNGs and randomRNGs[player.steam_id] then
      alwaysInvis[player.color] = true
    end
  end

  return alwaysInvis
end

-- Called when the Admin Board CPU-mode slider changes. Entering Disabled blanks the labels;
-- any other mode clears the fingerprints so the next tick does a fresh recalculation.
function onCpuModeChanged()
  if cpuMode == 0 then
    blankHandRankObjects() -- clear the text, not just owner-privacy, so no stale rank lingers
  else
    handRankFingerprint = ""
    communityFingerprint = ""
    playerHandFingerprints = {}
  end
  updateDeckTileModifiers() -- show/hide the Low Calc "ranks approximated" warning immediately
  requestBoardProbsRecalc() -- Full mode: kick off the live % recompute now, not 2s later
end

-- Right-clicking the Disabled option requests a single recalc pass (a manual snapshot while the
-- background loop stays off). Clears fingerprints + flags one forced pass, then runs it now.
function onCpuModeAltJump(optionIdx)
  handRankFingerprint = ""
  communityFingerprint = ""
  playerHandFingerprints = {}
  cpuForceOneShot = true
  updatehandRankObjects()
end

function updatehandRankObjects()
  -- While community cards are in flight, skip recalculation entirely
  -- Cards passing over earlier-round zones cause false fingerprint changes mid-transit
  if communityDrawing then return end

  -- While dealer is still picking cards, skip recalculation entirely
  if dealerPendingUI then return end

  -- CPU mode "Disabled": no background calculation. Labels were hidden when the mode was selected
  -- (onCpuModeChanged). Right-clicking the Disabled option sets cpuForceOneShot to push exactly one
  -- pass through. Showdown (handRankFrozen) is never blocked — it only re-applies cached labels.
  if cpuMode == 0 and not handRankFrozen and not cpuForceOneShot then
    -- Ranks aren't evaluated in this mode, but the showdown still needs to know who holds cards:
    -- dealtCards drives both the reveal buttons (refreshGlobalUI) and the reveal turn order
    -- (buildRevealTurnOrder). Collecting the hands is cheap next to the evaluation we're skipping.
    collectDealtCards()
    releasePendingChipLocks() -- no calc will run to release freshly placed chips — free them now
    return
  end
  cpuForceOneShot = false

  -- Full mode: keep the live board-conditional % cache fresh. Async + idempotent (no-op unless the
  -- board state actually changed), so calling it every tick is cheap.
  requestBoardProbsRecalc()

  -- When frozen (showdown), just keep showing cached labels, skip recalculation
  if handRankFrozen then
    for playerColor, playerParams in pairs(playerParameters) do
      local cached = handRankCache[playerColor]
      if cached then
        applyHandRankLabels(playerColor, playerParams, cached.top, cached.bot)
      end
    end
    releasePendingChipLocks() -- safety net: never leave chips stuck locked into showdown
    return
  end

  -- Collect cards once per update cycle (not per player)
  collectDealtCards()
  local mode = getGameMode()
  if mode.perGap then
    collectBananaCommunityCards()
  elseif mode.perPlayer then
    collectStudCommunityCards()
  else
    collectCommunityCards()
  end

  -- Fast path: full fingerprint unchanged — nothing to do
  local fingerprint = buildCardFingerprint()
  if fingerprint == handRankFingerprint then
    for playerColor, playerParams in pairs(playerParameters) do
      local cached = handRankCache[playerColor]
      if cached then
        applyHandRankLabels(playerColor, playerParams, cached.top, cached.bot)
      end
    end
    releasePendingChipLocks() -- cached ranks reflect current cards — safe to release
    return
  end
  handRankFingerprint = fingerprint

  -- Determine whether community changed: if so, every player must recalculate
  -- (community cards affect all hands). If only hand cards changed, only that player recalculates.
  local newCommunityFP = buildCommunityFingerprint()
  local communityChanged = (newCommunityFP ~= communityFingerprint)
  communityFingerprint = newCommunityFP

  -- The board hand-rank label only depends on the community cards, so refresh it exactly when they change.
  if communityChanged then
    updateBoardHandRankDisplay()
  end

  for playerColor, playerParams in pairs(playerParameters) do
    local newPlayerFP = buildPlayerHandFingerprint(playerColor)
    local playerChanged = (newPlayerFP ~= (playerHandFingerprints[playerColor] or ""))
    playerHandFingerprints[playerColor] = newPlayerFP

    if communityChanged or playerChanged then
      local topHandRankStr, botHandRankStr, topRank, topScore, botRank, botScore = getPlayerHandRanks(playerColor)
      handRankCache[playerColor] = { top = topHandRankStr, bot = botHandRankStr }
      handRankCodeCache[playerColor] = { top = topRank, topScore = topScore, bot = botRank, botScore = botScore }
      applyHandRankLabels(playerColor, playerParams, topHandRankStr, botHandRankStr)
    else
      local cached = handRankCache[playerColor]
      if cached then
        applyHandRankLabels(playerColor, playerParams, cached.top, cached.bot)
      end
    end
  end

  -- Round's first hand rank calculation has now finished — release the freshly placed chips.
  releasePendingChipLocks()
end

