function getHandRankInfoRow(rank, lockedRanks)
  local label = LANG_NOTAGS(rank.label)
  local fontColor = "#FFD94A"
  if (lockedRanks and lockedRanks[rank.code]) then
    label = "X " .. label
    fontColor = "#666666"
  elseif not flushActive and (rank.code == "FL" or rank.code == "SF" or rank.code == "RF") then
    label = "X " .. label
    fontColor = "#666666"
  end
  return label, fontColor
end

-- HAND_RANKS sorted by the live handRankPriority (so Short Deck's FL>FH / 3s>ST reorder is
-- reflected wherever ranks are listed top-to-bottom).
function handRanksByPriority()
  local ordered = {}
  for _, rank in ipairs(HAND_RANKS) do table.insert(ordered, rank) end
  table.sort(ordered, function(a, b)
    return (handRankPriority[a.code] or 0) > (handRankPriority[b.code] or 0)
  end)
  return ordered
end

function buildHandRankInfoXml(color)
  local lockedRanks = lockedHandRanks or {}
  local rows = {}
  for _, rank in ipairs(handRanksByPriority()) do
    local show = rank.code ~= "B0"
    if rank.rainbow and not rainbowActive then show = false end
    if show then
      local label, fontColor = getHandRankInfoRow(rank, lockedRanks)
      table.insert(rows,
        '<Text id="hri_' ..
        color ..
        '_' .. rank.code .. '" fontSize="17" color="' .. fontColor .. '" alignment="MiddleCenter">' .. label .. '</Text>')
    end
  end

  return '<Panel id="handRankInfoPanel_' .. color .. '" visibility="' .. color .. '"'
      .. ' allowDragging="true" returnToOriginalPositionWhenReleased="false"'
      .. ' rectAlignment="MiddleLeft" offsetXY="150 0" width="170" height="380">'
      .. '<Panel color="#000000DD" padding="8 8 8 8">'
      .. '<VerticalLayout spacing="-2" childAlignment="MiddleCenter">'
      .. '<HorizontalLayout spacing="5" preferredHeight="24">'
      .. '<Text fontSize="16" color="#FFD94A" fontStyle="Bold" alignment="MiddleCenter" flexibleWidth="1">Hand Ranks</Text>'
      ..
      '<Button onClick="onHandRankInfoClose" colors="#661111FF|#882222FF|#440000FF|#330000FF" preferredWidth="24" preferredHeight="22">'
      .. '<Text fontSize="14" color="#FF4444" alignment="MiddleCenter">X</Text>'
      .. '</Button></HorizontalLayout>'
      .. table.concat(rows, "\n")
      .. '</VerticalLayout></Panel></Panel>'
end

function updateHandRankInfoContent(color)
  local lockedRanks = lockedHandRanks or {}
  for _, rank in ipairs(HAND_RANKS) do
    local show = rank.code ~= "B0"
    if rank.rainbow and not rainbowActive then show = false end
    if show then
      local label, fontColor = getHandRankInfoRow(rank, lockedRanks)
      local id = "hri_" .. color .. "_" .. rank.code
      UI.setAttribute(id, "text", label)
      UI.setAttribute(id, "color", fontColor)
    end
  end
end

