    createRainbowButton(tokenObj)
  end
end

function onRainbowToggle(obj, playerColor, alt_click)
  rainbowEnabled = not rainbowEnabled
  rainbowActive = activeChallenges.GRINDING_GEARS and rainbowEnabled or false
  rebuildLockedHandRanks()
  refreshRainbowButton()
  updateDeckTileModifiers()
  handRankFingerprint = ""
  communityFingerprint = ""
  playerHandFingerprints = {}
  updatehandRankObjects() -- recalc immediately so rainbow ranks update now, not on the next 2s tick
end

