-------------------------------
ALARM_TOGGLE_CHALLENGE_KEYS = { "QUANTUM_CHAOS", "FOOT_DOOR" }

ALARM_CONFIG = {
  -- rounds: set of round numbers (1-4) in which the alarm flashes for this challenge.
  QUANTUM_CHAOS = { text = STRINGS.ALARM_FLASH_QUANTUM, rounds = { [1] = true, [2] = true, [3] = true, [4] = true } }, -- every round (values stay reversed all game)
  FOOT_DOOR     = { text = STRINGS.ALARM_FLASH_FOOT, rounds = { [1] = true } },                                        -- round 1 only (extra card is dealt pre-flop)
}

ALARM_TOGGLE_IDS = {} -- token GMNotes id -> challenge key, for re-adding the button on zone re-entry
for _, key in ipairs(ALARM_TOGGLE_CHALLENGE_KEYS) do
  ALARM_TOGGLE_IDS[CHALLENGES[key].id] = key
  if reminderAlarmEnabled[key] == nil then reminderAlarmEnabled[key] = true end -- default ON
end

function getReminderAlarmLabel(key)
  local prefix = reminderAlarmEnabled[key] and "[X] " or "[ ] "
  return LANG(STRINGS.TOGGLE_ALARM, prefix)
end

function createReminderAlarmButton(tokenObj, key)
