-- Flash a big center-screen reminder + sound for active forgettable challenges in this round.
-- Called from roundSetup() at the start of every round. No-op when none qualify.
-- Blinks 3 times like the countdown: 0.75s on (with a ping) + 0.25s off, per pulse.
ALARM_FLASH_PULSES     = 3
ALARM_FLASH_ON_TIME    = 0.75
ALARM_FLASH_OFF_TIME   = 0.25
ALARM_TYPE_LETTER_TIME = 0.035 -- per-character speed of the typewriter entrance (first pulse)

function showReminderAlarmFlash(roundNumber)
  local lines = {}
  -- Flash text goes into the XML <Text> overlay → LANG_NOTAGS (no {lang} tags there).
  for _, key in ipairs(ALARM_TOGGLE_CHALLENGE_KEYS) do
    local cfg = ALARM_CONFIG[key]
    if activeChallenges[key] and isChallengeCompatible(key) and reminderAlarmEnabled[key] and cfg and cfg.rounds[roundNumber] then
      table.insert(lines, LANG_NOTAGS(cfg.text))
    end
  end
  if #lines == 0 then return end

  local flashText = table.concat(lines, "\n")
  local totalChars = utf8CharLength(flashText)

  -- One pulse: show the full text + ping, hide after ON_TIME, then chain the next pulse after
  -- OFF_TIME. The bigTextContent guard means we never clobber a countdown (or other overlay)
  -- that may have replaced the big text in the meantime, and we stop pulsing once it's gone.
  local function pulse(n)
    showBigText(flashText)
    --if soundeffect then soundeffect.AssetBundle.playTriggerEffect(0) end
    Wait.time(function()
      if bigTextContent ~= flashText then return end -- something else took over → stop
      hideBigText()
      if n < ALARM_FLASH_PULSES then
        Wait.time(function() pulse(n + 1) end, ALARM_FLASH_OFF_TIME)
      end
    end, ALARM_FLASH_ON_TIME)
  end

  -- Entrance: type the text out one character at a time (quick), then hold it for ON_TIME and
  -- fall into the normal blink loop for the remaining pulses. `prevShown` is the last partial we
  -- pushed; if the overlay no longer matches it, another system took over so we abort the
  -- whole animation. UTF-8-aware so the ⚠ glyph and localized (CJK/Korean) text reveal cleanly.
  local function typeOut(i, prevShown)
    if prevShown and bigTextContent ~= prevShown then return end -- something else took over → stop
    local partial = utf8SubChars(flashText, i)
    showBigText(partial)
    if i == 1 and soundeffect then soundeffect.AssetBundle.playTriggerEffect(0) end
    if i < totalChars then
      Wait.time(function() typeOut(i + 1, partial) end, ALARM_TYPE_LETTER_TIME)
    else
      -- Fully revealed → hold, then continue with the remaining blink pulses.
      Wait.time(function()
        if bigTextContent ~= flashText then return end
        hideBigText()
        if ALARM_FLASH_PULSES > 1 then
          Wait.time(function() pulse(2) end, ALARM_FLASH_OFF_TIME)
        end
      end, ALARM_FLASH_ON_TIME)
    end
  end

  typeOut(1, nil)
end

