-------------------------------
-- Challenge 37: Intricate Lock
-- Displays all hand ranks on the token. Clicking a rank toggles its locked state.
-- Locked ranks cannot be achieved during hand evaluation (via isRankBetter filter).
-------------------------------
-- intricateLockRanks: derived from HAND_RANKS, excluding HC and B0 (not lockable)
intricateLockRanks = {}
for _, rank in ipairs(HAND_RANKS) do
  if rank.code ~= "HC" and rank.code ~= "B0" then
    intricateLockRanks[#intricateLockRanks + 1] = rank
  end
end

-- Returns a set of rank codes that are force-locked by other active challenges.
-- These ranks cannot be unlocked by clicking.
function getForceLockedRanks()
  local forced = {}
  if not flushActive then
    forced["FL"] = true
    forced["SF"] = true
    forced["RF"] = true
  end
  if not rainbowActive then
    forced["RB"] = true
    forced["SR"] = true
  end
  return forced
end

-- Rebuilds lockedHandRanks as the union of userLockedHandRanks and getForceLockedRanks().
-- Must be called whenever either set changes (user click, reset, challenge flag change, cleanUp).
function rebuildLockedHandRanks()
  lockedHandRanks = {}
  for code, _ in pairs(userLockedHandRanks) do
    lockedHandRanks[code] = true
  end
  local forcedLocks = getForceLockedRanks()
  for code, _ in pairs(forcedLocks) do
    lockedHandRanks[code] = true
  end
end

function createIntricateLockButtons()
  local tokenObj = findChallengeToken(CHALLENGES.INTRICATE_LOCK.id)
  if not tokenObj then return end

  -- Rebuild effective locks from user + force sets
  rebuildLockedHandRanks()

  local forcedLocks = getForceLockedRanks()

  tokenObj.clearButtons()

  local baseZ = 1.15
  local btnW, btnH, btnFS = 1400, 200, 180

  -- Reset button at the top
  tokenObj.createButton({
    click_function = "onIntricateLockReset",
    label = LANG(STRINGS.BTN_RESET),
    function_owner = self,
    position = { 0, 0.1, baseZ },
    rotation = { 0, 0, 0 },
    width = btnW,
    height = btnH,
    font_size = btnFS,
    color = { 0.4, 0.1, 0.1 },
    font_color = { 1, 1, 1 },
  })

  local btnIndex = 0
  for _, rankData in ipairs(intricateLockRanks) do
    -- Skip rainbow-only ranks (RB, SR) when Grinding Gears is not active
    if not (rankData.rainbow and not rainbowActive) then
      btnIndex = btnIndex + 1
      local isLocked = lockedHandRanks[rankData.code] or false
      local isForced = forcedLocks[rankData.code] or false
      local isUserLocked = userLockedHandRanks[rankData.code] or false
      local label = isLocked and ("X " .. LANG(rankData.label)) or LANG(rankData.label)
      local fontColor
      if isForced and isUserLocked then
        fontColor = { 0.4, 0.25, 0.25 } -- tinted dark grey for force+user locked
      elseif isForced then
        fontColor = { 0.3, 0.3, 0.3 }   -- darker grey for force-locked only
      elseif isUserLocked then
        fontColor = { 0.5, 0.5, 0.5 }   -- grey for user-locked
      else
        fontColor = colorGoldVector     -- gold for unlocked
      end
      tokenObj.createButton({
        click_function = "onIntricateLock_" .. rankData.code,
        label = label,
        function_owner = self,
        position = { 0, 0.1, baseZ + btnIndex * 0.3 },
        rotation = { 0, 0, 0 },
        width = btnW,
        height = btnH,
        font_size = btnFS,
        color = colorDarkBlueVector,
        font_color = fontColor,
      })
    end
  end
end

-- Generate individual click handlers for each lockable rank code
for _, rankData in ipairs(intricateLockRanks) do
  _G["onIntricateLock_" .. rankData.code] = function(obj, playerColor)
    if not antiTrollClearance(playerColor) then return end
    local code = rankData.code
    -- Prevent unlocking force-locked ranks
    local forcedLocks = getForceLockedRanks()
    if forcedLocks[code] then return end
    -- Toggle in userLockedHandRanks, then rebuild effective locks
    if userLockedHandRanks[code] then
      userLockedHandRanks[code] = nil
    else
      userLockedHandRanks[code] = true
    end
    rebuildLockedHandRanks()
    -- Refresh buttons to show updated state
    createIntricateLockButtons()
    -- Refresh deck tile modifiers to show updated locked ranks
    updateDeckTileModifiers()
    -- Force hand rank recalculation
    handRankFingerprint = ""
    communityFingerprint = ""
    playerHandFingerprints = {}
  end
end

function onIntricateLockReset(obj, playerColor)
  if not antiTrollClearance(playerColor) then return end
  -- Clear all user-locked ranks, then rebuild effective locks (re-applies force-locked ranks)
  userLockedHandRanks = {}
  rebuildLockedHandRanks()
  createIntricateLockButtons()
  updateDeckTileModifiers()
  handRankFingerprint = ""
  communityFingerprint = ""
  playerHandFingerprints = {}
end

