------------------------------------
--- Joker UI Choice System
--- Event-driven joker detection via onObjectEnterZone.
--- Shows a per-player UI letting them pick which replacement card to keep.
------------------------------------
-- Joker UI Choice System globals
jokerQueue = {}                                   -- jokerQueue[color] = { {id=N, card1=obj, card2=obj, card1Name="H6", card2Name="DJ"}, ... }
jokerPendingUI = {}                               -- jokerPendingUI[color] = true if a choice panel is shown for that player
jokerPendingCount = {}                            -- jokerPendingCount[color] = number of takeObject callbacks still pending for this batch
bigTextContent = nil                              -- current big text string (or nil if hidden)
jokerStagingPosition = { x = 0, y = -5, z = -30 } -- hidden off-table position for staging replacement cards
jokerNextEntryId = 0                              -- incrementing counter for stable entry IDs

-- Process a single joker card detected in a player's hand zone
-- Called by onObjectEnterZone (event-driven) or by onJokerCardChosen (when replacement is also a joker)
function processJokerCard(jokerObj, color, handSource)
  if not jokerObj or not color then return false end
  if not playerParameters[color] then return false end
  if not deck then return false end
  if not cardDiscardTileObj then return false end

  -- Return the joker card to the discard pile
  local returnPosition = cardDiscardTileObj.getPosition()
  jokerObj.setPosition({
    x = returnPosition.x,
    y = returnPosition.y + 0.5,
    z = returnPosition.z
  })
  jokerObj.setRotation(cardDiscardTileObj.getRotation())

  -- Initialize the queue for this player
  jokerQueue[color] = jokerQueue[color] or {}
  jokerPendingCount[color] = (jokerPendingCount[color] or 0) + 2

  jokerNextEntryId = jokerNextEntryId + 1
  local stableId = jokerNextEntryId
  local queueEntry = {
    id = stableId,
    source = handSource,
    card1 = nil,
    card2 = nil
  }
  table.insert(jokerQueue[color], queueEntry)

  -- Helper to find entry by stable ID (avoids stale index issues)
  local function findEntryById()
    if not jokerQueue[color] then return nil end
    for i, e in ipairs(jokerQueue[color]) do
      if e.id == stableId then return e end
    end
    return nil
  end

  -- Card 1
  refreshDeckReference()
  if not deck then return end
  deck.takeObject({
    position = { jokerStagingPosition.x - 2, jokerStagingPosition.y, jokerStagingPosition.z - stableId },
    rotation = { 0, 0, 180 },
    smooth = false,
    callback_function = function(card)
      card.interactable = false
      card.locked = true
      local entry = findEntryById()
      if entry then
        entry.card1 = card
      end
      jokerPendingCount[color] = jokerPendingCount[color] - 1
      jokerCheckReady(color)
    end
  })

  -- Card 2
  deck.takeObject({
    position = { jokerStagingPosition.x + 2, jokerStagingPosition.y, jokerStagingPosition.z - stableId },
    rotation = { 0, 0, 180 },
    smooth = false,
    callback_function = function(card)
      card.interactable = false
      card.locked = true
      local cardName = parseCardObj(card)
      local entry = findEntryById()
      if entry then
        entry.card2 = card
      end
      jokerPendingCount[color] = jokerPendingCount[color] - 1
      jokerCheckReady(color)
    end
  })

  broadcastToColor(LANG(STRINGS.MSG_REPLACE_SELECT), color)
  return true
end

-- Called after each takeObject callback; once all cards for a player are spawned, show the first choice UI
function jokerCheckReady(color)
  if jokerPendingCount[color] and jokerPendingCount[color] <= 0 then
    jokerPendingCount[color] = nil
    -- Show UI for the first queued joker
    if jokerQueue[color] and #jokerQueue[color] > 0 then
      showJokerChoiceUI(color)
    end
  end
end

-- Shows the joker choice UI panel for the next queued joker for a player
function showJokerChoiceUI(color)
  if not jokerQueue[color] or #jokerQueue[color] == 0 then
    -- No more jokers to resolve — clean up
    jokerPendingUI[color] = nil
    refreshGlobalUI()
    return
  end

  jokerPendingUI[color] = true
  refreshGlobalUI()
end

-- Builds the XML for ALL of a player's joker choice panels (one per queued joker)
function buildJokerChoiceXml(color)
  if not jokerQueue[color] or #jokerQueue[color] == 0 then return nil end

  local panels = {}
  for i, entry in ipairs(jokerQueue[color]) do
    local card1Text, card1Color = formatCardNameXml(entry.card1)
    local card2Text, card2Color = formatCardNameXml(entry.card2)

    local sourceLabel = entry.source or "Top"
    local headerText = LANG_NOTAGS(STRINGS.XML_REPLACE_HEADER, i, sourceLabel)
    local eid = entry.id
    local totalEntries = #jokerQueue[color]

    -- Layout: 1-2 panels = single column stacked; 3-4 panels = 2×2 grid
    local xOffset, yOffset
    if totalEntries <= 2 then
      -- Single column, centered horizontally
      xOffset = 0
      yOffset = 170 - (i - 1) * 340
    else
      -- 2-column grid: panels 1,2 on left; panels 3,4 on right
      local col = (i <= 2) and -1 or 1
      local row = ((i - 1) % 2) -- 0 or 1
      xOffset = col * 260
      yOffset = 170 - row * 340
    end

    local offsetStr = xOffset .. " " .. yOffset

    local panel = string.format([[
<Panel id="jokerPanel_%s_%d" visibility="%s" allowDragging="true" returnToOriginalPositionWhenReleased="false" rectAlignment="MiddleCenter" width="500" height="320" offsetXY="%s">
  <Panel color="#000000CC" padding="20 20 20 20">
    <VerticalLayout spacing="8" childAlignment="MiddleCenter">
      <Text fontSize="22" color="#FFFF00" alignment="MiddleCenter">%s</Text>
      <HorizontalLayout spacing="30" childAlignment="MiddleCenter" preferredHeight="170">
        <Button id="jokerBtn_%s_%d_1" onClick="onJokerCardChosen" colors="#333333FF|#555555FF|#222222FF|#111111FF" preferredWidth="200" preferredHeight="160">
          <Text fontSize="50" color="%s" alignment="MiddleCenter">%s</Text>
        </Button>
        <Button id="jokerBtn_%s_%d_2" onClick="onJokerCardChosen" colors="#333333FF|#555555FF|#222222FF|#111111FF" preferredWidth="200" preferredHeight="160">
          <Text fontSize="50" color="%s" alignment="MiddleCenter">%s</Text>
        </Button>
      </HorizontalLayout>
      <Button id="jokerRandom_%s_%d" onClick="onJokerRandomChosen" colors="#661111FF|#882222FF|#441111FF|#331111FF" preferredWidth="200" preferredHeight="40">
        <Text fontSize="20" color="#FFDDDD" alignment="MiddleCenter">Random</Text>
      </Button>
    </VerticalLayout>
  </Panel>
</Panel>
]], color, eid, color, offsetStr, headerText, color, eid, card1Color, card1Text, color, eid, card2Color, card2Text,
      color,
      eid)

    table.insert(panels, panel)
  end

  return table.concat(panels, "\n")
end

-- onClick handler for joker choice buttons
-- TTS calls this with: player (Player object), value (string), id (string)
function onJokerCardChosen(player, value, id)
  -- id format: "jokerBtn_Red_5_2" (color, stableEntryId, choice)
  local color, eidStr, choiceStr = string.match(id, "^jokerBtn_(%a+)_(%d+)_(%d+)$")
  if not color or not eidStr or not choiceStr then
    broadcastToAll(LANG(STRINGS.MSG_REPLACE_INVALID, tostring(id)))
    return
  end

  if player.color ~= color then
    broadcastToColor(LANG(STRINGS.MSG_REPLACE_NOT_YOURS), player.color)
    return
  end

  local eid = tonumber(eidStr)
  local choice = tonumber(choiceStr)

  -- Find and remove entry by stable ID
  local entry = nil
  if jokerQueue[color] then
    for i, e in ipairs(jokerQueue[color]) do
      if e.id == eid then
        entry = table.remove(jokerQueue[color], i)
        break
      end
    end
  end

  if not entry then
    broadcastToColor(LANG(STRINGS.MSG_REPLACE_NO_PENDING), color)
    return
  end

  local chosenCard, returnedCard
  if choice == 1 then
    chosenCard = entry.card1
    returnedCard = entry.card2
  else
    chosenCard = entry.card2
    returnedCard = entry.card1
  end

  local chosenCardIsJoker = false
  if chosenCard then
    chosenCard.locked = false
    chosenCard.interactable = true
    chosenCardIsJoker = chosenCard.hasTag(TAGS.joker)

    -- If the chosen card is also a joker, process it through the standard joker flow
    if chosenCardIsJoker and deck then
      processJokerCard(chosenCard, color, entry.source)
    else
      -- Normal card chosen, place into hand
      local targetHandObj
      if entry.source == "Bot" and playerParameters[color].botHandObj then
        targetHandObj = playerParameters[color].botHandObj
      else
        targetHandObj = playerParameters[color].topHandObj
      end
      -- Mark this card so onObjectEnterZone doesn't re-process it as a joker
      jokerProcessedGUIDs[chosenCard.getGUID()] = true
      chosenCard.setPosition(targetHandObj.getPosition())
      chosenCard.setRotation({ 0, 0, 0 })
      chosenCard.highlightOn({ 0, 1, 0 }, 2)
      -- Clear the processed flag after it settles
      Wait.time(function()
        jokerProcessedGUIDs[chosenCard.getGUID()] = nil
      end, 1)
    end
  end

  if returnedCard and cardDiscardTileObj then
    returnedCard.locked = false
    returnedCard.interactable = true
    Wait.time(function()
      returnedCard.setPosition({
        x = cardDiscardTileObj.getPosition().x,
        y = cardDiscardTileObj.getPosition().y + 0.5,
        z = cardDiscardTileObj.getPosition().z
      })
      returnedCard.setRotation({
        x = cardDiscardTileObj.getRotation().x,
        y = cardDiscardTileObj.getRotation().y,
        z = 180
      })
    end, 0.5)
  end

  -- Hide just this panel — other panels stay in place
  UI.hide("jokerPanel_" .. color .. "_" .. eid)

  -- If all done for this player, clean up with a full rebuild
  if not jokerQueue[color] or #jokerQueue[color] == 0 then
    jokerQueue[color] = nil
    jokerPendingUI[color] = nil
    refreshGlobalUI()
    broadcastToColor(LANG(STRINGS.MSG_REPLACE_RESOLVED), color)
    if next(jokerPendingUI) == nil then flushPendingSpecialistActivations() end
  end
end

-- onClick handler for the X close button on the joker choice panel
-- Returns both replacement cards to the deck and clears the current queue entry
-- Returns two positions for dismissed joker cards (card1, card2) for a given player color and slot.
-- In 7CS, community tiles are in front of the player — dismissed cards are placed beyond them (further negative Z).
function getJokerDismissPositions(color, slot)
  local params = playerParameters[color]
  if not params or not params.topChipSpaceObj then return nil, nil end
  local chipSpacePos = params.topChipSpaceObj.getPosition()

  local zBase
  if gameMode == 1 then
    -- 7CS: place beyond the last community tile
    -- Last tile is at namePlatePosition.z + specialModeFirstTileZOffset + (totalColumns - 1) * bananaColumnSpacingZ
    local mode = getGameMode()
    local totalColumns = mode.pocketCards + mode.flopCards + mode.turnCards + mode.riverCards
    local lastTileZ = params.namePlatePosition.z + specialModeFirstTileZOffset +
        (totalColumns - 1) * bananaColumnSpacingZ
    zBase = lastTileZ + jokerOffset.z * slot
  else
    -- Texas Hold'em / Banana Split: original behavior
    zBase = chipSpacePos.z + jokerOffset.z * slot
  end

  local pos1 = {
    x = chipSpacePos.x + jokerOffset.x,
    y = jokerOffset.y,
    z = zBase
  }
  local pos2 = {
    x = chipSpacePos.x - jokerOffset.x,
    y = jokerOffset.y,
    z = zBase
  }
  return pos1, pos2
end

function onJokerChoiceDismiss(player, value, id)
  -- id format: "jokerClose_Red_5" (color, stableEntryId)
  local color, eidStr = string.match(id, "^jokerClose_(%a+)_(%d+)$")
  if not color or not eidStr then return end

  if player.color ~= color then
    broadcastToColor(LANG(STRINGS.MSG_REPLACE_NOT_PANEL), player.color)
    return
  end

  local eid = tonumber(eidStr)

  -- Find and remove entry by stable ID
  local entry = nil
  if jokerQueue[color] then
    for i, e in ipairs(jokerQueue[color]) do
      if e.id == eid then
        entry = table.remove(jokerQueue[color], i)
        break
      end
    end
  end

  if not entry then return end

  -- Lay both cards face-down in front of the player (like the old physical joker flow)
  -- Count how many entries remain + 1 to compute a unique slot for this dismissed entry
  local slot = (#jokerQueue[color] or 0) + 1
  local pos1, pos2 = getJokerDismissPositions(color, slot)

  if pos1 and pos2 then
    if entry.card1 then
      entry.card1.locked = false
      entry.card1.interactable = true
      entry.card1.setPosition(pos1)
      entry.card1.setRotation({ 0, 0, 180 })
    end
    if entry.card2 then
      entry.card2.locked = false
      entry.card2.interactable = true
      entry.card2.setPosition(pos2)
      entry.card2.setRotation({ 0, 0, 180 })
    end

    Player.getPlayers()[1].pingTable(pos1)
  end

  -- Hide just this panel — other panels stay in place
  UI.hide("jokerPanel_" .. color .. "_" .. eid)

  -- If all done for this player, clean up with a full rebuild
  if not jokerQueue[color] or #jokerQueue[color] == 0 then
    jokerQueue[color] = nil
    jokerPendingUI[color] = nil
    refreshGlobalUI()
    broadcastToColor(LANG(STRINGS.MSG_REPLACE_DISMISSED), color)
    if next(jokerPendingUI) == nil then flushPendingSpecialistActivations() end
  end
end

-- Random handler for joker choice: picks one of the two cards at random.
function onJokerRandomChosen(player, value, id)
  -- id format: "jokerRandom_Red_5" (color, stableEntryId)
  local color, eidStr = string.match(id, "^jokerRandom_(%a+)_(%d+)$")
  if not color or not eidStr then return end

  if player.color ~= color then
    broadcastToColor(LANG(STRINGS.MSG_REPLACE_NOT_YOURS), player.color)
    return
  end

  -- Simulate clicking choice 1 or 2 at random
  local choice = math.random(1, 2)
  local fakeId = "jokerBtn_" .. color .. "_" .. eidStr .. "_" .. choice
  onJokerCardChosen(player, value, fakeId)
end

-- Cancel all active joker choice UIs for every player.
-- Unlocks all staged cards and moves them to visible table positions
-- so that cleanUp() can sweep them back into the deck.
function cancelAllJokerChoices()
  local hadAny = false
  for color, entries in pairs(jokerQueue) do
    if entries and #entries > 0 then
      hadAny = true

      for idx, entry in ipairs(entries) do
        local pos1, pos2 = getJokerDismissPositions(color, idx)
        -- Unlock and make interactable so cleanUp can find them
        if entry.card1 then
          entry.card1.locked = false
          entry.card1.interactable = true
          if pos1 then
            entry.card1.setPosition(pos1)
            entry.card1.setRotation({ 0, 0, 180 })
          end
        end
        if entry.card2 then
          entry.card2.locked = false
          entry.card2.interactable = true
          if pos2 then
            entry.card2.setPosition(pos2)
            entry.card2.setRotation({ 0, 0, 180 })
          end
        end
      end
    end
  end

  -- Clear all joker state
  jokerQueue = {}
  jokerPendingUI = {}
  jokerPendingCount = {}
  jokerNextEntryId = 0
  jokerProcessedGUIDs = {}
  toolProcessedGUIDs = {}
  -- Rebuild UI to remove all panels
  if hadAny then
    refreshGlobalUI()
  end
end

