--- Dealer Mode
------------------------------------

-- Staging position for dealer cards (off to the side, at table level, face-down)
local dealerStagingBasePos = { x = 13, y = 1, z = -5 }

-- Main entry point for dealer card drawing.
-- Counts tiles for the given round, draws N+1 cards to staging, then shows the dealer choice UI.
-- onComplete is called after the dealer finishes choosing.
function dealerDrawCards(roundNumber, onComplete)
  if not dealerColor then
    if onComplete then onComplete() end
    return
  end

  -- Flatten all tiles for this round that don't yet have a card
  dealerTargetTiles = {}
  if communityTileGUIDs[roundNumber] then
    for column, columnData in pairs(communityTileGUIDs[roundNumber]) do
      for _, tileData in ipairs(columnData) do
        if not tileData.card then
          table.insert(dealerTargetTiles, { round = roundNumber, column = column, tileData = tileData })
        end
      end
    end
  end

  local N = #dealerTargetTiles
  if N == 0 then
    if onComplete then onComplete() end
    return
  end

  dealerChosenCount = 0
  dealerExpectedChoices = N
  dealerOnComplete = onComplete
  dealerStagedCards = {}

  -- Draw N+1 cards to staging area
  local totalDraw = N + 1
  refreshDeckReference()
  if not deck then
    if onComplete then onComplete() end
    return
  end

  for i = 1, totalDraw do
    local stagingPos = { dealerStagingBasePos.x + (i - 1) * 2.5, dealerStagingBasePos.y, dealerStagingBasePos.z }
    local drawnCard = deck.takeObject({
      position = stagingPos,
      rotation = { 0, 0, 180 },
      smooth = true
    })
    if drawnCard then
      drawnCard.setLock(true)
      table.insert(dealerStagedCards, drawnCard)
    end
    refreshDeckReference()
    if not deck then break end
  end

  dealerStagedCardCount = #dealerStagedCards

  -- Wait a moment for cards to settle, then handle jokers and show UI
  Wait.time(function()
    dealerHandleStagedJokers(function()
      showDealerChoiceUI(dealerColor)
    end)
  end, 0.5)
end

-- Scans dealerStagedCards for Jokers. For each Joker found, draws 2 replacement cards
-- and stores them in dealerJokerReplacements[slotIndex]. The Joker card object stays in the
-- slot (used for display reference) until the dealer picks a replacement via the UI.
-- If no jokers found, calls onReady immediately.
function dealerHandleStagedJokers(onReady)
  dealerJokerReplacements = {}
  local foundJoker = false
  for i = 1, dealerStagedCardCount do
    local card = dealerStagedCards[i]
    if card and card.getGMNotes() == "Joker" then
      foundJoker = true
      refreshDeckReference()
      if deck then
        local replacements = {}
        for r = 1, 2 do
          local stagingPos = { dealerStagingBasePos.x + (dealerStagedCardCount + r) * 2.5, dealerStagingBasePos.y,
            dealerStagingBasePos.z }
          local newCard = deck.takeObject({
            position = stagingPos,
            rotation = { 0, 0, 180 },
            smooth = true
          })
          if newCard then
            newCard.setLock(true)
            table.insert(replacements, newCard)
          end
          refreshDeckReference()
          if not deck then break end
        end
        dealerJokerReplacements[i] = replacements
      end
    end
  end
  if onReady then onReady() end
end

-- Shows the dealer choice UI panel for the given color.
function showDealerChoiceUI(color)
  dealerPendingUI = color
  refreshGlobalUI()
  if dealerHasPendingJokers() then
    broadcastToColor(LANG(STRINGS.MSG_DEALER_RESOLVE_FIRST), color, { 1, 1, 0 })
  else
    broadcastToColor(LANG(STRINGS.MSG_DEALER_CHOOSE, dealerExpectedChoices), color, { 1, 1, 0 })
  end
end

-- Returns true if there are unresolved joker replacement choices pending.
function dealerHasPendingJokers()
  for _, _ in pairs(dealerJokerReplacements) do
    return true
  end
  return false
end

-- Builds the XML panel for the dealer card choice UI.
-- Two phases: 1) Joker resolution (if any jokers staged), 2) Normal card selection.
function buildDealerChoiceXml(color)
  if not color or not dealerStagedCardCount or dealerStagedCardCount == 0 then return nil end

  local roundLabel = LANG_NOTAGS(STRINGS.XML_DEALER_ROUND, dealerTargetTiles[1] and dealerTargetTiles[1].round or "?")
  local totalCards = dealerStagedCardCount
  local jokersRemaining = dealerHasPendingJokers()

  -- Header and progress text
  local expected = dealerExpectedChoices or 0
  local chosen = dealerChosenCount or 0
  local headerText, progressText
  if jokersRemaining then
    local jokerCount = 0
    for _, _ in pairs(dealerJokerReplacements) do jokerCount = jokerCount + 1 end
    headerText = LANG_NOTAGS(STRINGS.XML_DEALER_RESOLVE_HEADER, jokerCount > 1 and "s" or "")
    progressText = LANG_NOTAGS(STRINGS.XML_DEALER_PROGRESS_REPLACE, jokerCount, jokerCount > 1 and "s" or "", roundLabel)
  else
    headerText = LANG_NOTAGS(STRINGS.XML_DEALER_SELECT_HEADER, expected, expected > 1 and "s" or "")
    progressText = LANG_NOTAGS(STRINGS.XML_DEALER_PROGRESS, chosen, expected, roundLabel)
  end

  -- Build card buttons
  local cardButtons = {}
  local panelHeight = jokersRemaining and 320 or 380

  for i = 1, totalCards do
    local card = dealerStagedCards[i]
    local jokerPair = dealerJokerReplacements[i]

    if jokerPair and #jokerPair == 2 and jokerPair[1] and not jokerPair[1].isDestroyed() and jokerPair[2] and not jokerPair[2].isDestroyed() then
      local text1, col1 = formatCardNameXml(jokerPair[1])
      local text2, col2 = formatCardNameXml(jokerPair[2])
      table.insert(cardButtons,
        '<VerticalLayout spacing="5" preferredWidth="160">' ..
        '<Text fontSize="14" color="#DDDDDD" alignment="MiddleCenter">Replace</Text>' ..
        '<Button id="dealerJkr_' ..
        color ..
        '_' ..
        i ..
        '_1" onClick="onDealerJokerChosen" colors="#333333FF|#555555FF|#222222FF|#111111FF" preferredWidth="160" preferredHeight="75">' ..
        '<Text fontSize="32" color="' .. col1 .. '" alignment="MiddleCenter">' .. text1 .. '</Text></Button>' ..
        '<Button id="dealerJkr_' ..
        color ..
        '_' ..
        i ..
        '_2" onClick="onDealerJokerChosen" colors="#333333FF|#555555FF|#222222FF|#111111FF" preferredWidth="160" preferredHeight="75">' ..
        '<Text fontSize="32" color="' .. col2 .. '" alignment="MiddleCenter">' .. text2 .. '</Text></Button>' ..
        '</VerticalLayout>'
      )
      panelHeight = 400
    elseif card and not card.isDestroyed() then
      local displayText, hexColor = formatCardNameXml(card)
      if jokersRemaining then
        table.insert(cardButtons,
          '<Button colors="#222222FF|#222222FF|#222222FF|#222222FF" preferredWidth="140" preferredHeight="160">' ..
          '<Text fontSize="50" color="' .. hexColor .. '" alignment="MiddleCenter">' .. displayText .. '</Text></Button>'
        )
      else
        table.insert(cardButtons,
          '<Button id="dealerBtn_' ..
          color ..
          '_' ..
          i ..
          '" onClick="onDealerCardChosen" colors="#333333FF|#555555FF|#222222FF|#111111FF" preferredWidth="140" preferredHeight="160">' ..
          '<Text fontSize="50" color="' .. hexColor .. '" alignment="MiddleCenter">' .. displayText .. '</Text></Button>'
        )
      end
    else
      table.insert(cardButtons,
        '<Button colors="#111111FF|#111111FF|#111111FF|#111111FF" preferredWidth="140" preferredHeight="160">' ..
        '<Text fontSize="50" color="#333333" alignment="MiddleCenter">-</Text></Button>'
      )
    end
  end

  -- Assemble panel XML via concatenation
  local panelWidth = math.max(500, totalCards * 155 + 40)
  local parts = {}
  table.insert(parts, '<Panel id="dealerPanel_' .. color .. '" visibility="' .. color .. '"'
    .. ' allowDragging="true" returnToOriginalPositionWhenReleased="false"'
    .. ' rectAlignment="MiddleCenter" width="' .. panelWidth .. '" height="' .. panelHeight .. '"'
    .. ' offsetXY="0 200">')
  table.insert(parts, '<Panel color="#000000CC" padding="20 20 20 20">')
  table.insert(parts, '<VerticalLayout spacing="8" childAlignment="MiddleCenter">')
  table.insert(parts, '<Text fontSize="22" color="#FFFF00" alignment="MiddleCenter">' .. headerText .. '</Text>')
  table.insert(parts, '<HorizontalLayout spacing="10" childAlignment="MiddleCenter" preferredHeight="190">')
  table.insert(parts, table.concat(cardButtons, "\n"))
  table.insert(parts, '</HorizontalLayout>')
  table.insert(parts, '<Text fontSize="18" color="#AAAAAA" alignment="MiddleCenter">' .. progressText .. '</Text>')
  if not jokersRemaining then
    table.insert(parts, '<Button id="dealerRandom_' .. color .. '" onClick="onDealerRandomChosen"'
      .. ' colors="#661111FF|#882222FF|#441111FF|#331111FF" preferredWidth="200" preferredHeight="50">'
      .. '<Text fontSize="20" color="#FFDDDD" alignment="MiddleCenter">Random</Text></Button>')
  end
  table.insert(parts, '</VerticalLayout>')
  table.insert(parts, '</Panel>')
  table.insert(parts, '</Panel>')

  return table.concat(parts, "\n")
end

-- Click handler for dealer card choice buttons.
function onDealerCardChosen(player, value, id)
  -- id format: "dealerBtn_Red_3"
  local color, indexStr = string.match(id, "^dealerBtn_(%a+)_(%d+)$")
  if not color or not indexStr then return end

  if player.color ~= dealerColor then
    broadcastToColor(LANG(STRINGS.MSG_DEALER_ONLY_DEALER), player.color)
    return
  end

  -- Block during joker resolution phase
  if dealerHasPendingJokers() then
    broadcastToColor(LANG(STRINGS.MSG_DEALER_RESOLVE_ALL), player.color)
    return
  end

  local cardIndex = tonumber(indexStr)
  if not cardIndex or not dealerStagedCards[cardIndex] then
    broadcastToColor(LANG(STRINGS.MSG_DEALER_UNAVAILABLE), player.color)
    return
  end

  -- Find the next target tile
  dealerChosenCount = dealerChosenCount + 1
  local target = dealerTargetTiles[dealerChosenCount]
  if not target then return end

  local card = dealerStagedCards[cardIndex]
  local tileObj = getObjectFromGUID(target.tileData.guid)

  -- Move card to the tile position (like communityDrawCard)
  if tileObj then
    local tilePosition = tileObj.getPosition()
    local tileRotation = tileObj.getRotation()
    card.setLock(false)
    card.setPosition({ tilePosition.x, tilePosition.y + 2, tilePosition.z })
    card.setRotation({ 0, tileRotation.y, 0 })
  end
  target.tileData.card = card

  -- Mark as used
  dealerStagedCards[cardIndex] = nil

  -- Check if all choices made
  if dealerChosenCount >= dealerExpectedChoices then
    -- Discard remaining staged cards
    for idx = 1, dealerStagedCardCount do
      local remainingCard = dealerStagedCards[idx]
      if remainingCard then
        remainingCard.setLock(false)
        if cardDiscardTileObj then
          local discardPos = cardDiscardTileObj.getPosition()
          remainingCard.setPosition({ discardPos.x, discardPos.y + 0.5, discardPos.z })
          remainingCard.setRotation({ 0, 0, 180 })
        end
      end
    end

    -- Move dealer chip to next player after all choices are made
    moveDealerChip(dealerColor)

    -- Clean up state and call completion
    local onComplete = dealerOnComplete
    dealerPendingUI = nil
    dealerStagedCards = {}
    dealerTargetTiles = {}
    dealerJokerReplacements = {}
    dealerOnComplete = nil
    refreshGlobalUI()

    if onComplete then
      Wait.time(function() onComplete() end, 0.3)
    end
  else
    -- Rebuild UI to show progress
    refreshGlobalUI()
  end
end

-- Click handler for dealer random selection button.
function onDealerRandomChosen(player, value, id)
  local color = string.match(id, "^dealerRandom_(%a+)$")
  if not color then return end

  if player.color ~= dealerColor then
    broadcastToColor(LANG(STRINGS.MSG_DEALER_ONLY_DEALER), player.color)
    return
  end

  if dealerHasPendingJokers() then
    broadcastToColor(LANG(STRINGS.MSG_DEALER_RESOLVE_ALL), player.color)
    return
  end

  -- Collect remaining available card indices
  local available = {}
  for i = 1, dealerStagedCardCount do
    if dealerStagedCards[i] then
      table.insert(available, i)
    end
  end

  -- Shuffle available indices
  for i = #available, 2, -1 do
    local j = math.random(i)
    available[i], available[j] = available[j], available[i]
  end

  -- Pick cards for remaining targets
  while dealerChosenCount < dealerExpectedChoices and #available > 0 do
    local cardIndex = table.remove(available, 1)
    dealerChosenCount = dealerChosenCount + 1
    local target = dealerTargetTiles[dealerChosenCount]
    if not target then break end

    local card = dealerStagedCards[cardIndex]
    local tileObj = getObjectFromGUID(target.tileData.guid)
    if tileObj then
      local tilePosition = tileObj.getPosition()
      local tileRotation = tileObj.getRotation()
      card.setLock(false)
      card.setPosition({ tilePosition.x, tilePosition.y + 2, tilePosition.z })
      card.setRotation({ 0, tileRotation.y, 0 })
    end
    target.tileData.card = card
    dealerStagedCards[cardIndex] = nil
  end

  -- Discard remaining staged cards
  for idx = 1, dealerStagedCardCount do
    local remainingCard = dealerStagedCards[idx]
    if remainingCard then
      remainingCard.setLock(false)
      if cardDiscardTileObj then
        local discardPos = cardDiscardTileObj.getPosition()
        remainingCard.setPosition({ discardPos.x, discardPos.y + 0.5, discardPos.z })
        remainingCard.setRotation({ 0, 0, 180 })
      end
    end
  end

  -- Move dealer chip to next player
  moveDealerChip(dealerColor)

  -- Clean up state and call completion
  local onComplete = dealerOnComplete
  dealerPendingUI = nil
  dealerStagedCards = {}
  dealerTargetTiles = {}
  dealerJokerReplacements = {}
  dealerOnComplete = nil
  refreshGlobalUI()

  if onComplete then
    Wait.time(function() onComplete() end, 0.3)
  end
end

-- Click handler for dealer joker replacement buttons.
-- id format: "dealerJkr_Red_3_1" (color, slotIndex, choice 1 or 2)
function onDealerJokerChosen(player, value, id)
  local color, slotStr, choiceStr = string.match(id, "^dealerJkr_(%a+)_(%d+)_(%d+)$")
  if not color or not slotStr or not choiceStr then return end

  if player.color ~= dealerColor then
    broadcastToColor(LANG(STRINGS.MSG_DEALER_ONLY_DEALER), player.color)
    return
  end

  local slotIndex = tonumber(slotStr)
  local choice = tonumber(choiceStr)
  local pair = dealerJokerReplacements[slotIndex]
  if not pair or #pair ~= 2 then return end

  local chosenCard = pair[choice]
  local discardedCard = pair[choice == 1 and 2 or 1]

  -- Discard the joker card from the staged slot
  local jokerCard = dealerStagedCards[slotIndex]
  if jokerCard then
    jokerCard.setLock(false)
    if cardDiscardTileObj then
      local discardPos = cardDiscardTileObj.getPosition()
      jokerCard.setPosition({ discardPos.x, discardPos.y + 0.5, discardPos.z })
      jokerCard.setRotation({ 0, 0, 180 })
    end
  end

  -- Discard the unchosen replacement card
  if discardedCard then
    discardedCard.setLock(false)
    if cardDiscardTileObj then
      local discardPos = cardDiscardTileObj.getPosition()
      discardedCard.setPosition({ discardPos.x, discardPos.y + 0.5, discardPos.z })
      discardedCard.setRotation({ 0, 0, 180 })
    end
  end

  -- Replace the slot with the chosen card
  dealerStagedCards[slotIndex] = chosenCard
  dealerJokerReplacements[slotIndex] = nil

  -- Check if the chosen card is also a joker — if so, draw 2 new replacements
  if chosenCard and chosenCard.getGMNotes() == "Joker" then
    refreshDeckReference()
    if deck then
      local replacements = {}
      for r = 1, 2 do
        local stagingPos = { dealerStagingBasePos.x + (dealerStagedCardCount + r) * 2.5, dealerStagingBasePos.y,
          dealerStagingBasePos.z }
        local newCard = deck.takeObject({
          position = stagingPos,
          rotation = { 0, 0, 180 },
          smooth = true
        })
        if newCard then
          newCard.setLock(true)
          table.insert(replacements, newCard)
        end
        refreshDeckReference()
        if not deck then break end
      end
      dealerJokerReplacements[slotIndex] = replacements
    end
  end

  refreshGlobalUI()
end

-- Emergency cleanup: discard all staged cards, reset state. Called from cleanUp().
function cancelDealerChoice()
  for idx = 1, dealerStagedCardCount do
    local card = dealerStagedCards[idx]
    if card then
      card.setLock(false)
      if cardDiscardTileObj then
        local discardPos = cardDiscardTileObj.getPosition()
        card.setPosition({ discardPos.x, discardPos.y + 0.5, discardPos.z })
        card.setRotation({ 0, 0, 180 })
      end
    end
  end
  -- Also discard any pending joker replacement cards
  for _, pair in pairs(dealerJokerReplacements) do
    for _, card in ipairs(pair) do
      if card then
        card.setLock(false)
        if cardDiscardTileObj then
          local discardPos = cardDiscardTileObj.getPosition()
          card.setPosition({ discardPos.x, discardPos.y + 0.5, discardPos.z })
          card.setRotation({ 0, 0, 180 })
        end
      end
    end
  end
  dealerPendingUI = nil
  dealerStagedCards = {}
  dealerTargetTiles = {}
  dealerChosenCount = 0
  dealerExpectedChoices = 0
  dealerStagedCardCount = 0
  dealerJokerReplacements = {}
  dealerOnComplete = nil
end

-- Returns true if a dealer choice panel is currently active.
function hasActiveDealerPanel()
  return dealerPendingUI ~= nil
end

function countJQKInCommunity(communityRound, playerColor)
  local count = 0

  local function countInRoundData(roundData)
    if not roundData then return end
    for _, columnData in pairs(roundData) do
      for _, tileData in ipairs(columnData) do
        if tileData.card and tileData.card.isDestroyed() then tileData.card = nil end
        if tileData.card then
          local _, _, cardValue = parseCardObj(tileData.card)
          if cardValue == "J" or cardValue == "Q" or cardValue == "K" then
            count = count + 1
          end
        end
      end
    end
  end

  local mode = getGameMode()
  if mode.perGap and playerColor then
    -- Banana Split: scan this player's two adjacent gaps
    local gaps = bananaGapsByPlayer[playerColor]
    if gaps then
      if gaps.leftGapIndex and bananaGapTileGUIDs[gaps.leftGapIndex] then
        countInRoundData(bananaGapTileGUIDs[gaps.leftGapIndex][communityRound])
      end
      if gaps.rightGapIndex and bananaGapTileGUIDs[gaps.rightGapIndex] then
        countInRoundData(bananaGapTileGUIDs[gaps.rightGapIndex][communityRound])
      end
    end
  elseif mode.perPlayer and playerColor then
    -- 7-Card Stud: scan this player's tiles
    if studTileGUIDs[playerColor] then
      countInRoundData(studTileGUIDs[playerColor][communityRound])
    end
  else
    -- Standard: scan central board (shared by all players)
    countInRoundData(communityTileGUIDs[communityRound])
  end

  return count
end

function cleanUp()
  cleanUpFlashlights()
  cleanUpNightVision()
  cleanUpMagic8Balls()
  pendingSpecialistActivations = {}
  discardedChipSpaces = {}
  -- Reset accuracy producer (safety net if a game is abandoned before showdown push).
  accuracyGameId = nil
  accuracyRounds = {}
  accuracyPlayers = {}
  removeVoteReopenButtons() -- clear the "Reopen Vote" token button if present
  challengeVoteState = nil  -- close any open challenge-voting panel
  refreshGlobalUI()
  refreshStatsBookFaces()   -- showdown over / game reset → now safe to update the book leaderboard
  cleanUpMathWiz()
  cleanUpInvestor()
  cleanUpBackdoorKey()
  cancelAllJokerChoices()
  cancelDealerChoice()
  dealerColor = nil
  setChipSpaceSnapPoints()        -- restore snap points on chip spaces
  handRankFrozen = false          -- unfreeze hand rank calculation
  chipsAwaitingHandRank = false   -- clear pending chip-lock release state
  pendingChipUnlockGUIDs = {}
  uiCurrentSnapshot = "__dirty__" -- force full UI rebuild on next refreshGlobalUI
  sortNormal = true               -- reset reversed card values
  flushActive = true              -- reset flush visibility
  shortDeck = false               -- reset Short Deck (2-5 removal + rank reorder)
  applyShortDeckRankOrder()       -- restore canonical hand-rank order
  forceHighCard = false           -- reset forced card challenges
  forceLowCard = false
  extendedValues = false          -- reset extended card values
  blankedValue = nil              -- reset blanked card value
  lilOmaha = false                -- reset lil omaha rule
  lilOmahaTriggered = false       -- reset lil omaha trigger state
  rainbowActive = false           -- reset rainbow hand rank
  balanceApplied = false          -- reset balance round1 flag
  -- NOTE: userLockedHandRanks is NOT reset here — user locks persist across rounds within a full game.
  -- Use the manual reset button on the challenge 37 token to clear user locks.
  rebuildLockedHandRanks()     -- rebuild force-locks from reset flags (rainbow/flush)
  activeChallenges = {}        -- clear cached challenge lookups
  refreshValueChart()          -- redraw the value chart back to the normal (reset) order
  rankingHistory = {}          -- clear notepad ranking history
  peakChipIndex = {}           -- clear peak chip tracking
  lowPeakChipIndex = {}
  applyChipSpacePeakLabels({}) -- wipe peak indicators on the chip spaces
  chipHandRankSnapshot = {}    -- clear per-chip hand rank snapshots
  chipPositionSnapshot = {}    -- clear per-chip position snapshots
  chipZoneOwner = {}           -- clear chip zone ownership
  chipDraggedBy = {}           -- clear chip drag tracking
  refreshChipStampMenus(nil)   -- strip Stamp context menus from all chips between games
  for guid, _ in pairs(chipHintActive) do
    local chipObj = getObjectFromGUID(guid)
    if chipObj then chipObj.clearButtons() end
  end
  chipHintActive = {}
  nameVariants = {}                               -- clear forced name overrides
  nameCycleOrder = {}                             -- reset admin name-cycle state
  nameCycleIndex = {}
  revealedHandCards = {}                          -- clear revealed hand cards tracking
  rehideHandRankObjects()                         -- re-apply normal visibility after showdown reveals
  if cpuMode == 0 then blankHandRankObjects() end -- Disabled mode: clear stale showdown ranks on reset
  playedHandCards = {}                            -- clear played hand cards tracking
  revealHandPendingConfirm = {}                   -- clear reveal confirm state
  revealLockPressCount = {}                       -- clear reveal-lock backdoor press counts
  revealLockBypass = false                        -- clear override bypass flag
  revealPreTrigger = {}                           -- clear queued early reveals
  revealTurnOrder = {}                            -- clear showdown reveal order
  revealCurrentTurn = 1                           -- reset reveal turn index
  revealOverridePendingConfirm = 0                -- reset host override confirm state
  revealHandRankResults = {}                      -- clear showdown reveal comparison results
  backdoorKeyActivated = {}                       -- clear backdoor key activations
  handRankCodeCache = {}                          -- clear rank code cache
  studTileGUIDs = {}                              -- clear stud tile data
  bananaGapTileGUIDs = {}                         -- clear banana split tile data
  bananaPlayerCommunityColumns = {}
  communityCardColumns = {}                       -- clear last game's board so the next round1 doesn't evaluate a phantom
  -- (stale) board in getBoardHandRank before collectCommunityCards rebuilds it from real cards
  bananaGaps = {}
  bananaGapsByPlayer = {}
  bananaWrapMirrorTiles = {}
  setNotes("") -- clear the notepad
  round = 0

  local allObjects = getAllObjects()

  -- deckExpectedCount is set deterministically in prepareDeck() (52 + challenge additions).
  -- No need to recount here — it persists across rounds.

  -- Reset deck tile and related objects to default position BEFORE placing cards back
  positionDeckAndRelatedTiles(deckTileBasePosition)

  local deckPosition = { 0, 0, 0 }
  local deckRotation = { 0, 0, 0 }
  if deckTile then
    deckPosition = deckTile.getPosition()
    deckRotation = deckTile.getRotation()
  end

  -- Phase 1: Collect all Pokercard objects for merging.
  -- Uses putObject API instead of physics-based stacking to avoid
  -- tower collapse → multiple decks and rotation mismatch → double-back cards.
  local looseCards = {}
  local deckObjects = {}

  for _, obj in ipairs(allObjects) do
    if not obj.isDestroyed() then
      if obj.type == "Card" and obj.hasTag(TAGS.pokercard) and not obj.held_by_color then
        obj.setLock(false)
        table.insert(looseCards, obj)
      elseif obj.type == "Deck" then
        if obj.hasTag(TAGS.pokercard) then
          obj.setLock(false)
          table.insert(deckObjects, obj)
        else
          -- Extract Pokercard cards trapped inside non-tagged decks
          local guidsToExtract = {}
          for _, cardData in ipairs(obj.getObjects()) do
            local isPokercard = false
            if cardData.tags then
              for _, tag in ipairs(cardData.tags) do
                if tag == TAGS.pokercard then
                  isPokercard = true; break
                end
              end
            end
            if isPokercard then table.insert(guidsToExtract, cardData.guid) end
          end
          for _, guid in ipairs(guidsToExtract) do
            if not obj.isDestroyed() then
              local taken = obj.takeObject({ guid = guid, smooth = false })
              if taken then
                taken.setLock(false)
                table.insert(looseCards, taken)
              end
            end
          end
        end
      end
    end
  end

  -- Phase 2: Pick the largest Pokercard deck as target; merge all others into it via putObject.
  -- putObject is an API merge (instant, no physics) — prevents rotation and stacking bugs.
  table.sort(deckObjects, function(a, b)
    if a.isDestroyed() then return false end
    if b.isDestroyed() then return true end
    return #a.getObjects() > #b.getObjects()
  end)

  local targetDeck = nil
  for _, d in ipairs(deckObjects) do
    if not d.isDestroyed() then
      targetDeck = d
      break
    end
  end

  if targetDeck then
    -- Position target deck at deck tile
    targetDeck.setPosition({ deckPosition.x, deckPosition.y + 1, deckPosition.z })
    targetDeck.setRotation(deckRotation)

    -- Merge other Pokercard decks into target (putObject absorbs entire decks)
    for i = 2, #deckObjects do
      local d = deckObjects[i]
      if d and not d.isDestroyed() and d ~= targetDeck then
        d.setRotation(deckRotation)
        targetDeck.putObject(d)
      end
    end

    -- Merge loose Pokercard cards into target
    for _, card in ipairs(looseCards) do
      if card and not card.isDestroyed() then
        card.setRotation(deckRotation)
        targetDeck.putObject(card)
      end
    end

    deck = targetDeck
  elseif #looseCards >= 2 then
    -- No existing deck — place two cards at deck position, let TTS form a deck,
    -- then merge the rest via putObject after a short physics settle.
    local card1 = looseCards[1]
    local card2 = looseCards[2]
    card1.setRotation(deckRotation)
    card1.setPosition({ deckPosition.x, deckPosition.y + 1, deckPosition.z })
    card2.setRotation(deckRotation)
    card2.setPosition({ deckPosition.x, deckPosition.y + 1.2, deckPosition.z })

    Wait.time(function()
      refreshDeckReference()
      if deck then
        for i = 3, #looseCards do
          local card = looseCards[i]
          if card and not card.isDestroyed() then
            card.setRotation(deckRotation)
            deck.putObject(card)
          end
        end
      end
    end, 1.0)
  elseif #looseCards == 1 then
    looseCards[1].setRotation(deckRotation)
    looseCards[1].setPosition({ deckPosition.x, deckPosition.y + 1, deckPosition.z })
  end

  -- Phase 3: Safety net — catch any stragglers that were in flight during Phase 1-2.
  -- Runs a few times with delays to handle edge cases (cards mid-animation, etc.)
  local safetyAttempts = 0
  local function mergeStragglers()
    safetyAttempts = safetyAttempts + 1
    if safetyAttempts > 15 then return end
    if not scriptZoneDeck then return end

    local target = nil
    local targetSize = 0
    local stragglers = {}

    for _, obj in ipairs(scriptZoneDeck.getObjects()) do
      if not obj.isDestroyed() then
        if obj.type == "Deck" and obj.hasTag(TAGS.pokercard) then
          local size = #obj.getObjects()
          if size > targetSize then
            if target then table.insert(stragglers, target) end
            target = obj
            targetSize = size
          else
            table.insert(stragglers, obj)
          end
        elseif obj.type == "Card" and obj.hasTag(TAGS.pokercard) then
          table.insert(stragglers, obj)
        end
      end
    end

    if target and #stragglers > 0 then
      for _, obj in ipairs(stragglers) do
        if not obj.isDestroyed() then
          if obj.type == "Card" then obj.setRotation(deckRotation) end
          target.putObject(obj)
        end
      end
      Wait.time(mergeStragglers, 0.5)
    elseif target then
      deck = target
    end
  end

  Wait.time(mergeStragglers, 2.0)

  communityCleanUp()

  -- Reset all chips (regular + zero) per round in a single call so y-indices don't overlap
  for chipRound = 1, 4 do
    resetChipPosition(chipRound, getAllChipGUIDsForRound(chipRound))
  end
  -- Reset exit chips: stack them ABOVE the round-4 chips already placed in the same column
  -- (start index past the round-4 count) so they don't land at the same heights and collide.
  resetChipPosition(4, exitChipGUIDs, #getAllChipGUIDsForRound(4) + 1)
  -- Reset dealer chip if not in a player zone
  resetDealerChipPosition()

  challengeReminderHandRankObj.clearButtons()
  challengeReminderNumberObj.clearButtons()
  challengeReminderHandRankPlayerObj.clearButtons()
  challengeReminderNumberPlayerObj.clearButtons()
  -- Clear deck tile modifier display
  if deckTile then
    deckTile.clearButtons()
    deckTile.setSnapPoints({
      {
        position = { 0, 0, 0 },
        rotation = { 0, 0, 0 },
        rotation_snap = true
      }
    })
  end
  -- Clear blanked value button from challenge 38 token
  local clutteredToolboxObj = findChallengeToken(CHALLENGES.CLUTTERED_TOOLBOX.id)
  if clutteredToolboxObj then clutteredToolboxObj.clearButtons() end
  -- Clear incompatibility "X" marks from any suppressed challenge tokens (#14)
  removeIncompatibleChallengeXMarks()
  -- FEATURE #19: un-bench every seat and clear the roster — the next heist starts with no one benched
  clearAllBenchMarks()
  heistRoster = {}
  -- Refresh challenge 37 buttons (update auto-locked ranks from challenge flags, but keep user locks)
  if findChallengeToken(CHALLENGES.INTRICATE_LOCK.id) then
    createIntricateLockButtons()
  end
  numPlayersStartofRound = 0
  refreshGlobalUI() -- clear showdown UI (reveal hand button)
  unlockButtons()
end

