local countdownActive = false
local countdownTimer = 0
local countdownID = nil

function onButtonRoundClick(obj, playerColor)
  if not antiTrollClearance(playerColor) then return end

  -- Block round advancement while dealer is choosing cards
  if hasActiveDealerPanel() then
    broadcastToAll(LANG(STRINGS.MSG_DEALER_WAITING))
    return
  end

  if round == 1 then
    if buttonLocked then
      broadcastToAll(LANG(STRINGS.MSG_WAIT))
      return
    end
    local seatedCount = #getSeatedPlayers()
    -- 2Hand: max 5 players
    if FLAGS.TwoHand and seatedCount > 5 then
      broadcastToAll(LANG(STRINGS.MSG_2HAND_MAX))
      return
    end
    -- Short Deck: max 4 HANDS (players, or players × 2 in 2Hand). A 36-card deck can't supply
    -- enough cards once a hand can hold up to 5 (Omaha 4 + Security Camera) plus the community.
    if FLAGS.ShortDeck and (seatedCount * (FLAGS.TwoHand and 2 or 1)) > 4 then
      broadcastToAll(LANG(STRINGS.MSG_SHORTDECK_MAX))
      return
    end
    -- 7CS/Banana Split: max 6 players
    if gameMode ~= 0 and seatedCount > 6 then
      broadcastToAll(LANG(STRINGS.MSG_MODE_MAX, GAME_MODES[gameMode].label))
      return
    end
    -- Omaha + 7CS/Banana Split: max 6 players
    if gameMode ~= 0 and FLAGS.Omaha and seatedCount > 6 then
      broadcastToAll(LANG(STRINGS.MSG_OMAHA_MODE_MAX, GAME_MODES[gameMode].label))
      return
    end
    updateRoundButton(LANG(STRINGS.BTN_START_ROUND, 2), { 1, 1, 0, 1 }, { 0, 0, 0, 1 })
    lockButtons()
    round1()
  elseif round == 2 then
    if buttonLocked then
      broadcastToAll(LANG(STRINGS.MSG_WAIT))
      return
    else
      updateRoundButton(LANG(STRINGS.BTN_START_ROUND, 3), { 1, 0.5, 0, 1 }, { 0, 0, 0, 1 })
      lockButtons()
      round2()
    end
  elseif round == 3 then
    if buttonLocked then
      broadcastToAll(LANG(STRINGS.MSG_WAIT))
      return
    else
      updateRoundButton(LANG(STRINGS.BTN_START_ROUND, 4), { 1, 0, 0, 1 }, { 1, 1, 1, 1 })
      lockButtons()
      round3()
    end
  elseif round == 4 then
    if buttonLocked then
      broadcastToAll(LANG(STRINGS.MSG_WAIT))
      return
    else
      updateRoundButton(LANG(STRINGS.BTN_SHOWDOWN), { 0.5, 0, 1, 1 }, { 1, 1, 1, 1 })
      lockButtons()
      round4()
    end
  elseif round == 5 then
    if buttonLocked then
      return
    else
      cancelCountdown()
      updateRoundButton(LANG(STRINGS.BTN_CLEAN_UP), { 0, 0, 1, 1 }, { 1, 1, 1, 1 })
      broadcastToAll(LANG(STRINGS.MSG_SHOW_HAND))
      snapshotChipHandRanks(4)
      scoreAccuracyRound(4) -- score the decisive round, then push the finished game record
      finalizeAccuracyGame()
      handRankFrozen = true
      buildRevealTurnOrder()
      clearChipSpaceSnapPoints()
      snapshotRoundRankings(4)
      lastSpecialVault2 = nil
      updateNotepadRankings() -- also clears peak labels because handRankFrozen
      refreshGlobalUI()
    end
  elseif round >= 6 then
    if buttonLocked then
      return
    else
      updateRoundButton(LANG(STRINGS.BTN_START_ROUND, 1), { 1, 1, 1, 1 }, { 0, 0, 0, 1 })
      lockButtons()
      cleanUp()
    end
    round = 1
    if FLAGS.Automode then
      lockButtons()
      Wait.condition(
        function() NEXTROUND() end,
        function() return deckReformed() end,
        10,
        function() NEXTROUND() end -- timeout fallback
      )
      scheduleSafeUnlock(24)
    end
    return
  end
  round = round + 1

  if FLAGS.Automode then
    updateChipsOnPlayers()
  end
end

function onButtonResetClick(obj, playerColor)
  if not antiTrollClearance(playerColor) then return end


  if buttonLocked then
    broadcastToAll(LANG(STRINGS.MSG_WAIT))
    return
  end

  cleanUp() -- Triggers your existing cleanup function
  updateRoundButton(LANG(STRINGS.BTN_START_ROUND, 1), { 1, 1, 1, 1 }, { 0, 0, 0, 1 })

  round = 1

  if FLAGS.Automode then
    lockButtons()
    Wait.condition(
      function() NEXTROUND() end,
      function() return deckReformed() end,
      10,
      function() NEXTROUND() end -- timeout fallback
    )
    scheduleSafeUnlock(24)
  end
end

-- "Reset Free Chips": send any chip that's drifted out of all zones (off the table, physics
-- knocks, etc.) back to its supply position via the round-start cleanup, then re-evaluate
-- the automode threshold once the chips settle.
function onResetFreeChipsClick(obj, playerColor)
  if not antiTrollClearance(playerColor) then return end
  cleanUpChips()
  broadcastToAll(LANG(STRINGS.BTN_RESET_FREE_CHIPS), colorGoldVector)
  Wait.time(function()
    updateChipsOnPlayers()
    updateNotepadRankings()
  end, 1)
end

function startCountdown()
  if round < 6 then
    cancelCountdown()
    countdownActive = true
    if round == 1 then
      countdownTimer = 1
    elseif round ~= 1 then
      countdownTimer = 4
    end
    displayCountdown()
  end
end

function displayCountdown()
  if countdownActive and countdownTimer == 4 then
    countdownTimer = countdownTimer - 1
    countdownID = Wait.time(displayCountdown, 1)
  elseif countdownActive and countdownTimer > 0 then
    if round ~= 1 then
      showBigText(tostring(countdownTimer))
      if countdownTimer < 4 then soundeffect.AssetBundle.playTriggerEffect(1) end
    end
    countdownTimer = countdownTimer - 1
    countdownID = Wait.time(displayCountdown, 1)
  elseif countdownActive and countdownTimer == 0 then
    countdownActive = false
    hideBigText()
    soundeffect.AssetBundle.playTriggerEffect(2)
    NEXTROUND()
  end
end

function cancelCountdown()
  if countdownActive then
    countdownActive = false
    countdownTimer = 0

    if countdownID ~= nil then
      Wait.stop(countdownID)
      countdownID = nil
    end
    hideBigText()
  end
end

function NEXTROUND()
  if round == 1 then
    updateRoundButton(LANG(STRINGS.BTN_START_ROUND, 2), { 1, 1, 0, 1 }, { 0, 0, 0, 1 })
    lockButtons()
    round1()
    round = round + 1
  elseif round == 2 then
    updateRoundButton(LANG(STRINGS.BTN_START_ROUND, 3), { 1, 0.5, 0, 1 }, { 0, 0, 0, 1 })
    lockButtons()
    round2()
    round = round + 1
    lastSpecialVault2 = nil
  elseif round == 3 then
    updateRoundButton(LANG(STRINGS.BTN_START_ROUND, 4), { 1, 0, 0, 1 }, { 1, 1, 1, 1 })
    lockButtons()
    round3()
    round = round + 1
    lastSpecialVault2 = nil
  elseif round == 4 then
    updateRoundButton(LANG(STRINGS.BTN_SHOWDOWN), { 0.5, 0, 1, 1 }, { 1, 1, 1, 1 })
    lockButtons()
    round4()
    round = round + 1
    lastSpecialVault2 = nil
  elseif round == 5 then
    updateRoundButton(LANG(STRINGS.BTN_CLEAN_UP), { 0, 0, 1, 1 }, { 1, 1, 1, 1 })
    broadcastToAll(LANG(STRINGS.MSG_SHOW_HAND))
    snapshotChipHandRanks(4)
    scoreAccuracyRound(4)      -- score the decisive round, then push the finished game record
    finalizeAccuracyGame()
    handRankFrozen = true      -- freeze hand rank display during showdown
    buildRevealTurnOrder()
    clearChipSpaceSnapPoints() -- remove snap points so cards don't stick
    snapshotRoundRankings(4)   -- snapshot final round rankings at showdown
    round = round + 1
    lastSpecialVault2 = nil
    updateNotepadRankings()
    refreshGlobalUI() -- show reveal hand button
  end

  if FLAGS.Automode then
    updateChipsOnPlayers()
  end
end

------------------------------------
--- SECTION 18: Reveal Hand (Showdown)
------------------------------------

------------------------------------
--- Reveal Hand (Showdown)
--- Reveals cards from a player's hand by shifting them in front of their chip space.
--- Keeps each card's original X/Y position, only changes Z.
--- Cards that are part of the best hand ("played") get extra Z offset (stickOut).
------------------------------------

function onRevealHandClick(player, value, id)
  if not handRankFrozen then return end -- only during showdown

  local color = player.color
  if color == "Grey" or color == "Black" then return end -- spectators cannot reveal
  local params = playerParameters[color]
  if not params then return end

  -- Normalize waiting button ids to canonical ids so all downstream logic is uniform
  if id == "revealHandBtnTopWaiting" then id = "revealHandBtnTop" end
  if id == "revealHandBtnBotWaiting" then id = "revealHandBtnBot" end
  if id == "revealHandBtnWaiting" then id = "revealHandBtn" end

  local revealedSource = FLAGS.TwoHand and (id == "revealHandBtnTop" and "Top" or "Bot") or "Top"

  -- If not this player's turn yet, queue the reveal and return.
  -- The pre-trigger fires automatically when their turn is reached.
  local currentEntry = revealTurnOrder[revealCurrentTurn]
  local isMyTurn = currentEntry and currentEntry.color == color and currentEntry.hand == revealedSource
  if not isMyTurn then
    if not (revealedHandCards[color] and revealedHandCards[color][revealedSource]) then
      revealPreTrigger[color .. revealedSource] = { player = player, id = id }
    end
    return
  end

  -- Scan Challenges (Retina / Fingerprint) reveal handling for the leader hand. Runs in all
  -- modes: the double-confirm always applies; only the vote (mode 0) and the reveal lock
  -- (mode 1) are mode-specific, so Unscripted (mode 2) keeps just the double-confirm.
  if activeChallenges.RETINA_SCAN or activeChallenges.FINGERPRINT_SCAN then
    -- Determine which hand source this button targets
    local source = "Top"
    if id == "revealHandBtnBot" then source = "Bot" end

    -- The "leader" is the highest NON-EXITED hand (an exited top player bailed → shift down).
    local ranked = scanNonExitChipRankings()
    local needsConfirm = false
    if ranked[1] and ranked[1].color == color and ranked[1].hand == source then
      needsConfirm = true
    end

    -- Challenge Voting (Vote UI mode only): when the top-chip hand's reveal turn is reached,
    -- OPEN the vote instead of revealing. The hand can't be revealed until every vote is closed.
    -- EXCEPTION: if the heist is already lost from the hands revealed so far, the vote is
    -- moot — don't force it. Offer a manual "Open Vote" button on the token and let the
    -- reveal proceed as normal (the team can still run the vote for practice if they want).
    local heistLostSkipConfirm = false
    if needsConfirm and scanChallengeMode == 0 then
      if not challengeVoteState then
        if challengeVoteHeistAlreadyLost() then
          createVoteReopenButtons() -- manual "Open Vote" button; fall through to normal reveal
          -- Heist already lost: the vote never opens, so the "remember the challenges"
          -- double-confirm guard is also moot — let the leader reveal on a single click.
          heistLostSkipConfirm = true
        else
          openChallengeVote() -- first attempt at the top reveal → start the team vote
          return
        end
      elseif not challengeVoteAllClosed() then
        broadcastToColor(LANG(STRINGS.MSG_VOTE_BEFORE_REVEAL), color, colorGoldVector)
        return
      end
    end

    if needsConfirm and not heistLostSkipConfirm then
      local confirmKey = color .. "|" .. (id or "")
      if not revealHandPendingConfirm[confirmKey] then
        -- First click: change button text to a warning and require a confirming click
        revealHandPendingConfirm[confirmKey] = true
        revealLockPressCount[confirmKey] = 1
        -- Change button text to warning (map button id -> text element id)
        local textId = ({ revealHandBtnTop = "revealHandTxtTop", revealHandBtnBot = "revealHandTxtBot", revealHandBtn = "revealHandTxt" })
            [id]
        if textId then
          UI.setAttribute(textId, "text", LANG_NOTAGS(STRINGS.MSG_REMEMBER_CHALLENGES))
          UI.setAttribute(textId, "color", "#FF4444")
        end
        -- In Lock Reveal mode, tell the player the host controls the reveal (gold).
        -- The silent 10-press backdoor below is intentionally not advertised.
        if scanChallengeMode == 1 and not revealLockBypass then
          broadcastToColor(LANG(STRINGS.MSG_REVEAL_LOCKED), color, colorGoldVector)
        end
        return
      end

      -- Lock Reveal mode (highest-chip hand only): the normal second click no longer reveals —
      -- the host/promoted is meant to reveal via the override button. As a silent backdoor (e.g.
      -- no host present), 10 total presses force the reveal; presses 2–9 give no feedback and the
      -- warning button text persists.
      if scanChallengeMode == 1 and not revealLockBypass then
        local pressCount = (revealLockPressCount[confirmKey] or 1) + 1
        revealLockPressCount[confirmKey] = pressCount
        if pressCount < 10 then return end
      end
    end
  end

  -- Determine which hand(s) to reveal based on button id
  local handsToReveal = {}
  if FLAGS.TwoHand then
    -- Two separate buttons: "revealHandBtnTop" / "revealHandBtnBot"
    if id == "revealHandBtnTop" then
      if params.topHandObj then
        table.insert(handsToReveal,
          { handObj = params.topHandObj, chipSpaceObj = params.topChipSpaceObj, source = "Top" })
      end
    elseif id == "revealHandBtnBot" then
      if params.botHandObj then
        table.insert(handsToReveal,
          { handObj = params.botHandObj, chipSpaceObj = params.botChipSpaceObj, source = "Bot" })
      end
    end
  else
    -- Single button: reveal the main hand
    if params.topHandObj then
      table.insert(handsToReveal, { handObj = params.topHandObj, chipSpaceObj = params.topChipSpaceObj, source = "Top" })
    end
  end

  if #handsToReveal == 0 then return end

  -- Initialize tracking table if needed
  if not revealedHandCards[color] then
    revealedHandCards[color] = {}
  end

  -- Get chip space position for Z reference
  local chipSpaceObj = params.topChipSpaceObj
  if not chipSpaceObj then return end
  local chipPos = chipSpaceObj.getPosition()

  for _, handInfo in ipairs(handsToReveal) do
    -- Skip if this specific hand is already revealed
    if revealedHandCards[color][handInfo.source] then return end

    local handObj = handInfo.handObj
    if not handObj then return end

    -- Get cards from this hand (only Pokercard-tagged cards)
    local cards = {}
    for _, obj in ipairs(handObj.getObjects()) do
      if obj.type == "Card" and (obj.hasTag(TAGS.pokercard) or obj.hasTag(TAGS.jack)) then
        table.insert(cards, obj)
      end
    end

    if #cards == 0 then return end

    -- Top hand reveal is just above the hand rank display
    -- Bot hand reveal is right on the nameplate
    local baseZ = playerParameters[color].namePlatePosition.z + playerChipSpacePositionOffset.z +
        playerHandRankPositionOffset.z + revealHandOffset.zOffset
    if FLAGS.TwoHand then
      if handInfo.source == "Top" then
        baseZ = baseZ + playerChipSpacePositionOffset.z
      else
        baseZ = playerParameters[color].namePlatePosition.z + revealHandOffset.zOffset / 2
      end
    end

    -- Get played hand cards from evaluation
    -- playedList is either a flat list {"H7", "SK"} or structured { group = {"H7"}, kicker = {"SK"} }
    local playedRaw = {}
    if playedHandCards[color] then
      playedRaw = playedHandCards[color][handInfo.source] or {}
    end
    -- Build count tables: groupCounts for group cards, kickerCounts for kicker cards
    local groupCounts = {}
    local kickerCounts = {}
    if playedRaw.group then
      -- Structured: separate group and kicker cards
      for _, cn in ipairs(playedRaw.group) do
        groupCounts[cn] = (groupCounts[cn] or 0) + 1
      end
      for _, cn in ipairs(playedRaw.kicker or {}) do
        kickerCounts[cn] = (kickerCounts[cn] or 0) + 1
      end
    else
      -- Flat list: all cards are group cards (straights, flushes, full houses, etc.)
      for _, cn in ipairs(playedRaw) do
        groupCounts[cn] = (groupCounts[cn] or 0) + 1
      end
    end

    local revealedCards = {}
    for _, card in ipairs(cards) do
      local cardPos = card.getPosition()
      local cardRot = card.getRotation()
      local cardName, _, _ = parseCardObj(card)
      if card.hasTag(TAGS.jack) then cardName = "XJ" end

      -- Check if this card is "played" (part of the best hand) and whether it's a group or kicker card
      local cardOffset = 0
      if groupCounts[cardName] and groupCounts[cardName] > 0 then
        cardOffset = revealHandOffset.stickOut
        groupCounts[cardName] = groupCounts[cardName] - 1
      elseif kickerCounts[cardName] and kickerCounts[cardName] > 0 then
        cardOffset = revealHandOffset.kickerOffset
        kickerCounts[cardName] = kickerCounts[cardName] - 1
      end

      -- Keep X/Y, only change Z
      local targetZ = baseZ + cardOffset

      card.setPosition({ x = cardPos.x, y = cardPos.y, z = targetZ }, false, true)
      card.setPositionSmooth({ x = cardPos.x, y = cardPos.y + 0.5, z = targetZ }, false, true)
      card.setRotation({ 0, cardRot.y, 0 }) -- face-up
      table.insert(revealedCards, card)
    end
    revealedHandCards[color][handInfo.source] = revealedCards
  end
  hideHandRankObjects()

  -- Advance turn (we only reach here when it is this player's turn)
  revealCurrentTurn = revealCurrentTurn + 1

  -- Update showdown comparison results and notepad
  updateShowdownResults()
  updateNotepadRankings()

  -- Auto-fire next entry if they pre-triggered early
  local nextEntry = revealTurnOrder[revealCurrentTurn]
  local nextPreFired = false
  if nextEntry then
    local preKey = nextEntry.color .. nextEntry.hand
    local pre = revealPreTrigger[preKey]
    if pre then
      revealPreTrigger[preKey] = nil
      nextPreFired = true
      Wait.time(function() onRevealHandClick(pre.player, nil, pre.id) end, 0.75)
    end
  end

  -- Challenge Voting (Vote UI mode only): the moment the reveal order reaches the top-chip
  -- hand, open the team vote automatically (it gates that final reveal). Skipped if a pre-
  -- trigger is already about to open it via onRevealHandClick. If the heist is already lost
  -- from the hands revealed so far, the vote is moot — don't auto-open; offer a manual
  -- "Open Vote" button on the token instead.
  if nextEntry and not nextPreFired and not challengeVoteState and scanChallengeMode == 0
      and (activeChallenges.RETINA_SCAN or activeChallenges.FINGERPRINT_SCAN) then
    local ranked = scanNonExitChipRankings()
    if ranked[1] and ranked[1].color == nextEntry.color and ranked[1].hand == nextEntry.hand then
      if challengeVoteHeistAlreadyLost() then
        createVoteReopenButtons() -- manual "Open Vote" button; the final reveal proceeds normally
      else
        openChallengeVote()
      end
    end
  end

  -- Full rebuild: updates active/waiting button states for all remaining players
  uiCurrentSnapshot = "__dirty__"
  refreshGlobalUI()
end

-- Host/promoted override: reveal the current turn player's hand on their behalf.
-- First click enters confirm state (button label changes); second click executes.
-- Confirm state expires automatically when the turn advances (different revealCurrentTurn index).
function onRevealOverrideClick(player, value, id)
  if not handRankFrozen then return end
  local p = Player[player.color]
  if not p or not (p.promoted or p.host) then return end

  local currentEntry = revealTurnOrder[revealCurrentTurn]
  if not currentEntry then return end

  -- First click: show confirmation prompt
  if revealOverridePendingConfirm ~= revealCurrentTurn then
    revealOverridePendingConfirm = revealCurrentTurn
    local targetHex              = "#" .. colorToRGBHex(currentEntry.color)
    local targetName             = getPlayerDisplayName(currentEntry.color)
    UI.setAttribute("revealOverrideTxt", "text", LANG_NOTAGS(STRINGS.MSG_REVEAL_OVERRIDE_SURE, targetName))
    UI.setAttribute("revealOverrideTxt", "color", targetHex)
    -- Change button background to orange-warning tint
    UI.setAttribute("revealOverrideBtn", "colors", "#553300FF|#774400FF|#331100FF|#553300FF")
    return
  end

  -- Second click: pre-clear the Retina/Fingerprint confirm so the override bypasses it,
  -- then trigger reveal on behalf of the current turn player.
  local hand                                                   = currentEntry.hand
  local btnId                                                  = FLAGS.TwoHand and
      (hand == "Top" and "revealHandBtnTop" or "revealHandBtnBot") or "revealHandBtn"
  revealHandPendingConfirm[currentEntry.color .. "|" .. btnId] = true
  revealOverridePendingConfirm                                 = 0
  -- Bypass the Reveal Lock for the override path (already host/promoted-gated above).
  revealLockBypass                                             = true
  onRevealHandClick({ color = currentEntry.color }, nil, btnId)
  revealLockBypass = false
end

