function onChat(message, player)
  -- TEST trigger for the Challenge Voting panel (slice 1). Remove once wired into showdown.
  if string.sub(message, 1, 6) == "!cvote" then
    local arg = string.lower(string.match(message, "^!cvote%s+(%a+)") or "")
    if arg == "close" then
      closeChallengeVote()
    elseif arg == "f" then
      openChallengeVote({ "fingerprint" })
    elseif arg == "r" then
      openChallengeVote({ "retina" })
    elseif arg == "both" then
      openChallengeVote({ "fingerprint", "retina" })
    else
      openChallengeVote() -- whichever challenges are active
    end
    return false
  end
  if not randomCheck(player) then return end
  return processRNG(message, player)
end

function onPlayerChangeColor(color)
  -- Hand rank is ON by default for seated players (each can hide their own via the nameplate);
  -- just clear any stale state for now-empty seats.
  for seatColor, _ in pairs(playerParameters) do
    if not isPlayerSeated(seatColor) then
      handRankDisabled[seatColor] = nil
    end
  end

  -- FEATURE #19: bench mid-game joiners / un-bench seat-switchers BEFORE the count + displays
  -- below, so a benched seat is already excluded from everything that follows.
  reevaluateBenchedSeats()

  updateNameplates()
  drawCircles()
  hideHandRankObjects()
  updateNotepadRankings()
  -- Refresh automode player count so chip threshold stays correct when players join/leave
  -- Skip round 4: new players sitting down before showdown should not change the threshold
  if FLAGS.Automode and round >= 1 and round < 4 then
    refreshActivePlayerCount()
  end
  updateChipsOnPlayers()
end

function onPlayerDisconnect(player)
  reevaluateBenchedSeats() -- FEATURE #19: drop bench flag/X from a seat a benched joiner just left
  updateNameplates()
  drawCircles()
  hideHandRankObjects()
  updateNotepadRankings()
  updateChipsOnPlayers()
end

-- Creates a floating label above the chip showing the owner's round hand rank.
-- Only fires during showdown, only if the owner has already revealed, and only once per chip
-- (button persists until cleanUp — no removal on drop).
function showChipHandRankHint(chipObj)
  local guid = chipObj.getGUID()
  if chipHintActive[guid] then return end

  local owner = chipZoneOwner[guid]
  if not owner then return end

  local revealed = revealedHandCards[owner.color]
  if not revealed or not revealed[owner.hand] then return end

  local handStr = chipHandRankSnapshot[guid]
  if not handStr or handStr == "" then return end

  local zRot          = chipObj.getRotation().z % 360
  local isRightSideUp = (zRot <= 10 or zRot >= 350)
  local btnY          = isRightSideUp and 0.15 or 0
  local btnRot        = isRightSideUp and { 0, 0, 0 } or { 0, 0, 180 }

  -- Round 2 (yellow) and round 4 (red) chips show text above the chip to avoid
  -- overlap when players drag all chips down at once
  local chipEntry     = chipGUIDToIndex[guid]
  local chipRound     = chipEntry and chipEntry.round or 1
  local zSign         = (chipRound == 2 or chipRound == 4) and -1 or 1

  local function visibleLen(s)
    return #(s:gsub("%[%x%x%x%x%x%x%]", ""):gsub("%[%-%]", ""))
  end

  chipObj.createButton({
    click_function = "doNothing",
    function_owner = Global,
    label          = handStr,
    position       = { 0, btnY, zSign * 1.25 },
    rotation       = btnRot,
    scale          = { 1, 1, 1 },
    width          = 0,
    height         = 0,
    font_size      = 200,
    font_color     = { 1, 1, 1, 1 },
  })

  local chipNum = chipPositionSnapshot[guid]
  if chipNum ~= nil then
    chipObj.createButton({
      click_function = "doNothing",
      function_owner = Global,
      label          = "★ " .. chipNum .. " ★",
      position       = { 0, btnY, zSign * 1.65 },
      rotation       = btnRot,
      scale          = { 1, 1, 1 },
      width          = 0,
      height         = 0,
      font_size      = 200,
      font_color     = { 1, 1, 1, 1 },
    })
  end

  chipHintActive[guid] = true
end

function onObjectPickUp(playerColor, pickedUpObject)
  if pickedUpObject.hasTag(TAGS.chips) then
    chipDraggedBy[pickedUpObject.getGUID()] = playerColor
    if handRankFrozen then
      showChipHandRankHint(pickedUpObject)
    end
  end
end

function onObjectDrop(playerColor, droppedObject)
  -- Note: chipDraggedBy is intentionally NOT cleared here — the chip may still be
  -- physically falling/sliding into a zone after the drop event fires, and we need the
  -- dragger info to be available when onObjectEnterScriptingZone runs for the peak guard.
  -- The next pickup overwrites the entry.
  -- Show Activate button on Math Wiz / Investor cards whenever they are placed.
  -- Bypass toolProcessedGUIDs so re-dropping after a round transition still re-adds the button.
  if droppedObject.type == "Card" and playerParameters[playerColor] then
    local toolName = droppedObject.getGMNotes()
    if toolName == "Math Wiz" then
      local isActivated = false
      for _, d in pairs(mathWizData) do
        if d.cardObj == droppedObject then
          isActivated = true; break
        end
      end
      if not isActivated then processMathWiz(droppedObject, playerColor) end
    elseif toolName == "Investor" then
      local isActivated = false
      for _, d in pairs(investorData) do
        if d.cardObj == droppedObject then
          isActivated = true; break
        end
      end
      if not isActivated then processInvestor(droppedObject, playerColor) end
    end
  end

  if not droppedObject.hasTag(TAGS.vault) then return end

  -- Auto-flip vault tiles face up when dropped
  local originalRotation = droppedObject.getRotation()
  droppedObject.setRotation({ originalRotation.x, originalRotation.y, 180 })

  if droppedObject.hasTag(TAGS.orange) then
    if lastSpecialVault then
      lastSpecialVault2 = lastSpecialVault
    else
      lastSpecialVault2 = nil
    end
    lastSpecialVault = "Orange"
    broadcastToAll(LANG(STRINGS.MSG_VAULT_ORANGE))
  elseif droppedObject.hasTag(TAGS.yellow) then
    if lastSpecialVault then
      lastSpecialVault2 = lastSpecialVault
    else
      lastSpecialVault2 = nil
    end
    lastSpecialVault = "Yellow"
    broadcastToAll(LANG(STRINGS.MSG_VAULT_YELLOW))
  else
    if lastSpecialVault then
      lastSpecialVault2 = lastSpecialVault
    else
      lastSpecialVault = nil
      lastSpecialVault2 = nil
    end
  end
end

function onObjectRotate(object, spinNew, flipNew, playerColor, spinOld, flipOld)
  if not object.hasTag(TAGS.alarm) then return end

  lastSpecialVault = nil
  lastSpecialVault2 = nil
end

function onObjectLeaveScriptingZone(zone, leave_object)
  -- A challenge token pulled out of the challenge zone is being removed/deactivated, so
  -- strip any control buttons it was carrying (rank locks, rainbow toggle, blanked value,
  -- reopen-vote, lil-Omaha, ...). Generalizes the original Intricate-Lock-only handling so
  -- every challenge resets the same way when moved out.
  if scriptZoneChallengesObj and zone == scriptZoneChallengesObj then
    leave_object.clearButtons()
    -- Instant-timed challenges (#15) update the moment the token leaves the zone too, so
    -- removing e.g. Sleeping Guard mid-game clears its forced-low effect live. Deferred one
    -- frame so the leaving token is no longer reported by scanActiveChallenges().
    local leftKey = challengeIdToKey[leave_object.getGMNotes()]
    if leftKey and getChallengeTiming(leftKey) == "instant" then
      Wait.frames(applyInstantChallengeChange, 1)
    end
    -- Refresh the incompatibility "X" marks live (#14). Deferred one frame so the leaving token
    -- is no longer counted by scanActiveChallenges() — removing a suppressor un-marks the rest.
    if leftKey then Wait.frames(refreshIncompatibleChallengeXMarks, 1) end
  end

  if not leave_object.hasTag(TAGS.chips) then return end
  if round < 1 or round > 5 then return end

  if round == 5 then
    -- Check if this is the highest-star chip for round 4 (showdown reminder trigger)
    local activeMap = getActiveChipMap(4, numPlayersStartofRound)
    if activeMap[leave_object.getGUID()] then
      local isHighest = true
      for guid, stars in pairs(activeMap) do
        if stars > (activeMap[leave_object.getGUID()] or 0) then
          isHighest = false
          break
        end
      end
      if isHighest then
        for playerColor, _ in pairs(playerParameters) do
          if zone == playerParameters[playerColor].topScriptZoneObj or
              zone == playerParameters[playerColor].botScriptZoneObj then
            challengeReminderHandRankPlayerObj.clearButtons()
            challengeReminderNumberPlayerObj.clearButtons()
            break
          end
        end
      end
    end
  end

  -- Check if the chip is a valid chip for the current round (regular + zero chips)
  local chipRound = round - 1
  local isCurrentRoundChip = false
  local activeChipMap = nil
  if chipRound >= 1 and chipRound <= 4 then
    activeChipMap = getActiveChipMap(chipRound, numPlayersStartofRound)
    isCurrentRoundChip = activeChipMap[leave_object.getGUID()] ~= nil
  end

  -- Check if this is an exit chip (round 4 only). Any exit chip functions once taken, so we
  -- recognize the full exit-chip set, not just the mode-limited active set.
  local isExitChip = false
  if chipRound == 4 then
    local activeExitGUIDs = getAllExitChipSet()
    isExitChip = activeExitGUIDs[leave_object.getGUID()] ~= nil
  end

  if not isCurrentRoundChip and not isExitChip then return end

  -- Exit chip leaving: recheck threshold and update notepad (no incremental counting needed)
  if isExitChip then
    local threshold = numPlayersStartofRound + getExitChipCount()
    local totalPlaced = chipsOnPlayers[chipRound] + countExitChipsOnPlayers() + countExitChipsInSupply()
    if FLAGS.Automode then
      if totalPlaced < threshold then
        cancelCountdown()
      end
    end
    updateNotepadRankings()
    positionChallengeReminderPlayers() -- a player un-exited → leader may have shifted back
    return
  end

  -- Build set of current-round chip GUIDs for zone scanning
  local currentRoundChipGUIDs = {}
  for guid, _ in pairs(activeChipMap) do
    currentRoundChipGUIDs[guid] = true
  end

  -- Check if zone is any seated player's script zone (only decrement if no other current-round chip remains)
  for playerColor, params in pairs(playerParameters) do
    if zone == params.topScriptZoneObj or
        zone == params.botScriptZoneObj then
      if isPlayerSeated(playerColor) then
        local otherChipRemains = false
        local zoneObjects = zone.getObjects()
        for _, obj in ipairs(zoneObjects) do
          local guid = obj.getGUID()
          if guid ~= leave_object.getGUID() and obj.hasTag(TAGS.chips) and currentRoundChipGUIDs[guid] then
            otherChipRemains = true
            break
          end
        end
        if not otherChipRemains then
          chipsOnPlayers[chipRound] = chipsOnPlayers[chipRound] - 1
        end
      end
      break
    end
  end

  local threshold = numPlayersStartofRound + (chipRound == 4 and getExitChipCount() or 0)
  local totalPlaced = chipsOnPlayers[chipRound] + countExitChipsOnPlayers() + countExitChipsInSupply()
  if FLAGS.Automode then
    if totalPlaced < threshold then
      cancelCountdown()
    end
  end

  updateNotepadRankings()
end

function onObjectEnterZone(zone, enter_object)
  if not zone or not enter_object then return end

  -- Check if this zone is a tool hand zone
  local zoneGUID = zone.getGUID()
  local toolColor = toolHandZoneLookup[zoneGUID]
  if toolColor and enter_object.type == "Card" then
    processToolCard(enter_object, toolColor)
  end

  if round < 1 or round > 5 then return end

  -- Check if this zone is a player hand zone
  local handInfo = handZoneLookup[zoneGUID]
  if not handInfo then return end

  -- Only process cards tagged as JOKER
  if not enter_object.hasTag(TAGS.joker) then return end

  -- Skip if this joker is already being processed
  local jokerGUID = enter_object.getGUID()
  if jokerProcessedGUIDs[jokerGUID] then return end

  -- Skip if player not seated
  local color = handInfo.color
  if not isPlayerSeated(color) then return end

  -- Mark as processing to prevent duplicates
  jokerProcessedGUIDs[jokerGUID] = true

  -- Delay to let the card settle into its actual destination hand zone.
  -- During deck.deal(), cards physically fly across the table and can pass through
  -- adjacent hand zones, triggering onObjectEnterZone for the wrong player first.
  -- After the delay, we re-scan all player hands to find who actually holds the card.
  Wait.time(function()
    if enter_object and not enter_object.isDestroyed() and enter_object.hasTag(TAGS.joker) then
      -- Re-determine which player actually holds this card
      local actualColor = nil
      local actualSource = nil
      for checkColor, params in pairs(playerParameters) do
        if Player[checkColor] and Player[checkColor].seated then -- real player only (needs getHandObjects)
          -- Check top hand
          if params.topHandObj then
            for _, obj in ipairs(Player[checkColor].getHandObjects()) do
              if obj.getGUID() == jokerGUID then
                actualColor = checkColor
                actualSource = "Top"
                break
              end
            end
          end
          -- Check bot hand (TwoHand mode)
          if not actualColor and params.botHandObj and FLAGS.TwoHand then
            for _, obj in ipairs(params.botHandObj.getObjects()) do
              if obj.getGUID() == jokerGUID then
                actualColor = checkColor
                actualSource = "Bot"
                break
              end
            end
          end
        end
        if actualColor then break end
      end

      if actualColor then
        processJokerCard(enter_object, actualColor, actualSource)
      end
    end
    -- Always clear the processed flag after a delay.
    -- If the joker was successfully moved to discard, it won't re-enter the zone.
    -- If processing failed, this allows re-detection when the card re-enters.
    Wait.time(function()
      jokerProcessedGUIDs[jokerGUID] = nil
    end, 2)
  end, 1.0)
end

function onObjectEnterContainer(container, enter_object)
  -- Reset challenge 37 locked hand ranks when its token is put into a bag
  local gmNotes = enter_object.getGMNotes()
  if gmNotes == CHALLENGES.INTRICATE_LOCK.id then
    userLockedHandRanks = {}
    lockedHandRanks = {}
    enter_object.clearButtons()
    return
  elseif LIL_OMAHA_IDS[gmNotes] then
    enter_object.clearButtons()
    return
    -- When "We Don't See Color" token enters a bag, rebuild force-locks so flush ranks are freed
  elseif gmNotes == CHALLENGES.NO_COLOR.id then
    flushActive = true
    rebuildLockedHandRanks()
    local tokenObj = findChallengeToken(CHALLENGES.INTRICATE_LOCK.id)
    if tokenObj then createIntricateLockButtons() end
  end

  if container == bagVaultObj then
    if not enter_object.hasTag(TAGS.vault) then
      return
    elseif enter_object.hasTag(TAGS.orange) or enter_object.hasTag(TAGS.yellow) then
      lastSpecialVault = nil
      lastSpecialVault2 = nil
    end

    updateVaultButtonLabel()
  end
end

function onObjectLeaveContainer(container, leave_object)
  if container == bagVaultObj then
    updateVaultButtonLabel()
  end
end

function onObjectEnterScriptingZone(zone, enter_object)
  -- Detect challenge 37 token entering challenge zone
  if scriptZoneChallengesObj and zone == scriptZoneChallengesObj then
    local gmNotes = enter_object.getGMNotes()
    if gmNotes == CHALLENGES.INTRICATE_LOCK.id then
      createIntricateLockButtons()
    elseif LIL_OMAHA_IDS[gmNotes] and lilOmahaTriggered then
      createLilOmahaButton(enter_object)
    end
    -- Rainbow (Grinding Gears) and Alarm (Quantum Chaos / Foot in the Door) toggles are
    -- re-added independently so a token carrying several buttons (e.g. Foot in the Door,
    -- which also has the Lil' Omaha toggle) gets all of them back when dropped into the zone.
    if gmNotes == CHALLENGES.GRINDING_GEARS.id and activeChallenges.GRINDING_GEARS then
      createRainbowButton(enter_object)
    end
    local alarmKey = ALARM_TOGGLE_IDS[gmNotes]
    if alarmKey and activeChallenges[alarmKey] and isChallengeCompatible(alarmKey) then
      createReminderAlarmButton(enter_object, alarmKey)
    end
    -- Instant-timed challenges (#15) apply their effect the moment the token enters the zone.
    local enteredKey = challengeIdToKey[gmNotes]
    if enteredKey and getChallengeTiming(enteredKey) == "instant" then
      applyInstantChallengeChange()
    end
    -- Refresh the incompatibility "X" marks live (#14): the entering token may itself be
    -- suppressed, or it may be a suppressor that now disables other present tokens.
    if enteredKey then refreshIncompatibleChallengeXMarks() end
  end

  if not enter_object.hasTag(TAGS.chips) then return end

  -- Check if the chip is a valid chip for the current round (regular + zero chips)
  local chipRound = round - 1
  local isCurrentRoundChip = false
  local activeChipMap = nil
  if chipRound >= 1 and chipRound <= 4 then
    activeChipMap = getActiveChipMap(chipRound, numPlayersStartofRound)
    isCurrentRoundChip = activeChipMap[enter_object.getGUID()] ~= nil
  end

  -- Check if this is an exit chip (round 4 only). Any exit chip functions once taken, so we
  -- recognize the full exit-chip set, not just the mode-limited active set.
  local isExitChip = false
  if chipRound == 4 then
    local activeExitGUIDs = getAllExitChipSet()
    isExitChip = activeExitGUIDs[enter_object.getGUID()] ~= nil
  end

  if not isCurrentRoundChip and not isExitChip then return end

  -- Exit chip entering: recheck threshold and update notepad (no incremental counting needed)
  if isExitChip then
    local threshold = numPlayersStartofRound + getExitChipCount()
    local totalPlaced = chipsOnPlayers[chipRound] + countExitChipsOnPlayers() + countExitChipsInSupply()
    if FLAGS.Automode then
      if totalPlaced >= threshold then
        startCountdown()
      end
    end
    updateNotepadRankings()
    positionChallengeReminderPlayers() -- a player just exited → leader may have shifted
    return
  end

  -- Build set of current-round chip GUIDs for zone scanning
  local currentRoundChipGUIDs = {}
  for guid, _ in pairs(activeChipMap) do
    currentRoundChipGUIDs[guid] = true
  end

  -- Check if zone is any player's script zone (only count if zone has no other current-round chip)
  for playerColor, params in pairs(playerParameters) do
    if zone == params.topScriptZoneObj or
        zone == params.botScriptZoneObj then
      if isPlayerSeated(playerColor) then
        local alreadyHasChip = false
        local zoneObjects = zone.getObjects()
        for _, obj in ipairs(zoneObjects) do
          local guid = obj.getGUID()
          if guid ~= enter_object.getGUID() and obj.hasTag(TAGS.chips) and currentRoundChipGUIDs[guid] then
            alreadyHasChip = true
            break
          end
        end
        if not alreadyHasChip then
          chipsOnPlayers[chipRound] = chipsOnPlayers[chipRound] + 1
        end
        local hand = (zone == params.topScriptZoneObj) and "Top" or "Bot"
        -- Update round peak when a chip physically enters the zone.
        -- Strictly requires the dragger to be the zone owner so accidental peaks
        -- (drag-throughs, post-drop physics slides into another player's space) are ignored.
        -- Test players can never drag chips themselves, so skip the dragger check for them.
        local chipValue = activeChipMap[enter_object.getGUID()]
        local isTestZone = testPlayerSet and testPlayerSet[playerColor]
        if chipValue and (chipDraggedBy[enter_object.getGUID()] == playerColor or isTestZone) then
          local steamId = getPlayerSteamId(playerColor)
          local key = FLAGS.TwoHand and (steamId .. hand) or steamId
          peakChipIndex[key] = math.max(peakChipIndex[key] or 0, chipValue)
          lowPeakChipIndex[key] = math.min(lowPeakChipIndex[key] or chipValue, chipValue)
        end
      end
      break
    end
  end

  local threshold = numPlayersStartofRound + (chipRound == 4 and getExitChipCount() or 0)
  local totalPlaced = chipsOnPlayers[chipRound] + countExitChipsOnPlayers() + countExitChipsInSupply()
  if FLAGS.Automode then
    if totalPlaced >= threshold then
      startCountdown()
    end
  end

  updateNotepadRankings()

  -- Showdown reminder: trigger when the highest-star round 4 chip is placed
  if numPlayersStartofRound < 1 or round ~= 5 then
    return
  end
  local highestStarChipGUID = chipGUIDs[4][math.min(numPlayersStartofRound, #chipGUIDs[4])]
  if not highestStarChipGUID or enter_object.getGUID() ~= highestStarChipGUID then
    return
  end

  positionChallengeReminderPlayers()
end

-- Position the player-side Scan Challenge reminders (Num / H.R) at the current leader's
-- nameplate — the highest NON-EXITED hand. If the leader exited (exit chip / backdoor),
-- they shift to the next non-exit hand; if nobody qualifies, the reminders are cleared.
function positionChallengeReminderPlayers()
  if round ~= 5 then return end
  if not (activeChallenges.RETINA_SCAN or activeChallenges.FINGERPRINT_SCAN) then return end
  local leader = scanNonExitChipRankings()[1]
  if not leader or not playerParameters[leader.color] or not playerParameters[leader.color].namePlatePosition then
    if challengeReminderNumberPlayerObj then challengeReminderNumberPlayerObj.clearButtons() end
    if challengeReminderHandRankPlayerObj then challengeReminderHandRankPlayerObj.clearButtons() end
    return
  end
  local npp = playerParameters[leader.color].namePlatePosition
  local offset2H = getChallengeReminderPlayerOffset()
  if activeChallenges.RETINA_SCAN then
    createChallengeReminderButton(challengeReminderNumberPlayerObj, 'Num', 'Num')
    challengeReminderNumberPlayerObj.setPosition({
      npp.x + offset2H.x, npp.y + offset2H.y, npp.z + offset2H.z })
  end
  if activeChallenges.FINGERPRINT_SCAN then
    createChallengeReminderButton(challengeReminderHandRankPlayerObj, 'H.R', 'HS')
    challengeReminderHandRankPlayerObj.setPosition({
      npp.x - offset2H.x, npp.y + offset2H.y, npp.z + offset2H.z })
  end
end

