-- Shared helper: moves all Challenge-tagged objects from a source bag into bagChallengesPlayObj.
function transferChallengesFromBag(sourceBag, categoryLabel)
  if not sourceBag or not bagChallengesPlayObj then return end
  local challenges = {}
  for _, entry in ipairs(sourceBag.getObjects()) do
    for _, tag in ipairs(entry.tags or {}) do
      if tag == TAGS.challenge then
        table.insert(challenges, entry)
        break
      end
    end
  end
  for _, entry in ipairs(challenges) do
    sourceBag.takeObject({
      guid = entry.guid,
      smooth = false,
      rotation = bagChallengesPlayObj.getRotation(),
      callback_function = function(takenObj)
        if takenObj then
          bagChallengesPlayObj.putObject(takenObj)
        end
      end
    })
  end
  broadcastToAll(LANG(STRINGS.MSG_CHALLENGES_ADDED, #challenges, categoryLabel), colorGoldVector)
end

