-- Shared confirm-click handler for challenge bag buttons.
-- Any click sets label to "Right Click 2 Confirm". Right-click when pending executes the action.
function challengeBagConfirmClick(bagObj, originalLabel, alt_click, actionFn)
  local guid = bagObj.getGUID()
  local pending = challengeBagPending[guid]

  if pending then
    -- Already in confirm state
    if alt_click then
      -- Confirmed — execute action and reset label
      challengeBagPending[guid] = nil
      bagObj.editButton({ index = 0, label = originalLabel })
      actionFn()
    end
    -- Left-click while pending = do nothing (already showing confirm text)
    return
  end

  -- First click (any) — enter confirm state
  challengeBagPending[guid] = true
  bagObj.editButton({ index = 0, label = LANG(STRINGS.BTN_RIGHT_CLICK) })
end

function onButtonWinClick(obj, playerColor)
  if not antiTrollClearance(playerColor) then return end
  if not bagVaultObj or not vaultTile then return end

  if #bagVaultObj.getObjects() > 0 then
    -- Find all vault-tagged objects in the bag
    local vaults = {}
    for _, obj in ipairs(bagVaultObj.getObjects()) do
      for _, tag in ipairs(obj.tags or {}) do
        if tag == TAGS.vault then
          table.insert(vaults, obj)
          break
        end
      end
    end
    if #vaults > 0 then
      local chosen = vaults[math.random(#vaults)]
      local tilePos = vaultTile.getPosition()
      local vault = bagVaultObj.takeObject({
        guid = chosen.guid,
        smooth = true,
        position = { tilePos.x, tilePos.y + 2, tilePos.z },
        rotation = { 0, 90, 180 },
      })

      if vault then
        onObjectDrop(playerColor, vault)
      end
    end
  end
end

