-- Process a tool card entering a player's tool hand zone.
-- Checks GMNotes for tool name and triggers the corresponding effect.
-- Uses toolProcessedGUIDs guard to prevent duplicate triggers from drag flickering.
function processToolCard(cardObj, color)
  if not cardObj or not color then return end
  local toolName = cardObj.getGMNotes()
  if not toolName or toolName == "" then return end

  -- Debounce: prevent multiple triggers while dragging
  local toolGUID = cardObj.getGUID()
  if toolProcessedGUIDs[toolGUID] then return end
  toolProcessedGUIDs[toolGUID] = true

  -- Wait until the player releases the card before processing.
  -- If dragged in manually, held_by_color is set; we delay until it clears.
  local function executeToolEffect()
    if toolName == "Burner Phone" then
      processBurnerPhone(cardObj, color)
    elseif toolName == "Lubricant" then
      processLubricant(cardObj, color)
    elseif toolName == "Flashlight" then
      processFlashlight(cardObj, color)
    elseif toolName == "Night Vision Goggles" then
      processNightVision(cardObj, color)
    elseif toolName == "Magic 8 Ball" then
      processMagic8Ball(cardObj, color)
    elseif toolName == "Math Wiz" then
      processMathWiz(cardObj, color)
    elseif toolName == "Investor" then
      processInvestor(cardObj, color)
    elseif toolName == "Backdoor Key" then
      processBackdoorKey(cardObj, color)
    end
    -- Clear the processed flag after a delay to allow re-use if needed
    Wait.time(function()
      toolProcessedGUIDs[toolGUID] = nil
    end, 3)
  end

  if cardObj.held_by_color then
    Wait.condition(
      executeToolEffect,
      function() return not cardObj or cardObj.isDestroyed() or not cardObj.held_by_color end,
      5,                                                -- timeout after 5 seconds
      function() toolProcessedGUIDs[toolGUID] = nil end -- on timeout, clear guard
    )
  else
    executeToolEffect()
  end
end

-- Returns the face-up tool position for a given player color.
-- 7CS uses faceupToolPositionSpecialOffset, BS uses nameplate X (no X offset), normal uses faceupToolPositionOffset.
-- TwoHand (normal mode only) shifts Z toward center by playerChipSpacePositionOffset.z.
function getFaceupToolPosition(color)
  local npp = playerParameters[color].namePlatePosition
  local mode = getGameMode()
  if mode.perPlayer then
    return {
      x = npp.x + faceupToolPositionSpecialOffset.x,
      y = npp.y + faceupToolPositionSpecialOffset.y,
      z = npp.z + faceupToolPositionSpecialOffset.z
    }
  elseif mode.perGap then
    return {
      x = npp.x,
      y = npp.y + faceupToolPositionOffset.y,
      z = npp.z + faceupToolPositionOffset.z
    }
  else
    local zExtra = FLAGS.TwoHand and playerChipSpacePositionOffset.z or 0
    return {
      x = npp.x + faceupToolPositionOffset.x,
      y = npp.y + faceupToolPositionOffset.y,
      z = npp.z + faceupToolPositionOffset.z + zExtra
    }
  end
end

-- Positions and locks a tool/specialist card face-up at the player's standard tool position.
function lockToolFaceUp(obj, color)
  local pos = getFaceupToolPosition(color)
  obj.setPosition(pos)
  obj.setRotation({ 0, 0, 0 })
  obj.setLock(true)
  obj.sticky = false
end

-- Creates activate button(s) on a card (clears first).
-- If clickFnTop + clickFnBot are set AND FLAGS.TwoHand: creates "Activate TOP" + "Activate BOT".
