-- Flashlight Activate: position + lock tool, spawn script zone, draw a card from deck.
function onFlashlightActivate(obj, playerColor)
  if not obj or not playerColor then return end
  if not playerParameters[playerColor] then return end
  if numPlayersStartofRound == 0 or handRankFrozen then return end
  if flashlightData[playerColor] then return end

  refreshDeckReference()
  if not deck then return end

  lockToolFaceUp(obj, playerColor)
  local toolPos = getFaceupToolPosition(playerColor) -- needed for card offset below

  -- Spawn script zone on the tool card
  local scriptZone = spawnObject({
    type = "ScriptingTrigger",
    position = { toolPos.x, toolPos.y, toolPos.z },
    rotation = { 0, 0, 0 },
    scale = { 2, 1, 3 },
  })
  scriptZone.setGMNotes("flashlightScriptZone")

  -- Store data immediately (cardObj filled in callback)
  flashlightData[playerColor] = {
    toolObj = obj,
    scriptZoneObj = scriptZone,
    cardObj = nil,
  }

  -- Draw a card from deck, skip jokers
  local function drawCard()
    refreshDeckReference()
    if not deck then return end
    deck.takeObject({
      position = {
        toolPos.x + flashlightCardOffset.x,
        toolPos.y + flashlightCardOffset.y,
        toolPos.z + flashlightCardOffset.z
      },
      rotation = { 0, 0, 0 },
      smooth = false,
      callback_function = function(drawnCard)
        if not drawnCard then return end
        if drawnCard.hasTag(TAGS.joker) then
          if cardDiscardTileObj then
            local discardPos = cardDiscardTileObj.getPosition()
            local discardRot = cardDiscardTileObj.getRotation()
            drawnCard.setPosition({ discardPos.x, discardPos.y + 0.5, discardPos.z })
            drawnCard.setRotation({ discardRot.x, discardRot.y, discardRot.z })
          end
          Wait.time(drawCard, 0.2)
        else
          if flashlightData[playerColor] then
            flashlightData[playerColor].cardObj = drawnCard
          end
        end
      end
    })
  end

  drawCard()
  addToolActivatedButtons(obj, {
    resetFn = "onFlashlightReset",
    tooltip = STRINGS.TOOLTIP_FLASHLIGHT_OFF,
  })
end

-- Flashlight Reset: return drawn card to discard, destroy script zone, unlock tool.
function onFlashlightReset(obj, playerColor)
  if not obj then return end

  local ownerColor = nil
  for color, data in pairs(flashlightData) do
    if data.toolObj == obj then
      ownerColor = color
      break
    end
  end
  if not ownerColor then return end

  resetFlashlight(ownerColor, false)
end

-- Shared reset logic for a single flashlight.
-- discardTool: if true, also discard the tool card face-up onto tool discard pile.
function resetFlashlight(color, discardTool)
  local data = flashlightData[color]
  if not data then return end
  if discardTool and data.cardObj and not data.cardObj.isDestroyed() then
    if cardDiscardTileObj then
      local pos = cardDiscardTileObj.getPosition()
      data.cardObj.setPosition({ pos.x, pos.y + 0.5, pos.z })
      data.cardObj.setRotation({ 0, 0, 180 })
    end
  end
  if data.scriptZoneObj and not data.scriptZoneObj.isDestroyed() then
    data.scriptZoneObj.destruct()
  end
  resetToolCard(data.toolObj, discardTool, toolsDiscardTile)
  flashlightData[color] = nil
end

-- Cleanup all active flashlights: discard drawn cards + tool cards, destroy script zones.
function cleanUpFlashlights()
  local colors = {}
  for color, _ in pairs(flashlightData) do
    table.insert(colors, color)
  end
  for _, color in ipairs(colors) do
    resetFlashlight(color, true)
  end
end

