-- Animation frames cycled before revealing the answer.
local MAGIC8BALL_FRAMES = { "● ● ●", "◆ ◆ ◆", "○ ○ ○", "◇ ◇ ◇", "▲ ▲ ▲", "∗ ∗ ∗", "☆ ☆ ☆", "★ ★ ★" }
local MAGIC8BALL_FRAME_DELAY = 0.45 -- seconds per frame

-- Returns the predicted chip number for the given hand, plus total hand count.
-- Chip numbers: best hand = highest chip (up to 8), worst = 1 (or 0 for 9+ player games).
-- hand: "top" or "bot"
function computeMagic8BallChipNumber(color, hand)
  local myCache = handRankCodeCache[color]
  if not myCache then return nil, 0 end
  local myRank  = (hand == "bot") and myCache.bot or myCache.top
  local myScore = (hand == "bot") and myCache.botScore or myCache.topScore
  local myPrio  = handRankPriority[myRank] or 0
  if not myRank or myPrio == 0 then return nil, 0 end

  -- Compare (priority, score) pairs — score alone is not cross-rank comparable
  -- because it is a within-rank tiebreaker packed from card values.
  local function isWorse(rank, score)
    local prio = handRankPriority[rank] or 0
    return prio < myPrio or (prio == myPrio and (score or 0) < (myScore or 0))
  end

  -- Count all hands in play (TOP + BOT in 2-hand mode, TOP only otherwise).
  local lower = 0
  local total = 0
  for c, _ in pairs(playerParameters) do
    if isPlayerSeated(c) then
      local cache = handRankCodeCache[c]
      if cache and cache.top then
        total = total + 1
        if isWorse(cache.top, cache.topScore) then lower = lower + 1 end
        if FLAGS.TwoHand and cache.bot then
          total = total + 1
          if isWorse(cache.bot, cache.botScore) then lower = lower + 1 end
        end
      end
    end
  end

  if total == 0 then return nil, 0 end

  -- posFromBottom: 1 = worst. Subtract zero-chip slots to get the star chip value.
  local posFromBottom = lower + 1
  local zeroNeeded    = math.max(0, total - 8)
  local chipValue     = (posFromBottom <= zeroNeeded) and 0 or (posFromBottom - zeroNeeded)
  return chipValue, total
end

