-- Shared activation: pin card, run symbol animation, then show rank answer.
function activateMagic8Ball(obj, playerColor, hand)
  if not obj or not playerColor then return end
  if not playerParameters[playerColor] then return end
  if magic8BallData[playerColor] then return end
  if numPlayersStartofRound == 0 then return end

  lockToolFaceUp(obj, playerColor)
  magic8BallData[playerColor] = { cardObj = obj, hand = hand }

  -- Shared button params for animation and result frames.
  local function setFrameButton(label, clickFn, col, fontCol)
    if not obj or obj.isDestroyed() then return end
    obj.clearButtons()
    obj.createButton({
      click_function = clickFn or "doNothing",
      function_owner = Global,
      label          = label,
      position       = { 0, 0.5, -0.85 },
      width          = 700,
      height         = 380,
      font_size      = 200,
      color          = col or colorDarkBlueVector,
      font_color     = fontCol or { 1, 1, 1, 1 },
    })
  end

  -- Chain animation frames, then reveal answer.
  local function runFrame(index)
    if not obj or obj.isDestroyed() then return end
    if index <= #MAGIC8BALL_FRAMES then
      setFrameButton(MAGIC8BALL_FRAMES[index])
      Wait.time(function() runFrame(index + 1) end, MAGIC8BALL_FRAME_DELAY)
    else
      -- Animation done — compute and show the answer.
      local chipValue, total = computeMagic8BallChipNumber(playerColor, hand)
      local answerLabel = (chipValue ~= nil and total > 0) and ("★ " .. chipValue .. " ★") or "★ ? ★"
      setFrameButton(answerLabel)
      if not obj or obj.isDestroyed() then return end
      -- In 2-hand mode: show a label indicating which hand is displayed.
      if FLAGS.TwoHand then
        local handLabel2 = (hand == "top") and LANG(STRINGS.BTN_MAGIC8BALL_ACTIVE_TOP) or
            LANG(STRINGS.BTN_MAGIC8BALL_ACTIVE_BOT)
        obj.createButton({
          click_function = "doNothing",
          function_owner = Global,
          label          = handLabel2,
          position       = { 0, 0.5, -0.2 },
          width          = 600,
          height         = 200,
          font_size      = 100,
          color          = colorDarkBlueVector,
          font_color     = { 0.7, 0.7, 0.7, 1 },
        })
      end
      -- Reset button below the answer.
      obj.createButton({
        click_function = "onMagic8BallReset",
        function_owner = Global,
        label          = LANG(STRINGS.BTN_RESET),
        position       = { 0, 0.5, -1.65 },
        width          = 600,
        height         = 230,
        font_size      = 110,
        color          = colorRedVector,
        font_color     = colorWhiteVector,
        tooltip        = LANG(STRINGS.TOOLTIP_MAGIC8BALL_OFF),
      })
    end
  end

  runFrame(1)
end

