-- Returns the blackjack-style face value of a card value string.
-- J/Q/K = 10, A = 11, W (wild) = 11, 2-10 = numeric, B/C/D = 15/16/17, blanked = 0.
function getCardFaceValue(value)
  if value == "J" or value == "Q" or value == "K" then return 10 end
  if value == "A" then return 11 end
  if value == "W" then return 11 end
  if value == "B" then return 12 end
  if value == "C" then return 13 end
  if value == "D" then return 14 end
  return tonumber(value) or 0
end

