-- Counts J, Q, K cards in a player's hand. hand = "Top"/"Bot"/nil (both).
-- Wilds resolve to their best poker value; count as face card if that resolved value is J/Q/K.
function getInvestorCount(color, hand)
  local handCards = {}
  if hand == nil or hand == "Top" then
    for _, c in ipairs(dealtCards[color] and dealtCards[color]["Top"] or {}) do table.insert(handCards, c) end
  end
  if hand == nil or hand == "Bot" then
    for _, c in ipairs(dealtCards[color] and dealtCards[color]["Bot"] or {}) do table.insert(handCards, c) end
  end
  local cards, commCards = getSpecialistActiveCards(handCards, color)
  cards = resolveWildsForSpecialist(cards, commCards)
  local count = 0
  for _, cardName in ipairs(cards) do
    local value = string.sub(cardName, 2)
    if value == "J" or value == "Q" or value == "K" then count = count + 1 end
  end
  return count
end

-- Investor: add an Activate button when entering tool hand.
function processInvestor(cardObj, color)
  if not cardObj then return end
  Wait.time(function()
    if not cardObj or cardObj.isDestroyed() then return end
    addToolActivateButtons(cardObj, {
      clickFn = "onInvestorActivate",
      tooltip = STRINGS.TOOLTIP_INVESTOR_ON,
    })
    if pendingSpecialistActivations[color] and pendingSpecialistActivations[color].type == "Investor" then
      pendingSpecialistActivations[color].obj = cardObj
      cardObj.editButton({
        index = 0,
        label = LANG(STRINGS.BTN_SPECIALIST_QUEUED),
        color = colorGoldVector,
        font_color =
            colorDarkBlueVector
      })
    end
  end, 0.3)
end

-- Investor Activate: lock card face-up, snapshot face-card counts for ALL players once, show Reset button.
function onInvestorActivate(obj, playerColor)
  if not obj or not playerColor then return end
  if not playerParameters[playerColor] then return end
  if round ~= 2 then
    broadcastToColor(LANG(STRINGS.MSG_TOOLSPEC_ONLY_ROUND_1), playerColor, colorGoldVector)
    return
  end
  if numPlayersStartofRound == 0 or handRankFrozen then return end
  if next(jokerPendingUI) ~= nil then
    if not pendingSpecialistActivations[playerColor] then
      pendingSpecialistActivations[playerColor] = { type = "Investor", obj = obj }
      obj.editButton({
        index = 0,
        label = LANG(STRINGS.BTN_SPECIALIST_QUEUED),
        color = colorGoldVector,
        font_color =
            colorDarkBlueVector
      })
    end
    broadcastToColor(LANG(STRINGS.MSG_SPECIALIST_QUEUED), playerColor, colorGoldVector)
    return
  end
  pendingSpecialistActivations[playerColor] = nil
  if investorData[playerColor] then return end

  lockToolFaceUp(obj, playerColor)

  -- Snapshot face-card counts for every seated player at activation time (not updated later).
  collectDealtCards()
  local cachedValues = {}
  for color, _ in pairs(playerParameters) do
    if isPlayerSeated(color) then
      cachedValues[color] = { top = getInvestorCount(color, "Top"), bot = getInvestorCount(color, "Bot") }
    end
  end
  investorData[playerColor] = { cardObj = obj, cachedValues = cachedValues }
  updateAllSpecialistDisplays()
  addToolActivatedButtons(obj, {
    resetFn = "onInvestorReset",
    tooltip = STRINGS.TOOLTIP_INVESTOR_OFF,
  })
end

function onInvestorReset(obj, playerColor)
  if not obj then return end
  for color, data in pairs(investorData) do
    if data.cardObj == obj then
      resetInvestor(color, false)
      return
    end
  end
end

function resetInvestor(color, discardTool)
  local data = investorData[color]
  if not data then return end
  resetToolCard(data.cardObj, discardTool, specialistsDiscardTile)
  investorData[color] = nil
  updateAllSpecialistDisplays()
end

function cleanUpInvestor()
  local colors = {}
  for color, _ in pairs(investorData) do table.insert(colors, color) end
  for _, color in ipairs(colors) do resetInvestor(color, true) end
end

