-- Builds the label for a player's specialist display from cached snapshots.
-- hand = "Top"/"Bot" for TwoHand buttons; nil = combined (normal mode).
-- Hands invalidated by challenge discards have nil values and produce no entry.
function buildSpecialistLabel(color, hand)
  local parts = {}
  for _, data in pairs(mathWizData) do
    if data.cachedValues and data.cachedValues[color] ~= nil then
      local vals = data.cachedValues[color]
      if hand == "Top" then
        if vals.top ~= nil then table.insert(parts, "Σ " .. tostring(vals.top)) end
      elseif hand == "Bot" then
        if vals.bot ~= nil then table.insert(parts, "Σ " .. tostring(vals.bot)) end
      else
        if vals.top ~= nil or vals.bot ~= nil then
          table.insert(parts, "Σ " .. tostring((vals.top or 0) + (vals.bot or 0)))
        end
      end
      break
    end
  end
  for _, data in pairs(investorData) do
    if data.cachedValues and data.cachedValues[color] ~= nil then
      local vals = data.cachedValues[color]
      if hand == "Top" then
        if vals.top ~= nil then table.insert(parts, "JQK " .. tostring(vals.top)) end
      elseif hand == "Bot" then
        if vals.bot ~= nil then table.insert(parts, "JQK " .. tostring(vals.bot)) end
      else
        if vals.top ~= nil or vals.bot ~= nil then
          table.insert(parts, "JQK " .. tostring((vals.top or 0) + (vals.bot or 0)))
        end
      end
      break
    end
  end
  return table.concat(parts, "  ")
end

-- Clears cached specialist values for a specific hand (after challenge discard).
function invalidateSpecialistCacheForHand(color, hand)
  local key = (hand == "Top") and "top" or "bot"
  for _, data in pairs(mathWizData) do
    if data.cachedValues and data.cachedValues[color] then
      data.cachedValues[color][key] = nil
    end
  end
  for _, data in pairs(investorData) do
    if data.cachedValues and data.cachedValues[color] then
      data.cachedValues[color][key] = nil
    end
  end
  updateAllSpecialistDisplays()
end

-- Clears Math Wiz and Investor buttons for a player whose hand was challenge-discarded.
function clearSpecialistButtonsForPlayer(color)
  if mathWizData[color] and mathWizData[color].cardObj and not mathWizData[color].cardObj.isDestroyed() then
    mathWizData[color].cardObj.clearButtons()
  end
  if investorData[color] and investorData[color].cardObj and not investorData[color].cardObj.isDestroyed() then
    investorData[color].cardObj.clearButtons()
  end
end

-- Updates the specialist display buttons on a player's nameplate.
-- In TwoHand mode: button 1 (Z+) = Top hand, button 2 (Z-) = Bot hand.
-- In normal mode: button 1 (center) = combined, button 2 hidden.
function updateSpecialistDisplay(color)
  local params = playerParameters[color]
  if not params or not params.namePlateObj then return end

  if next(mathWizData) == nil and next(investorData) == nil then
    params.namePlateObj.editButton({ index = 1, label = "", width = 0, height = 0 })
    params.namePlateObj.editButton({ index = 2, label = "", width = 0, height = 0 })
    return
  end

  local bothActive = next(mathWizData) ~= nil and next(investorData) ~= nil
  local btnWidth = bothActive and 2400 or 1200

  if FLAGS.TwoHand then
    local topLabel = buildSpecialistLabel(color, "Top")
    local botLabel = buildSpecialistLabel(color, "Bot")

    if topLabel ~= "" then
      params.namePlateObj.editButton({
        index = 1,
        label = topLabel,
        position = { 0, 0.1, -2 },
        width = btnWidth,
        height = 500,
        font_size = 500,
        color = colorDarkBlueVector,
        font_color = colorGoldVector,
      })
    else
      params.namePlateObj.editButton({ index = 1, label = "", width = 0, height = 0 })
    end

    if botLabel ~= "" then
      params.namePlateObj.editButton({
        index = 2,
        label = botLabel,
        position = { 0, 0.1, 2 },
        width = btnWidth,
        height = 500,
        font_size = 500,
        color = colorDarkBlueVector,
        font_color = colorGoldVector,
      })
    else
      params.namePlateObj.editButton({ index = 2, label = "", width = 0, height = 0 })
    end
  else
    local label = buildSpecialistLabel(color, nil)
    if label ~= "" then
      params.namePlateObj.editButton({
        index = 1,
        label = label,
        position = { 0, 0.1, -2 },
        width = btnWidth,
        height = 500,
        font_size = 500,
        color = colorDarkBlueVector,
        font_color = colorGoldVector,
      })
    else
      params.namePlateObj.editButton({ index = 1, label = "", width = 0, height = 0 })
    end
    params.namePlateObj.editButton({ index = 2, label = "", width = 0, height = 0 })
  end
end

-- Hides the specialist display buttons for one player.
function clearSpecialistDisplay(color)
  local params = playerParameters[color]
  if not params or not params.namePlateObj then return end
  params.namePlateObj.editButton({ index = 1, label = "", width = 0, height = 0 })
  params.namePlateObj.editButton({ index = 2, label = "", width = 0, height = 0 })
end

-- Updates specialist displays for all players. Called from the hand rank update loop.
function updateAllSpecialistDisplays()
  for color, _ in pairs(playerParameters) do
    updateSpecialistDisplay(color)
  end
end

-- Clicking a player's Math Wiz nameplate label broadcasts their possible
-- card-value combinations privately to the clicking player.
function onMathWizNameplateTopClick(obj, playerColor)
  local targetColor = obj.getGMNotes()
  if targetColor then showMathWizCombosForPlayer(targetColor, "Top", playerColor) end
end

function onMathWizNameplateBotClick(obj, playerColor)
  local targetColor = obj.getGMNotes()
  if targetColor then showMathWizCombosForPlayer(targetColor, "Bot", playerColor) end
end

function showMathWizCombosForPlayer(targetColor, hand, clickerColor)
  if next(mathWizData) == nil then return end
  local vals = nil
  for _, data in pairs(mathWizData) do
    if data.cachedValues and data.cachedValues[targetColor] then
      vals = data.cachedValues[targetColor]
      break
    end
  end
  if not vals then return end

  local sum = (hand == "Top") and vals.top or vals.bot
  local cnt = (hand == "Top") and vals.topCount or vals.botCount
  if sum == nil or cnt == nil or cnt == 0 then return end

  local combos   = generateMathWizCombos(sum, cnt)
  local MAX_SHOW = 15
  local comboStr
  if #combos == 0 then
    comboStr = LANG_NOTAGS(STRINGS.MSG_MATHWIZ_NO_COMBOS)
  else
    local parts = {}
    for i = 1, math.min(#combos, MAX_SHOW) do
      table.insert(parts, formatMathWizCombo(combos[i]))
    end
    comboStr = table.concat(parts, ", ")
    if #combos > MAX_SHOW then
      comboStr = comboStr .. ", " .. LANG_NOTAGS(STRINGS.MSG_MATHWIZ_MORE, #combos - MAX_SHOW)
    end
  end

  local name = "[" .. colorToRGBHex(targetColor) .. "]" .. getPlayerDisplayName(targetColor) .. "[FFFFFF]"
  local handSuffix = FLAGS.TwoHand and (" (" .. hand .. ")") or ""
  local plural = cnt == 1 and "" or "s"
  broadcastToColor(
    LANG(STRINGS.MSG_MATHWIZ_COMBO_LINE, name .. handSuffix, sum, cnt, plural, comboStr),
    clickerColor, colorGoldVector
  )
end

