-- Burner Phone: discard the tool card face-up, draw 2 specialist cards into tool hand.
function processBurnerPhone(cardObj, color)
  -- Discard the Burner Phone face-up on the tools discard tile
  if toolsDiscardTile then
    local discardPos = toolsDiscardTile.getPosition()
    Wait.time(function()
      if not cardObj or cardObj.isDestroyed() then return end
      cardObj.setPosition({ discardPos.x, discardPos.y + 0.5, discardPos.z })
      cardObj.setRotation({ 0, 0, 0 })
    end, 0.3)
  end

  -- Find specialist deck in script zone
  if not specialistsTileScriptZoneObj then return end

  local specDeck = nil
  for _, zoneObj in ipairs(specialistsTileScriptZoneObj.getObjects()) do
    if zoneObj.type == "Deck" and zoneObj.hasTag(TAGS.specialist) then
      specDeck = zoneObj
      break
    end
  end

  if not specDeck then
    broadcastToColor(LANG(STRINGS.MSG_NO_SPECIALIST_DECK), color, { 1, 0.2, 0.2 })
    return
  end

  local params = playerParameters[color]
  if not params or not params.toolHandObj then return end
  local handPos = params.toolHandObj.getPosition()

  specDeck.shuffle()
  Wait.time(function()
    if not specDeck or specDeck.isDestroyed() then return end
    for i = 1, 2 do
      specDeck.takeObject({
        position = { handPos.x, handPos.y + 1 + i * 0.2, handPos.z },
        flip = true,
        smooth = false,
      })
    end
    broadcastToColor(LANG(STRINGS.MSG_BURNER_PHONE), color, { 1, 0.85, 0.3 })
  end, 0.3)
end

-- Shared helper: resets all cards/decks with a given tag back to a target tile.
-- Extracts tagged cards from mixed decks, moves loose cards and tagged decks.
function resetTaggedCardsToTile(tag, targetTile)
  if not targetTile then return end
  local tilePos = targetTile.getPosition()
  local resetPos = { x = tilePos.x, y = tilePos.y + 0.5, z = tilePos.z }

  local allObjects = getAllObjects()
  for _, obj in ipairs(allObjects) do
    if obj.type == "Card" and obj.hasTag(tag) then
      obj.setPosition(resetPos)
      obj.setRotation({ 0, 0, 180 })
      obj.setLock(false)
    elseif obj.type == "Deck" then
      if obj.hasTag(tag) then
        obj.setPosition(resetPos)
        obj.setRotation({ 0, 0, 180 })
        obj.setLock(false)
      else
        for _, card in ipairs(obj.getObjects()) do
          local hasTag = false
          if card.tags then
            for _, t in ipairs(card.tags) do
              if t == tag then
                hasTag = true
                break
              end
            end
          end
          if hasTag then
            local cardToMove = obj.takeObject({ guid = card.guid, smooth = false })
            if cardToMove then
              cardToMove.setPosition(resetPos)
              cardToMove.setRotation({ 0, 0, 180 })
              cardToMove.setLock(false)
            end
          end
        end
      end
    end
  end
end

