specialModeFirstTileZOffset = -5 -- Z offset from nameplate: just above HandRank (which is at -3.0)
bananaColumnSpacingZ = -2.55     -- Z spacing between columns (negative = stacking toward center)

------------------------------------
--- Banana Split: Gap Computation & Positioning
------------------------------------

-- Computes the circular gap list for Banana Split mode based on seated players.
-- Returns the gap list and populates bananaGaps + bananaGapsByPlayer globals.
function computeBananaGaps()
  bananaGaps = {}
  bananaGapsByPlayer = {}

  -- Filter SEAT_ORDER to seated players (real + test)
  local seatedInOrder = {}
  for _, color in ipairs(SEAT_ORDER) do
    if isPlayerSeated(color) then
      table.insert(seatedInOrder, color)
    end
  end

  if #seatedInOrder < 2 then return bananaGaps end

  -- Build circular gaps: between each adjacent pair, wrapping last→first
  for i = 1, #seatedInOrder do
    local nextIdx = (i % #seatedInOrder) + 1
    local gap = {
      left = seatedInOrder[i],
      right = seatedInOrder[nextIdx],
    }
    -- Last gap wraps from last player back to first — needs mirror tiles
    if i == #seatedInOrder then
      gap.isWrap = true
    end
    table.insert(bananaGaps, gap)
  end

  -- Build reverse lookup: player → { leftGapIndex, rightGapIndex }
  for gapIdx, gap in ipairs(bananaGaps) do
    -- Right player's left gap is this gap
    if not bananaGapsByPlayer[gap.right] then
      bananaGapsByPlayer[gap.right] = {}
    end
    bananaGapsByPlayer[gap.right].leftGapIndex = gapIdx

    -- Left player's right gap is this gap
    if not bananaGapsByPlayer[gap.left] then
      bananaGapsByPlayer[gap.left] = {}
    end
    bananaGapsByPlayer[gap.left].rightGapIndex = gapIdx
  end

  return bananaGaps
end

function getBananaGapPosition(leftColor, rightColor, tileColumn)
  local leftPos = playerParameters[leftColor].namePlatePosition
  local rightPos = playerParameters[rightColor].namePlatePosition
  -- Use the lower Z (closer to center) of the two players to avoid overlapping corner nameplates
  local baseZ = math.min(leftPos.z, rightPos.z)
  local twoHandShift = FLAGS.TwoHand and playerChipSpacePositionOffset.z or 0
  return {
    x = (leftPos.x + rightPos.x) / 2,
    y = deckTileBasePosition.y - 0.2,
    z = baseZ + specialModeFirstTileZOffset + (tileColumn - 1) * bananaColumnSpacingZ + twoHandShift
  }
end

-- Returns the wrap gap position: tiles placed at the outer edge of the specified end player.
-- direction: -1 = to the left (for the leftmost player), +1 = to the right (for the rightmost player)
-- neighborColor: the next seat beyond edgeColor (e.g. Teal/Brown), used to avoid nameplate overlap
function getBananaWrapPosition(edgeColor, tileColumn, direction, neighborColor)
  local edgePos = playerParameters[edgeColor].namePlatePosition
  -- Offset by half the normal gap width in the outward direction
  local offsetX = direction * 3.8
  local baseZ = edgePos.z
  if neighborColor and playerParameters[neighborColor] then
    baseZ = math.min(baseZ, playerParameters[neighborColor].namePlatePosition.z)
  end
  local twoHandShift = FLAGS.TwoHand and playerChipSpacePositionOffset.z or 0
  return {
    x = edgePos.x + offsetX,
    y = deckTileBasePosition.y - 0.2,
    z = baseZ + specialModeFirstTileZOffset + (tileColumn - 1) * bananaColumnSpacingZ + twoHandShift
  }
end

-- Returns the outer neighbor color in SEAT_ORDER for wrap gap positioning.
-- direction: -1 = previous seat (toward Teal), +1 = next seat (toward Brown)
function getBananaOuterNeighbor(color, direction)
  for i, c in ipairs(SEAT_ORDER) do
    if c == color then
      local ni = ((i - 1 + direction) % #SEAT_ORDER) + 1
      return SEAT_ORDER[ni]
    end
  end
  return nil
end

------------------------------------
--- Banana Split: Tile Spawning
------------------------------------

-- Spawns community tiles between each pair of adjacent seated players.
function communityCreateTilesBanana()
  local gaps = computeBananaGaps()
  if #gaps < 2 then return end

  local mode = getGameMode()
  local flopCards = mode.flopCards
  local turnCards = mode.turnCards
  local riverCards = mode.riverCards

  communityFirstActiveRound = 2 -- no pocket cards in Banana Split

  for gapIdx, gap in ipairs(gaps) do
    local tileColumn = 0

    for i = 1, flopCards do
      tileColumn = tileColumn + 1
      if bagCommunityTiles[2] then
        bananaSpawnTile(gapIdx, gap.left, gap.right, 2, tileColumn, bagCommunityTiles[2])
      end
    end

    for i = 1, turnCards do
      tileColumn = tileColumn + 1
      if bagCommunityTiles[3] then
        bananaSpawnTile(gapIdx, gap.left, gap.right, 3, tileColumn, bagCommunityTiles[3])
      end
    end

    for i = 1, riverCards do
      tileColumn = tileColumn + 1
      if bagCommunityTiles[4] then
        bananaSpawnTile(gapIdx, gap.left, gap.right, 4, tileColumn, bagCommunityTiles[4])
      end
    end

    -- Wrap gap: spawn mirror tiles at the other end of the table
    if gap.isWrap then
      local mirrorColumn = 0
      for i = 1, flopCards do
        mirrorColumn = mirrorColumn + 1
        if bagCommunityTiles[2] then
          bananaSpawnMirrorTile(gapIdx, gap.left, gap.right, 2, mirrorColumn, bagCommunityTiles[2])
        end
      end
      for i = 1, turnCards do
        mirrorColumn = mirrorColumn + 1
        if bagCommunityTiles[3] then
          bananaSpawnMirrorTile(gapIdx, gap.left, gap.right, 3, mirrorColumn, bagCommunityTiles[3])
        end
      end
      for i = 1, riverCards do
        mirrorColumn = mirrorColumn + 1
        if bagCommunityTiles[4] then
          bananaSpawnMirrorTile(gapIdx, gap.left, gap.right, 4, mirrorColumn, bagCommunityTiles[4])
        end
      end
    end
  end
end

-- Spawns a single Banana Split community tile.
function bananaSpawnTile(gapIndex, leftColor, rightColor, tileRound, tileColumn, tileBag)
  if not tileBag then return nil end

  local gap = bananaGaps[gapIndex]
  local tilePosition
  if gap and gap.isWrap then
    local leftPos = playerParameters[leftColor].namePlatePosition
    local rightPos = playerParameters[rightColor].namePlatePosition
    if leftPos.x > rightPos.x then
      local neighbor = getBananaOuterNeighbor(leftColor, -1)
      tilePosition = getBananaWrapPosition(leftColor, tileColumn, 1, neighbor)
    else
      local neighbor = getBananaOuterNeighbor(leftColor, 1)
      tilePosition = getBananaWrapPosition(leftColor, tileColumn, -1, neighbor)
    end
  else
    tilePosition = getBananaGapPosition(leftColor, rightColor, tileColumn)
  end
  local tileRotation = { x = 0, y = 90, z = 0 }

  local newTile = tileBag.takeObject({
    position = tilePosition,
    rotation = tileRotation,
    smooth = false,
  })

  if newTile then
    newTile.setLock(true)
    newTile.setGMNotes("communityTile")
    newTile.interactable = DEFAULT_INTERACTABLE

    local scriptZonePosition = { tilePosition.x, tilePosition.y, tilePosition.z }
    local scriptZoneRotation = { 0, 0, 0 }
    local scriptZoneScale = communityScriptZoneScaleHorizontal

    local params = {
      type = "ScriptingTrigger",
      position = scriptZonePosition,
      rotation = scriptZoneRotation,
      scale = scriptZoneScale,
      sound = false,
      snap_to_grid = false,
      callback_function = function(obj)
        obj.setGMNotes("communityScriptZone")
        bananaAddTileToGUIDList(gapIndex, tileRound, tileColumn, newTile.getGUID(), obj.getGUID())
      end
    }
    spawnObject(params)
  end

  return newTile
end

-- Spawns a visual mirror tile for the wrap-around gap at the opposite end of the table.
function bananaSpawnMirrorTile(gapIndex, leftColor, rightColor, tileRound, tileColumn, tileBag)
  if not tileBag then return nil end

  local leftPos = playerParameters[leftColor].namePlatePosition
  local rightPos = playerParameters[rightColor].namePlatePosition
  local tilePosition
  if leftPos.x > rightPos.x then
    local neighbor = getBananaOuterNeighbor(rightColor, 1)
    tilePosition = getBananaWrapPosition(rightColor, tileColumn, -1, neighbor)
  else
    local neighbor = getBananaOuterNeighbor(rightColor, -1)
    tilePosition = getBananaWrapPosition(rightColor, tileColumn, 1, neighbor)
  end
  local tileRotation = { x = 0, y = 90, z = 0 }

  local newTile = tileBag.takeObject({
    position = tilePosition,
    rotation = tileRotation,
    smooth = false,
  })

  if newTile then
    newTile.setLock(true)
    newTile.setGMNotes("communityTile")
    newTile.addTag(TAGS.bananaClone)
    newTile.interactable = DEFAULT_INTERACTABLE

    bananaWrapMirrorTiles = bananaWrapMirrorTiles or {}
    bananaWrapMirrorTiles[gapIndex] = bananaWrapMirrorTiles[gapIndex] or {}
    bananaWrapMirrorTiles[gapIndex][tileRound] = bananaWrapMirrorTiles[gapIndex][tileRound] or {}
    bananaWrapMirrorTiles[gapIndex][tileRound][tileColumn] = newTile
  end

  return newTile
end

-- Registers a Banana Split tile in bananaGapTileGUIDs.
function bananaAddTileToGUIDList(gapIndex, tileRound, tileColumn, tileGUID, scriptZoneGUID)
  if not gapIndex or not tileRound or not tileColumn or not tileGUID then return end

  bananaGapTileGUIDs[gapIndex] = bananaGapTileGUIDs[gapIndex] or {}
  bananaGapTileGUIDs[gapIndex][tileRound] = bananaGapTileGUIDs[gapIndex][tileRound] or {}
  bananaGapTileGUIDs[gapIndex][tileRound][tileColumn] = bananaGapTileGUIDs[gapIndex][tileRound][tileColumn] or {}
  table.insert(bananaGapTileGUIDs[gapIndex][tileRound][tileColumn], {
    guid = tileGUID,
    card = nil,
    scriptZoneGUID = scriptZoneGUID,
  })
end

------------------------------------
--- Banana Split: Card Drawing & Collection
------------------------------------

-- Draws a card for a single Banana Split tile column.
-- For wrap gaps: clones the drawn card onto the mirror tile.
function bananaDrawCardsForColumn(gapIndex, currentRound, currentColumn)
  if not bananaGapTileGUIDs[gapIndex] or
      not bananaGapTileGUIDs[gapIndex][currentRound] or
      not bananaGapTileGUIDs[gapIndex][currentRound][currentColumn] then
    return
  end

  for _, tileData in ipairs(bananaGapTileGUIDs[gapIndex][currentRound][currentColumn]) do
    local tileObj = getObjectFromGUID(tileData.guid)
    if tileObj then
      local drawnCard = communityDrawCardSkipJoker(tileObj)
      if drawnCard then
        tileData.card = drawnCard

        -- Clone card to mirror tile if this is a wrap gap
        local mirrorTile = bananaWrapMirrorTiles[gapIndex]
            and bananaWrapMirrorTiles[gapIndex][currentRound]
            and bananaWrapMirrorTiles[gapIndex][currentRound][currentColumn]
        if mirrorTile and not mirrorTile.isDestroyed() then
          local capturedCard = drawnCard
          local capturedMirror = mirrorTile
          Wait.time(function()
            if capturedCard and not capturedCard.isDestroyed() then
              local mirrorPos = capturedMirror.getPosition()
              local mirrorRot = capturedMirror.getRotation()
              local clonedCard = capturedCard.clone({
                position = { mirrorPos.x, mirrorPos.y + 2, mirrorPos.z },
                rotation = { 0, mirrorRot.y, 0 },
              })
              if clonedCard then
                clonedCard.addTag(TAGS.bananaClone)
                if clonedCard.hasTag(TAGS.pokercard) then
                  clonedCard.removeTag(TAGS.pokercard)
                end
              end
            end
          end, 1.5)
        end
      end
    end
  end
end

-- Collects community cards per gap, then merges into per-player columns.
function collectBananaCommunityCards()
  bananaPlayerCommunityColumns = {}
  local collectedGuids = {}

  -- Step 1: collect columns per gap
  local gapColumns = {}
  for gapIndex, gapData in pairs(bananaGapTileGUIDs) do
    gapColumns[gapIndex] = {}
    for round, roundData in pairs(gapData) do
      for column, columnData in pairs(roundData) do
        local columnCards = collectCardsFromTileData(columnData, collectedGuids)
        if #columnCards > 0 then
          table.insert(gapColumns[gapIndex], columnCards)
        end
      end
    end
  end

  -- Step 2: merge left + right gap columns per player
  for color, gapInfo in pairs(bananaGapsByPlayer) do
    local playerColumns = {}
    if gapInfo.leftGapIndex and gapColumns[gapInfo.leftGapIndex] then
      for _, col in ipairs(gapColumns[gapInfo.leftGapIndex]) do
        table.insert(playerColumns, col)
      end
    end
    if gapInfo.rightGapIndex and gapColumns[gapInfo.rightGapIndex] then
      for _, col in ipairs(gapColumns[gapInfo.rightGapIndex]) do
        table.insert(playerColumns, col)
      end
    end
    bananaPlayerCommunityColumns[color] = playerColumns
  end
end

