-- Returns the world position for a 7-Card Stud community tile in front of a player.
function getStudTilePosition(color, tileColumn)
  local pos = playerParameters[color].namePlatePosition
  local twoHandShift = FLAGS.TwoHand and playerChipSpacePositionOffset.z or 0
  return {
    x = pos.x,
    y = deckTileBasePosition.y - 0.2,
    z = pos.z + specialModeFirstTileZOffset + (tileColumn - 1) * bananaColumnSpacingZ + twoHandShift
  }
end

-- Creates personal community tiles in front of each seated player.
function communityCreateTilesStud()
  local mode = getGameMode()
  local pocketCards = mode.pocketCards
  local flopCards = mode.flopCards
  local turnCards = mode.turnCards
  local riverCards = mode.riverCards

  -- Shift deck tile forward (negative Z) to avoid clipping with player community cards
  local deckNewPos = {
    x = deckTileBasePosition.x,
    y = deckTileBasePosition.y,
    z = deckTileBasePosition.z - 2
  }
  positionDeckAndRelatedTiles(deckNewPos)

  local seatedPlayers = getSeatedPlayers()

  for _, color in ipairs(seatedPlayers) do
    local tileColumn = 0

    if pocketCards > 0 then
      communityFirstActiveRound = 1
      for i = 1, pocketCards do
        tileColumn = tileColumn + 1
        if bagCommunityTiles[1] then
          studSpawnTile(color, 1, tileColumn, bagCommunityTiles[1])
        end
      end
    end

    for i = 1, flopCards do
      tileColumn = tileColumn + 1
      if bagCommunityTiles[2] then
        studSpawnTile(color, 2, tileColumn, bagCommunityTiles[2])
      end
    end

    for i = 1, turnCards do
      tileColumn = tileColumn + 1
      if bagCommunityTiles[3] then
        studSpawnTile(color, 3, tileColumn, bagCommunityTiles[3])
      end
    end

    for i = 1, riverCards do
      tileColumn = tileColumn + 1
      if bagCommunityTiles[4] then
        studSpawnTile(color, 4, tileColumn, bagCommunityTiles[4])
      end
    end
  end
end

-- Spawns a single 7-Card Stud community tile in front of a player.
function studSpawnTile(color, tileRound, tileColumn, tileBag)
  if not tileBag then return nil end

  local tilePosition = getStudTilePosition(color, tileColumn)
  local tileRotation = { x = 0, y = 90, z = 0 }

  local newTile = tileBag.takeObject({
    position = tilePosition,
    rotation = tileRotation,
    smooth = false,
  })

  if newTile then
    newTile.setLock(true)
    newTile.setGMNotes("communityTile")
    newTile.interactable = DEFAULT_INTERACTABLE

    local scriptZonePosition = { tilePosition.x, tilePosition.y, tilePosition.z }
    local scriptZoneRotation = { 0, 0, 0 }
    local scriptZoneScale = communityScriptZoneScaleHorizontal

    local capturedColor = color
    local params = {
      type = "ScriptingTrigger",
      position = scriptZonePosition,
      rotation = scriptZoneRotation,
      scale = scriptZoneScale,
      sound = false,
      snap_to_grid = false,
      callback_function = function(obj)
        obj.setGMNotes("communityScriptZone")
        studAddTileToGUIDList(capturedColor, tileRound, tileColumn, newTile.getGUID(), obj.getGUID())
      end
    }
    spawnObject(params)
  end

  return newTile
end

-- Registers a 7-Card Stud tile in studTileGUIDs.
function studAddTileToGUIDList(color, tileRound, tileColumn, tileGUID, scriptZoneGUID)
  if not color or not tileRound or not tileColumn or not tileGUID then return end

  studTileGUIDs[color] = studTileGUIDs[color] or {}
  studTileGUIDs[color][tileRound] = studTileGUIDs[color][tileRound] or {}
  studTileGUIDs[color][tileRound][tileColumn] = studTileGUIDs[color][tileRound][tileColumn] or {}
  table.insert(studTileGUIDs[color][tileRound][tileColumn], {
    guid = tileGUID,
    card = nil,
    scriptZoneGUID = scriptZoneGUID,
  })
end

------------------------------------
--- 7-Card Stud: Card Drawing & Collection
------------------------------------

-- Draws a card for a single 7-Card Stud tile column for a specific player.
-- Joker cards are discarded and a replacement card is drawn automatically.
function studDrawCardsForColumn(color, currentRound, currentColumn)
  if not studTileGUIDs[color] or
      not studTileGUIDs[color][currentRound] or
      not studTileGUIDs[color][currentRound][currentColumn] then
    return
  end

  for _, tileData in ipairs(studTileGUIDs[color][currentRound][currentColumn]) do
    local tileObj = getObjectFromGUID(tileData.guid)
    if tileObj then
      local drawnCard = communityDrawCardSkipJoker(tileObj)
      if drawnCard then
        tileData.card = drawnCard
      end
    end
  end
end

-- Collects community cards per player for 7-Card Stud.
-- Populates bananaPlayerCommunityColumns (reused for per-player evaluation).
function collectStudCommunityCards()
  bananaPlayerCommunityColumns = {}
  local collectedGuids = {}

  for color, playerData in pairs(studTileGUIDs) do
    local playerColumns = {}
    for round, roundData in pairs(playerData) do
      for column, columnData in pairs(roundData) do
        local columnCards = collectCardsFromTileData(columnData, collectedGuids)
        if #columnCards > 0 then
          table.insert(playerColumns, columnCards)
        end
      end
    end
    bananaPlayerCommunityColumns[color] = playerColumns
  end
end

